  "В этом уровне ты научишься здороваться и прощаться, представляться и спрашивать, как зовут человека, откуда он и где живёт. Заодно разберём глаголы sein и heißen и разницу между «ты» и «Вы».": "Bu dərsdə salamlaşmağı və sağollaşmağı, özünü təqdim etməyi, adamın adını, haradan olduğunu və harada yaşadığını soruşmağı öyrənəcəksən. Yanaşı sein və heißen feillərini, həmçinin «sən» və «Siz» arasındakı fərqi açacağıq.",
