  "Личные местоимения и глагол sein (быть)": "Şəxs əvəzlikləri və sein (olmaq) feili",
  "В немецком глагол «быть» никогда не пропускают: «Я Эмиль» = Ich bin Emil. Формы sein нужно просто выучить — они неправильные.\nВажно: du — «ты» (друзья, коллеги, молодёжь), Sie — вежливое «Вы» (незнакомые, старшие, официальные ситуации). Sie как «Вы» всегда пишется с большой буквы, а глагол при нём стоит в форме, как у wir/sie (они).": "Alman dilində «olmaq» feili heç vaxt buraxılmır: «Mən Emiləm» = Ich bin Emil. sein-in formalarını sadəcə əzbərləmək lazımdır — o, qaydasızdır.\nVacib: du — «sən» (dostlar, həmkarlar, gənclər), Sie — nəzakətli «Siz» (tanımadığın adamlar, yaşlılar, rəsmi vəziyyətlər). «Siz» mənasında Sie həmişə böyük hərflə yazılır, feil isə wir/sie (onlar) ilə eyni formada olur.",
