  "Вы господин Мюллер.": "Siz cənab Müllersiniz.",
  "Глаголы heißen, kommen, wohnen, sprechen": "heißen, kommen, wohnen, sprechen feilləri",
  "heißen — «зваться»: Ich heiße Emil = Меня зовут Эмиль. Обрати внимание: у du и er/sie/es форма одинаковая — heißt.\nkommen (aus) — «быть родом из», wohnen (in) — «жить в», sprechen — «говорить». У sprechen в формах du и er/sie/es меняется гласная: sprichst, spricht. Форма для Sie (Вы) всегда совпадает с инфинитивом.": "heißen — «adlanmaq»: Ich heiße Emil = Mənim adım Emildir. Diqqət et: du və er/sie/es-də forma eynidir — heißt.\nkommen (aus) — «haradansa olmaq», wohnen (in) — «harada yaşamaq», sprechen — «danışmaq». sprechen feilində du və er/sie/es formalarında sait dəyişir: sprichst, spricht. Sie (Siz) üçün forma həmişə məsdərlə eynidir.",
  "Меня зовут Эмиль, и я из Азербайджана.": "Mənim adım Emildir və mən Azərbaycandanam.",
  "Ты живёшь в Берлине.": "Sən Berlində yaşayırsan.",
