  "Вопросы с wie, woher, wo, was": "wie, woher, wo, was ilə suallar",
  "Вопросительное слово стоит на первом месте, глагол — на втором, потом подлежащее: Wie heißt du? Woher kommst du? Wo wohnst du?\nwie — «как», woher — «откуда», wo — «где», was — «что». Обрати внимание, что после woher идёт kommen aus, а после wo — wohnen in.": "Sual sözü birinci yerdə, feil ikinci, sonra mübtəda gəlir: Wie heißt du? Woher kommst du? Wo wohnst du?\nwie — «necə», woher — «haradan», wo — «harada», was — «nə». Diqqət et: woher-dən sonra kommen aus, wo-dan sonra isə wohnen in gəlir.",
