  "Ты пришёл на курсы немецкого в Берлине. Рядом сидит Мия. Познакомься с ней: скажи, как тебя зовут, откуда ты, где живёшь и на каких языках говоришь. В конце попрощайся.": "Berlində alman dili kursuna gəlmisən. Yanında Mia oturub. Onunla tanış ol: adını, haradan olduğunu, harada yaşadığını və hansı dillərdə danışdığını de. Sonda sağollaş.",
