  "медленно": "yavaş",
  "Помедленнее, пожалуйста!": "Bir az yavaş, zəhmət olmasa!",
  "Числа от 0 до 100": "0-dan 100-ə qədər rəqəmlər",
  "Числа 0–12 нужно просто запомнить. 13–19 строятся как «единица + zehn»: dreizehn, vierzehn (внимание: sechzehn, siebzehn). Десятки заканчиваются на -zig: zwanzig, vierzig (внимание: dreißig).\nСоставные числа читаются «наоборот»: сначала единицы, потом und, потом десятки. 21 = ein-und-zwanzig, 45 = fünf-und-vierzig. Всё пишется одним словом. Обрати внимание: внутри составного числа eins теряет -s: einundzwanzig, einunddreißig.": "0–12 rəqəmlərini sadəcə əzbərləmək lazımdır. 13–19 «təkrəqəm + zehn» kimi qurulur: dreizehn, vierzehn (diqqət: sechzehn, siebzehn). Onluqlar -zig ilə bitir: zwanzig, vierzig (diqqət: dreißig).\nMürəkkəb rəqəmlər «tərsinə» oxunur: əvvəlcə təklər, sonra und, sonra onluqlar. 21 = ein-und-zwanzig, 45 = fünf-und-vierzig. Hamısı bir söz kimi yazılır. Diqqət et: mürəkkəb rəqəmin içində eins -s hərfini itirir: einundzwanzig, einunddreißig.",
  "Число": "Rəqəm",
  "По-немецки": "Almanca",
  "Мой номер — 0176 24 80.": "Mənim nömrəm 0176 24 80-dır.",
  "Двадцать плюс пять — двадцать пять.": "İyirmi üstəgəl beş — iyirmi beş.",
  "Глагол haben (иметь)": "haben (malik olmaq) feili",
  "По-русски мы говорим «у меня есть», а по-немецки — «я имею»: Ich habe ein Handy. Глагол haben неправильный: в формах du и er/sie/es пропадает буква b (hast, hat).\nПосле haben стоит то, что ты имеешь: ein Handy, eine Frage, zwei Handys.": "Azərbaycanca «mənim … var» deyirik, almanca isə «mən … malikəm»: Ich habe ein Handy. haben feili qaydasızdır: du və er/sie/es formalarında b hərfi düşür (hast, hat).\nhaben-dən sonra sahib olduğun şey gəlir: ein Handy, eine Frage, zwei Handys.",
  "У меня есть мобильный телефон.": "Mənim mobil telefonum var.",
  "У тебя есть адрес электронной почты?": "Sənin e-poçt ünvanın var?",
  "У Мии есть вопрос.": "Mianın bir sualı var.",
  "У нас есть адрес в Берлине.": "Bizim Berlində ünvanımız var.",
  "Окончания глаголов, вопросы «да/нет» и алфавит": "Feil şəkilçiləri, «bəli/xeyr» sualları və əlifba",
  "У правильных глаголов (wohnen, kommen, buchstabieren) окончания всегда одинаковые: ich -e, du -st, er/sie/es -t, wir -en, ihr -t, sie/Sie -en. Слово man («люди вообще», безличное) ведёт себя как er: Wie schreibt man das?\nВопрос, на который отвечают «да» или «нет», начинается с глагола: Hast du ein Handy? – Ja. Bist du Emil? – Ja, ich bin Emil.\nАлфавит (как называются буквы): A а, B бе, C це, D де, E э, F эф, G ге, H ха, I и, J йот, K ка, L эль, M эм, N эн, O о, P пе, Q ку, R эр, S эс, T тэ, U у, V фау, W ве, X икс, Y ипсилон, Z цет. Ä а-умлаут, Ö о-умлаут, Ü у-умлаут, ß эс-цет. Спросить: Wie schreibt man das? — Ответ: Ich buchstabiere: E – M – I – L.\nСлова mein / dein / Ihr («мой / твой / Ваш») пока просто запомни в готовых фразах: Meine Nummer ist …, Wie ist deine Adresse? Подробно разберём их в уровне 3.": "Qaydalı feillərdə (wohnen, kommen, buchstabieren) şəkilçilər həmişə eynidir: ich -e, du -st, er/sie/es -t, wir -en, ihr -t, sie/Sie -en. man sözü («ümumiyyətlə adamlar», qeyri-müəyyən şəxs) er kimi davranır: Wie schreibt man das?\n«Bəli» və ya «xeyr» cavabı tələb edən sual feillə başlayır: Hast du ein Handy? – Ja. Bist du Emil? – Ja, ich bin Emil.\nƏlifba (hərflərin adları): A a, B be, C tse, D de, E e, F ef, G ge, H ha, I i, J yot, K ka, L el, M em, N en, O o, P pe, Q ku, R er, S es, T te, U u, V fau, W ve, X iks, Y üpsilon, Z tset. Ä a-umlaut, Ö o-umlaut, Ü u-umlaut, ß es-tset. Soruşmaq: Wie schreibt man das? — Cavab: Ich buchstabiere: E – M – I – L.\nmein / dein / Ihr («mənim / sənin / Sizin») sözlərini hələlik hazır ifadələrdə əzbərlə: Meine Nummer ist …, Wie ist deine Adresse? Onları 3-cü dərsdə ətraflı açacağıq.",
