  "Регистрация на курсах": "Kursa qeydiyyat",
  "Ты записываешься на курс немецкого. Мия заполняет анкету: скажи ей, сколько тебе лет, есть ли у тебя мобильный, назови номер телефона, e-mail и адрес, продиктуй имя по буквам.": "Alman dili kursuna yazılırsan. Mia anketi doldurur: ona neçə yaşın olduğunu, mobil telefonun olub-olmadığını de, telefon nömrəni, e-poçtunu və ünvanını söylə, adını hərf-hərf de.",
  "Да, у меня есть мобильный.": "Bəli, mobil telefonum var.",
