  "Семья и люди": "Ailə və insanlar",
  "На этом уровне ты научишься рассказывать о своей семье: кто есть кто, сколько им лет, кем они работают. Освоишь слова «мой», «твой», «его», «её», «наш» и научишься говорить «нет» по-немецки.": "Bu dərsdə ailən haqqında danışmağı öyrənəcəksən: kim kimdir, neçə yaşları var, kim kimi işləyir. «Mənim», «sənin», «onun», «bizim» sözlərini mənimsəyəcək və almanca «yox» deməyi öyrənəcəksən.",
