  "Сколько у тебя детей?": "Neçə uşağın var?",
  "Притяжательные артикли: mein, dein, sein, ihr, unser": "Yiyəlik artikllər: mein, dein, sein, ihr, unser",
  "Слова «мой», «твой», «его», «её», «наш» стоят перед существительным вместо артикля. Форма зависит от рода слова: для der и das — без окончания (mein Vater, mein Kind), для die и множественного числа добавляем -e (meine Mutter, meine Eltern). Внимание: sein = его, ihr = её.": "«Mənim», «sənin», «onun», «bizim» sözləri artiklin yerinə ismin qarşısında dayanır. Forma sözün cinsindən asılıdır: der və das üçün şəkilçisiz (mein Vater, mein Kind), die və cəm üçün -e əlavə edirik (meine Mutter, meine Eltern). Diqqət: sein = onun (kişi), ihr = onun (qadın).",
  "Чей?": "Kimin?",
  "die / мн. число": "die / cəm",
  "ich → мой": "ich → mənim",
  "du → твой": "du → sənin",
  "er → его": "er → onun (kişi)",
  "sie → её": "sie → onun (qadın)",
  "wir → наш": "wir → bizim",
  "Это мой папа.": "Bu mənim atamdır.",
  "Это твоя сестра?": "Bu sənin bacındır?",
  "Мия милая. Её брат врач.": "Mia mehribandır. Onun qardaşı həkimdir.",
  "Наши родители живут в Баку.": "Bizim valideynlərimiz Bakıda yaşayırlar.",
  "Отрицание: nicht и kein / keine": "İnkar: nicht və kein / keine",
  "Перед существительным «нет, никакой» — это kein (для der, das) или keine (для die и множественного числа): Ich habe keine Kinder. Всё остальное отрицаем словом nicht: глагол, прилагательное, имя или mein/dein: Ich arbeite nicht. Er ist nicht verheiratet. Das ist nicht mein Bruder. Здесь часто нужен глагол haben: Hast du Geschwister? — Nein, ich habe keine Geschwister. После haben слова с der меняют форму: Ich habe keinen Bruder — это выучим позже; на этом уровне с haben используем только keine: keine Schwester, keine Kinder, keine Geschwister.": "İsmin qarşısında «heç bir, yoxdur» — bu, kein (der, das üçün) və ya keine (die və cəm üçün) deməkdir: Ich habe keine Kinder. Qalan hər şeyi nicht sözü ilə inkar edirik: feili, sifəti, adı və ya mein/dein sözünü: Ich arbeite nicht. Er ist nicht verheiratet. Das ist nicht mein Bruder. Burada tez-tez haben feili lazım olur: Hast du Geschwister? — Nein, ich habe keine Geschwister. haben-dən sonra der ilə olan sözlər formasını dəyişir: Ich habe keinen Bruder — bunu sonra öyrənəcəyik; bu dərsdə haben ilə yalnız keine işlədirik: keine Schwester, keine Kinder, keine Geschwister.",
  "Что отрицаем": "Nəyi inkar edirik",
  "Отрицание": "İnkar",
  "существительное der / das (после ist)": "der / das ismi (ist-dən sonra)",
  "существительное die": "die ismi",
  "множественное число": "cəm",
  "глагол, прилагательное, имя": "feil, sifət, ad",
  "У меня нет братьев и сестёр.": "Mənim qardaş-bacım yoxdur.",
  "Мой дедушка не работает.": "Babam işləmir.",
  "Это не моя жена.": "Bu mənim arvadım deyil.",
  "Множественное число и вопросы wer / wie viele": "Cəm və wer / wie viele sualları",
  "У слов о семье множественное число часто образуется с умлаутом: der Bruder → die Brüder, die Mutter → die Mütter. Слова die Eltern и die Geschwister бывают только во множественном числе, поэтому с ними глагол тоже во множественном: Das sind meine Eltern. Вопрос «кто?» — wer, «сколько?» — wie viele. Профессии называем без артикля: Ich bin Programmierer. Женские профессии получают -in: Lehrerin, Ärztin, Studentin.": "Ailə sözlərində cəm tez-tez umlautla düzəlir: der Bruder → die Brüder, die Mutter → die Mütter. die Eltern və die Geschwister sözləri yalnız cəmdə olur, ona görə feil də cəmdə durur: Das sind meine Eltern. «Kim?» sualı — wer, «neçə?» — wie viele. Peşələri artiklsiz deyirik: Ich bin Programmierer. Qadın peşələri -in şəkilçisi alır: Lehrerin, Ärztin, Studentin.",
  "Единственное число": "Tək",
  "Множественное число": "Cəm",
  "Кто это? — Это моя бабушка.": "Bu kimdir? — Bu mənim nənəmdir.",
