  "Семейные фото": "Ailə şəkilləri",
  "Эмиль, это твоя семья?": "Emil, bu sənin ailəndir?",
  "Да, это мои родители. Моего папу зовут Рустам, мою маму зовут Алина.": "Bəli, bunlar mənim valideynlərimdir. Atamın adı Rüstəm, anamın adı Alinadır.",
  "А кто это? Это твоя жена?": "Bəs bu kimdir? Bu sənin arvadındır?",
  "Нет, я холост. Это моя сестра Дина.": "Xeyr, mən subayam. Bu mənim bacım Dinadır.",
  "Она очень милая. А братья у тебя есть?": "O, çox mehribandır. Bəs qardaşın var?",
  "Да, моего брата зовут Тимур. Ему 28 лет.": "Bəli, qardaşımın adı Timurdur. Onun 28 yaşı var.",
  "Кто он по профессии?": "Onun peşəsi nədir?",
  "Он инженер. А моя сестра студентка.": "O, mühəndisdir. Bacım isə tələbədir.",
  "А твои родители? Где они живут?": "Bəs valideynlərin? Onlar harada yaşayırlar?",
  "Они живут в Баку. Мой папа врач, а мама учительница.": "Onlar Bakıda yaşayırlar. Atam həkimdir, anam isə müəllimədir.",
  "Твоя семья большая! У меня нет братьев и сестёр, но у меня есть бабушка. Ей 80, и она очень добрая.": "Sənin ailən böyükdür! Mənim qardaş-bacım yoxdur, amma nənəm var. Onun 80 yaşı var və o, çox mehribandır.",
  "Здорово! Мою бабушку зовут Фатима, и она тоже живёт в Баку.": "Gözəldir! Mənim nənəmin adı Fatimədir və o da Bakıda yaşayır.",
  "Расскажи о своей семье": "Ailəndən danış",
  "Ты пьёшь кофе с Мией, и она спрашивает о твоей семье. Расскажи, есть ли у тебя братья и сёстры, как зовут родителей, сколько им лет, кем они работают и где живут. Скажи, женат ты или холост.": "Mia ilə qəhvə içirsən və o, ailən haqqında soruşur. Qardaş-bacın olub-olmadığını, valideynlərinin adını, neçə yaşları olduğunu, kim işlədiklərini və harada yaşadıqlarını danış. Evli, yoxsa subay olduğunu de.",
  "Моего папу зовут Рустам.": "Atamın adı Rüstəmdir.",
  "Моей маме 55 лет.": "Anamın 55 yaşı var.",
  "Мой папа работает врачом.": "Atam həkim işləyir.",
  "А как зовут твоих родителей?": "Bəs valideynlərinin adları nədir?",
