  "Еда и напитки": "Yemək və içkilər",
  "В этом уровне ты научишься заказывать еду и напитки в кафе, говорить о завтраке, обеде и ужине и рассказывать, что ты любишь и не любишь есть.": "Bu dərsdə kafedə yemək və içki sifariş etməyi, səhər yeməyi, nahar və şam yeməyi barədə danışmağı, nəyi sevib-sevmədiyini deməyi öyrənəcəksən.",
  "Вежливо заказать еду и напитки в кафе (Ich möchte …)": "Kafedə nəzakətlə yemək və içki sifariş etmək (Ich möchte …)",
