  "У каждого существительного есть род: der (мужской), die (женский), das (средний). Неопределённый артикль: ein (для der и das) и eine (для die).\nКогда ты что-то ешь, пьёшь, берёшь или хочешь, существительное стоит в винительном падеже (Akkusativ). Меняется только мужской род: ein → einen, kein → keinen. Женский и средний род не меняются.": "Hər ismin cinsi var: der (kişi), die (qadın), das (orta). Qeyri-müəyyən artikl: ein (der və das üçün) və eine (die üçün).\nNəyisə yeyəndə, içəndə, götürəndə və ya istəyəndə isim təsirlik halda (Akkusativ) durur. Yalnız kişi cinsi dəyişir: ein → einen, kein → keinen. Qadın və orta cins dəyişmir.",
  "Род": "Cins",
  "der (м.р.)": "der (kişi)",
  "die (ж.р.)": "die (qadın)",
  "das (ср.р.)": "das (orta)",
  "Это яблоко.": "Bu almadır.",
  "Эмиль ест суп.": "Emil şorba yeyir.",
  "Я не пью сок.": "Mən şirə içmirəm.",
  "möchten и gern / nicht gern / lieber": "möchten və gern / nicht gern / lieber",
  "möchten — вежливое «хотел бы». Так заказывают в кафе: Ich möchte einen Tee, bitte. Официант спрашивает: Was möchten Sie?\ngern = «с удовольствием, люблю»: Ich trinke gern Kaffee. nicht gern = «не люблю»: Ich esse nicht gern Suppe. lieber = «предпочитаю, охотнее»: Ich trinke lieber Tee. Эти слова стоят сразу после глагола.": "möchten — nəzakətli «istərdim». Kafedə belə sifariş verirlər: Ich möchte einen Tee, bitte. Ofisiant soruşur: Was möchten Sie?\ngern = «həvəslə, sevirəm»: Ich trinke gern Kaffee. nicht gern = «sevmirəm»: Ich esse nicht gern Suppe. lieber = «üstün tuturam, daha həvəslə»: Ich trinke lieber Tee. Bu sözlər feildən dərhal sonra durur.",
  "Что вы будете заказывать?": "Nə sifariş verəcəksiniz?",
  "Я хотел бы булочку с сыром.": "Mən pendirli bulka istərdim.",
  "Эмиль с удовольствием пьёт сок.": "Emil həvəslə şirə içir.",
  "Я предпочитаю салат.": "Mən salatı üstün tuturam.",
  "Глаголы essen, trinken, nehmen": "essen, trinken, nehmen feilləri",
  "trinken — правильный глагол, окончания ты уже знаешь: -e, -st, -t, -en.\nessen и nehmen — неправильные: в формах du и er/sie/es меняется гласная: du isst, er isst; du nimmst, er nimmt. Остальные формы обычные.": "trinken — qaydalı feildir, şəkilçiləri artıq bilirsən: -e, -st, -t, -en.\nessen və nehmen qaydasızdır: du və er/sie/es formalarında sait dəyişir: du isst, er isst; du nimmst, er nimmt. Qalan formalar adi qaydadadır.",
