  "Суп очень вкусный.": "Şorba çox dadlıdır.",
  "В кафе": "Kafedə",
  "Добрый день! Добро пожаловать! Что будете заказывать?": "Günortanız xeyir! Xoş gəlmisiniz! Nə sifariş verərsiniz?",
  "Добрый день. Меню, пожалуйста.": "Günortanız xeyir. Menyu, zəhmət olmasa.",
  "Пожалуйста. Хотите что-нибудь выпить?": "Buyurun. Nəsə içmək istəyirsiniz?",
  "Да, я хотел бы кофе с молоком.": "Bəli, mən südlü qəhvə istərdim.",
  "А что вы хотели бы поесть? У нас есть суп, салат и рис с колбасой.": "Bəs nə yemək istərdiniz? Bizdə şorba, salat və kolbasalı düyü var.",
  "Хм, я не люблю суп. Я лучше возьму салат.": "Hmm, mən şorbanı sevmirəm. Yaxşısı budur, salat götürüm.",
  "Хотите ещё булочку? Хлеб очень вкусный.": "Bir bulka da istəyirsiniz? Çörək çox dadlıdır.",
