  "Всё хорошо?": "Hər şey qaydasındadır?",
  "Да, всё очень вкусно. Счёт, пожалуйста.": "Bəli, hər şey çox dadlıdır. Hesab, zəhmət olmasa.",
  "Заказ в кафе": "Kafedə sifariş",
  "Ты в кафе в Берлине. Мия работает официанткой. Закажи напиток и что-нибудь поесть, скажи, что ты любишь и не любишь, а в конце попроси счёт.": "Berlində bir kafedəsən. Mia ofisiant işləyir. İçki və yeməli bir şey sifariş et, nəyi sevib-sevmədiyini de, sonda isə hesabı istə.",
  "Меню, пожалуйста.": "Menyu, zəhmət olmasa.",
  "Я люблю хлеб с сыром.": "Mən pendirli çörəyi sevirəm.",
  "Это очень вкусно.": "Bu, çox dadlıdır.",
  "Я хотел бы заплатить. Счёт, пожалуйста.": "Mən ödəmək istərdim. Hesab, zəhmət olmasa.",
  "Привет, Эмиль! Добро пожаловать! Что ты хотел бы выпить?": "Salam, Emil! Xoş gəlmisən! Nə içmək istərdin?",
  "Хорошо. С молоком?": "Yaxşı. Südlə?",
  "А что ты хотел бы поесть? У нас есть булочки, суп и салат.": "Bəs nə yemək istərdin? Bizdə bulka, şorba və salat var.",
  "Ты любишь суп?": "Şorbanı sevirsən?",
  "Вот, пожалуйста. Приятного аппетита!": "Buyurun. Nuş olsun!",
