  "Вот счёт. Спасибо, Эмиль! До скорого!": "Budur hesab. Sağ ol, Emil! Tezliklə görüşərik!",
  "Выбери правильные артикли: Ich möchte … Salat und … Wasser.": "Düzgün artiklləri seç: Ich möchte … Salat und … Wasser.",
  "Эмиль берёт булочку с колбасой.": "Emil kolbasalı bulka götürür.",
