  "Распорядок дня и время": "Gün rejimi və vaxt",
  "В этом уровне ты научишься называть время и рассказывать о своём дне: когда встаёшь, работаешь, отдыхаешь. Разберём отделяемые глаголы, дни недели и вопрос «Wann?».": "Bu dərsdə saatı deməyi və günündən danışmağı öyrənəcəksən: nə vaxt durursan, işləyirsən, dincəlirsən. Ayrılan prefiksli feilləri, həftənin günlərini və «Wann?» sualını açacağıq.",
