  "Сейчас половина восьмого (7:30).": "Saat səkkizin yarısıdır (7:30).",
  "Который час? Wie spät ist es? и вопрос Wann?": "Saat neçədir? Wie spät ist es? və Wann? sualı",
  "Спросить время: Wie spät ist es? / Wie viel Uhr ist es? Ответ: Es ist … Uhr.\nОфициально (на вокзале, по радио) считают до 24: Es ist vierzehn Uhr dreißig (14:30). В разговоре считают до 12 и используют halb, Viertel, nach, vor. halb drei = 14:30 — как по-русски «половина третьего»: называем следующий час.\nВопрос о времени события: Wann? Отвечаем: um + время (um acht Uhr), am + день или часть дня (am Montag, am Abend), von … bis … (von neun bis fünf).": "Vaxtı soruşmaq: Wie spät ist es? / Wie viel Uhr ist es? Cavab: Es ist … Uhr.\nRəsmi şəkildə (vağzalda, radioda) 24-ə qədər sayırlar: Es ist vierzehn Uhr dreißig (14:30). Danışıqda 12-yə qədər sayır və halb, Viertel, nach, vor işlədirlər. halb drei = 14:30 — azərbaycanca «üçün yarısı»: növbəti saatı deyirik.\nHadisənin vaxtı haqqında sual: Wann? Cavab veririk: um + vaxt (um acht Uhr), am + gün və ya günün hissəsi (am Montag, am Abend), von … bis … (von neun bis fünf).",
  "Время": "Vaxt",
  "Официально": "Rəsmi",
  "Разговорно": "Danışıqda",
  "Который час? — Половина десятого (9:30).": "Saat neçədir? — Onun yarısı (9:30).",
  "Когда начинается курс? — В четверть десятого (9:15).": "Kurs nə vaxt başlayır? — Doqquzun on beşində (9:15).",
  "В понедельник я работаю с девяти до пяти.": "Bazar ertəsi doqquzdan beşə qədər işləyirəm.",
  "Вечером у меня встреча.": "Axşam görüşüm var.",
  "Отделяемые глаголы: aufstehen, anfangen, einkaufen, fernsehen, anrufen": "Ayrılan prefiksli feillər: aufstehen, anfangen, einkaufen, fernsehen, anrufen",
  "У этих глаголов ударная приставка (auf-, an-, ein-, fern-). В предложении приставка отделяется и уходит в самый конец: aufstehen → Ich stehe um sieben auf. Спрягается только основа глагола.\nВ вопросе то же самое: Wann stehst du auf? Rufst du deine Mutter an?\nОбрати внимание: anfangen — неправильный глагол (du fängst an, er fängt an), fernsehen спрягается как sehen (du siehst fern, er sieht fern).": "Bu feillərin vurğulu prefiksi var (auf-, an-, ein-, fern-). Cümlədə prefiks ayrılır və ən sona gedir: aufstehen → Ich stehe um sieben auf. Yalnız feilin kökü təsriflənir.\nSualda da eynidir: Wann stehst du auf? Rufst du deine Mutter an?\nDiqqət et: anfangen qaydasız feildir (du fängst an, er fängt an), fernsehen isə sehen kimi təsriflənir (du siehst fern, er sieht fern).",
  "Инфинитив": "Məsdər",
  "Эмиль встаёт в половине седьмого.": "Emil yeddinin yarısında durur.",
  "Работа начинается в девять часов.": "İş saat doqquzda başlayır.",
  "В субботу мы делаем покупки.": "Şənbə günü alış-veriş edirik.",
  "Ты смотришь телевизор вечером?": "Axşam televizora baxırsan?",
  "Порядок слов: время в начале. Глаголы schlafen и fahren": "Söz sırası: vaxt əvvəldə. schlafen və fahren feilləri",
  "В немецком предложении глагол всегда стоит на втором месте. Если ты начинаешь предложение со времени (Am Montag, Um acht, Heute), то подлежащее уходит на место после глагола: Am Montag arbeite ich. Оба варианта верны: Ich arbeite am Montag. = Am Montag arbeite ich.\nГлаголы schlafen и fahren меняют a → ä в формах du и er/sie/es: du schläfst, er fährt. Остальные формы регулярные.": "Alman cümləsində feil həmişə ikinci yerdə durur. Cümləyə vaxtla başlasan (Am Montag, Um acht, Heute), mübtəda feildən sonrakı yerə keçir: Am Montag arbeite ich. Hər iki variant düzgündür: Ich arbeite am Montag. = Am Montag arbeite ich.\nschlafen və fahren feilləri du və er/sie/es formalarında a → ä dəyişir: du schläfst, er fährt. Qalan formalar qaydalıdır.",
  "В шесть часов я еду домой.": "Saat altıda evə gedirəm.",
  "В выходные Эмиль долго спит.": "Həftəsonu Emil uzun yatır.",
  "Когда ты едешь в Берлин?": "Nə vaxt Berlinə gedirsən?",
  "Как сказать «выходные»?": "«Həftəsonu» necə deyilir?",
  "das Wochenende — выходные, die Woche — неделя, der Sonntag — воскресенье.": "das Wochenende — həftəsonu, die Woche — həftə, der Sonntag — bazar günü.",
  "Es ist 8:00. Как это сказать?": "Es ist 8:00. Bunu necə demək olar?",
  "При указании времени говорят … Uhr: acht Uhr.": "Vaxt deyəndə … Uhr işlədilir: acht Uhr.",
  "первая половина дня": "günün birinci yarısı",
  "вторая половина дня": "günün ikinci yarısı",
  "7:30 — как это сказать разговорно?": "7:30 — danışıqda bunu necə demək olar?",
  "halb acht = 7:30 — как по-русски «половина восьмого»: называем следующий час.": "halb acht = 7:30 — azərbaycanca «səkkizin yarısı»: növbəti saatı deyirik.",
  "Сейчас четверть десятого (9:15).": "Saat doqquzun on beşi keçib (9:15).",
  "9:15 = Viertel nach neun — четверть ПОСЛЕ девяти.": "9:15 = Viertel nach neun — doqquzdan SONRA bir rüb.",
  "10:45 = без четверти одиннадцать = Viertel vor elf.": "10:45 = on birə on beş qalıb = Viertel vor elf.",
  "Я встаю в семь часов.": "Saat yeddidə dururam.",
  "aufstehen — приставка auf уходит в конец предложения.": "aufstehen — auf prefiksi cümlənin sonuna gedir.",
  "У меня обеденный перерыв в двенадцать.": "Saat on ikidə nahar fasiləm var.",
  "Во сколько начинается фильм?": "Film saat neçədə başlayır?",
  "Фильм начинается в половине девятого.": "Film doqquzun yarısında başlayır.",
  "Вечером Эмиль смотрит телевизор.": "Axşam Emil televizora baxır.",
  "fernsehen спрягается как sehen: er sieht … fern.": "fernsehen sehen kimi təsriflənir: er sieht … fern.",
  "Эмиль звонит своей маме.": "Emil anasına zəng edir.",
  "Когда начинается курс?": "Kurs nə vaxt başlayır?",
  "Во сколько начинается курс?": "Kurs saat neçədə başlayır?",
  "Когда начнётся курс?": "Kurs nə vaxt başlayacaq?",
  "Когда начинаются курсы?": "Kurslar nə vaxt başlayır?",
  "anfangen = начинаться": "anfangen = başlamaq",
  "schlafen: в форме du гласная a меняется на ä — du schläfst.": "schlafen: du formasında a saiti ä-yə dəyişir — du schläfst.",
  "В понедельник Эмиль едет в Берлин.": "Bazar ertəsi Emil Berlinə gedir.",
