  "звонить": "zəng etmək",
  "Который час?": "Saat neçədir?",
  "С днями недели и частями дня — am: am Montag, am Abend. С часами — um.": "Həftənin günləri və günün hissələri ilə — am: am Montag, am Abend. Saatlarla — um.",
  "Я работаю с девяти до пяти.": "Mən doqquzdan beşə qədər işləyirəm.",
  "von … bis … = с … до …": "von … bis … = …-dan …-ə qədər",
  "В понедельник я не работаю.": "Bazar ertəsi işləmirəm.",
  "Я завтракаю в восемь часов.": "Saat səkkizdə səhər yeməyi yeyirəm.",
  "У меня встреча в десять часов.": "Saat onda görüşüm var.",
