  "В шесть я еду домой.": "Saat altıda evə gedirəm.",
  "Время в начале — глагол на втором месте, потом подлежащее.": "Vaxt əvvəldədirsə — feil ikinci yerdə, sonra mübtəda.",
  "В выходные я долго сплю.": "Həftəsonu uzun yatıram.",
  "На выходных я сплю долго.": "Həftəsonlarında uzun yatıram.",
  "В выходные я сплю долго.": "Həftəsonu mən uzun yatıram.",
  "На выходных я долго сплю.": "Həftəsonlarında mən uzun yatıram.",
  "lange = долго": "lange = uzun müddət",
  "В понедельник я встаю рано.": "Bazar ertəsi tez dururam.",
  "Es ist 19:00. Официально это:": "Es ist 19:00. Rəsmi şəkildə bu:",
  "Официально считают до 24: 19:00 = neunzehn Uhr. Разговорно — sieben (am Abend).": "Rəsmi şəkildə 24-ə qədər sayırlar: 19:00 = neunzehn Uhr. Danışıqda — sieben (am Abend).",
  "Когда ты звонишь своей сестре?": "Bacına nə vaxt zəng edirsən?",
  "Когда ты встаёшь?": "Nə vaxt durursan?",
  "aufstehen — приставка в конец": "aufstehen — prefiks sona",
  "В какой день говорящий едет в Гамбург?": "Danışan hansı gün Hamburqa gedir?",
  "В четверг без четверти восемь я еду в Гамбург.": "Cümə axşamı səkkizə on beş qalmış Hamburqa gedirəm.",
  "Эмиль спит с одиннадцати до семи.": "Emil on birdən yeddiyə qədər yatır.",
  "В субботу я не работаю.": "Şənbə günü işləmirəm.",
  "Эмиль работает с восьми до четырёх.": "Emil səkkizdən dördə qədər işləyir.",
  "Эмиль работает с восьми до четырёх часов.": "Emil saat səkkizdən dördə qədər işləyir.",
  "Эмиль работает с 8 до 16.": "Emil 8-dən 16-ya qədər işləyir.",
  "Эмиль работает с 8 до 4.": "Emil 8-dən 4-ə qədər işləyir.",
  "von … bis = с … до": "von … bis = …-dan …-ə qədər",
  "Во вторник у меня встреча.": "Çərşənbə axşamı görüşüm var.",
  "Обычный день": "Adi bir gün",
  "Эмиль, когда ты встаёшь?": "Emil, nə vaxt durursan?",
  "Я встаю в половине седьмого. Это очень рано!": "Yeddinin yarısında dururam. Bu, çox tezdir!",
  "А когда начинается работа?": "Bəs iş nə vaxt başlayır?",
  "В девять. Я работаю с девяти до пяти.": "Doqquzda. Doqquzdan beşə qədər işləyirəm.",
  "У тебя есть обеденный перерыв?": "Nahar fasilən var?",
  "Да, с двенадцати до часа. В пять у меня конец рабочего дня.": "Bəli, on ikidən birə qədər. Saat beşdə iş günüm bitir.",
  "Что ты делаешь вечером?": "Axşam nə edirsən?",
  "Я делаю покупки, потом смотрю телевизор или звоню семье.": "Alış-veriş edirəm, sonra televizora baxıram və ya ailəmə zəng edirəm.",
  "А в выходные?": "Bəs həftəsonu?",
  "В субботу я долго сплю. В воскресенье еду в Потсдам.": "Şənbə günü uzun yatıram. Bazar günü Potsdama gedirəm.",
  "Здорово! У меня в воскресенье тоже выходной.": "Gözəldir! Mənim də bazar günü istirahətimdir.",
  "Отлично! Тогда поедем вместе.": "Əla! Onda birlikdə gedərik.",
  "Мой день": "Mənim günüm",
  "Мия спрашивает тебя о твоём дне. Скажи, который сейчас час, когда ты встаёшь, когда начинается работа, когда у тебя обед, что ты делаешь вечером и есть ли у тебя планы на выходные. Используй um … Uhr, am Montag, von … bis и отделяемые глаголы.": "Mia səndən günün barədə soruşur. Saatın neçə olduğunu, nə vaxt durduğunu, işin nə vaxt başladığını, naharının nə vaxt olduğunu, axşam nə etdiyini və həftəsonuna planın olub-olmadığını de. um … Uhr, am Montag, von … bis və ayrılan prefiksli feilləri işlət.",
  "Сейчас половина восьмого.": "Saat səkkizin yarısıdır.",
  "Работа начинается в девять.": "İş saat doqquzda başlayır.",
  "У меня обед с двенадцати до часа.": "Naharım on ikidən birə qədərdir.",
  "В пять у меня конец рабочего дня.": "Saat beşdə iş günüm bitir.",
  "В субботу у меня встреча.": "Şənbə günü görüşüm var.",
  "В воскресенье я долго сплю.": "Bazar günü uzun yatıram.",
  "Привет, Эмиль! Который сейчас час?": "Salam, Emil! Saat neçədir?",
  "А когда ты встаёшь в понедельник?": "Bəs bazar ertəsi nə vaxt durursan?",
  "Когда начинается твоя работа?": "İşin nə vaxt başlayır?",
  "Когда у тебя обеденный перерыв?": "Nahar fasilən nə vaxtdır?",
  "У тебя есть встреча на выходных?": "Həftəsonu görüşün var?",
  "Отлично, Эмиль! Спасибо. До понедельника, пока!": "Əla, Emil! Sağ ol. Bazar ertəsinə qədər, salamat qal!",
  "Es ist 14:30. Разговорно это:": "Es ist 14:30. Danışıqda bu:",
  "14:30 = половина третьего = halb drei.": "14:30 = üçün yarısı = halb drei.",
  "Эмиль встаёт без четверти семь.": "Emil yeddiyə on beş qalmış durur.",
  "С часами — um: um fünf Uhr.": "Saatlarla — um: um fünf Uhr.",
  "В субботу я делаю покупки.": "Şənbə günü alış-veriş edirəm.",
  "Ты слишком долго спишь! Уже десять часов.": "Sən həddən artıq uzun yatırsan! Artıq saat ondur.",
  "schlafen: du schläfst (a → ä, окончание -st).": "schlafen: du schläfst (a → ä, şəkilçi -st).",
  "6:45 (без четверти семь)": "6:45 (yeddiyə on beş qalıb)",
