  "7:55 (без пяти восемь)": "7:55 (səkkizə beş dəqiqə qalıb)",
  "Когда встреча?": "Görüş nə vaxtdır?",
  "Моя встреча в среду в четверть одиннадцатого.": "Görüşüm çərşənbə günü onu on beş dəqiqə keçmişdir.",
  "Я работаю с понедельника по пятницу.": "Bazar ertəsindən cüməyə qədər işləyirəm.",
  "Я работаю с понедельника до пятницы.": "Mən bazar ertəsindən cümə gününə qədər işləyirəm.",
  "Какое предложение построено правильно?": "Hansı cümlə düzgün qurulub?",
  "Глагол на втором месте, приставка fern — в конце.": "Feil ikinci yerdə, fern prefiksi isə sonda.",
  "Дом и квартира": "Ev və mənzil",
  "В этом уровне ты научишься описывать квартиру: комнаты, мебель и где что стоит. Ты также поймёшь объявление о съёме жилья и сможешь спросить про аренду.": "Bu dərsdə mənzili təsvir etməyi öyrənəcəksən: otaqlar, mebel və nəyin harada durduğu. Həmçinin kirayə elanını başa düşəcək və kirayə haqqında soruşa biləcəksən.",
  "Назвать комнаты и мебель в квартире": "Mənzildəki otaqları və mebeli adlandırmaq",
