  "Сколько стоит аренда?": "Kirayə neçəyədir?",
  "Сколько стоит аренда? – 650 евро.": "Kirayə neçəyədir? – 650 avro.",
  "Es gibt + Akkusativ (есть, имеется)": "Es gibt + Akkusativ (var, mövcuddur)",
  "«Es gibt» значит «есть, имеется». После es gibt существительное стоит в Akkusativ.\nМеняется только мужской род: ein → einen, kein → keinen. Женский и средний род выглядят как в Nominativ.\nВопрос: Gibt es einen Balkon? – Ja, es gibt einen Balkon. / Nein, es gibt keinen Balkon.": "«Es gibt» — «var, mövcuddur» deməkdir. es gibt-dən sonra isim Akkusativdə durur.\nYalnız kişi cinsi dəyişir: ein → einen, kein → keinen. Qadın və orta cins Nominativdəki kimi görünür.\nSual: Gibt es einen Balkon? – Ja, es gibt einen Balkon. / Nein, es gibt keinen Balkon.",
  "отрицание, der": "inkar, der",
  "отрицание, die / das": "inkar, die / das",
  "Есть кухня?": "Mətbəx var?",
  "В квартире есть две комнаты.": "Mənzildə iki otaq var.",
  "Сада нет.": "Bağ yoxdur.",
  "Wo? Предлоги места + Dativ": "Wo? Yer sözönləri + Dativ",
  "На вопрос Wo? (где?) предлоги in, auf, neben, unter, hinter, vor, an, zwischen требуют Dativ.\nАртикль меняется: der → dem, die → der, das → dem.\nСокращения: in dem = im, an dem = am.\nПока мы учим только «где что находится» – без движения.": "Wo? (harada?) sualında in, auf, neben, unter, hinter, vor, an, zwischen sözönləri Dativ tələb edir.\nArtikl dəyişir: der → dem, die → der, das → dem.\nQısaltmalar: in dem = im, an dem = am.\nHələlik yalnız «nəyin harada olduğunu» öyrənirik — hərəkət olmadan.",
  "Предлог": "Sözönü",
  "Значение": "Mənası",
  "в": "-də, içində",
  "на": "üstündə",
  "рядом с": "yanında",
  "под": "altında",
  "за": "arxasında",
  "перед": "qarşısında",
  "у, на (вертикально)": "-də (şaquli səthdə)",
  "между": "arasında",
  "Стул между кроватью и шкафом.": "Stul çarpayı ilə şkafın arasındadır.",
  "Где шкаф? – За дверью.": "Şkaf haradadır? – Qapının arxasında.",
  "Прилагательное после sein и этажи": "sein-dən sonra sifət və mərtəbələr",
  "После глагола sein прилагательное не меняется: Das Zimmer ist hell. Die Wohnung ist hell. Die Zimmer sind hell.\nЭтаж: das Erdgeschoss – нижний этаж (у нас это «первый этаж»), im ersten Stock (1.), im zweiten Stock (2.), im dritten Stock (3.), im vierten Stock (4.).\nВнимание: в Германии счёт начинается с Erdgeschoss, поэтому im ersten Stock – это по-русски второй этаж. В этом курсе мы переводим по немецкому счёту: im ersten Stock = «на первом этаже» (т.е. на один этаж выше Erdgeschoss).": "sein feilindən sonra sifət dəyişmir: Das Zimmer ist hell. Die Wohnung ist hell. Die Zimmer sind hell.\nMərtəbə: das Erdgeschoss – zirzəmi üstü, ən aşağı mərtəbə (bizdə bu «birinci mərtəbə»dir), im ersten Stock (1.), im zweiten Stock (2.), im dritten Stock (3.), im vierten Stock (4.).\nDiqqət: Almaniyada sayım Erdgeschoss-dan başlayır, ona görə im ersten Stock bizim hesabla ikinci mərtəbədir. Bu kursda alman sayımı ilə tərcümə edirik: im ersten Stock = «birinci mərtəbədə» (yəni Erdgeschoss-dan bir mərtəbə yuxarı).",
  "Прилагательное": "Sifət",
  "Противоположность": "Əksi",
