  "ванная": "hamam",
  "коридор": "dəhliz",
  "Как по-немецки «квартира»?": "«Mənzil» almanca necədir?",
  "das Haus – дом, das Zimmer – комната, die Wohnung – квартира.": "das Haus – ev, das Zimmer – otaq, die Wohnung – mənzil.",
  "hell – светлый, dunkel – тёмный.": "hell – işıqlı, dunkel – qaranlıq.",
  "1500 евро – это дорого: teuer.": "1500 avro – bu bahadır: teuer.",
  "Есть стол.": "Stol var.",
  "der Tisch → после es gibt Akkusativ: einen Tisch.": "der Tisch → es gibt-dən sonra Akkusativ: einen Tisch.",
  "die Küche → eine, das Bad → ein: женский и средний род в Akkusativ не меняются.": "die Küche → eine, das Bad → ein: qadın və orta cins Akkusativdə dəyişmir.",
  "В квартире нет сада.": "Mənzilin bağı yoxdur.",
  "Anzeige: «2 Zimmer, Küche, Bad, Balkon. Miete: 700 Euro». Что есть в этой квартире?": "Anzeige: «2 Zimmer, Küche, Bad, Balkon. Miete: 700 Euro». Bu mənzildə nə var?",
  "две ванные": "iki hamam",
  "В объявлении: Balkon – балкон. Сада (Garten) нет, ванная одна.": "Elanda: Balkon – balkon. Bağ (Garten) yoxdur, hamam birdir.",
  "Стул рядом с кроватью.": "Stul çarpayının yanındadır.",
  "Стол у окна.": "Stol pəncərənin yanındadır.",
  "две": "iki",
  "Сколько комнат в квартире?": "Mənzildə neçə otaq var?",
  "В квартире три комнаты, кухня и ванная.": "Mənzildə üç otaq, mətbəx və hamam var.",
  "Стул рядом с окном.": "Stul pəncərənin yanındadır.",
  "Как сказать «Стул стоит между столом и кроватью»?": "«Stul stolla çarpayının arasındadır» necə deyilir?",
  "Квартира большая.": "Mənzil böyükdür.",
