  "Этаж: im ersten / zweiten / dritten Stock.": "Mərtəbə: im ersten / zweiten / dritten Stock.",
  "Аренда 300 евро. Это дёшево.": "Kirayə 300 avrodur. Bu, ucuzdur.",
  "300 евро – мало, значит billig (дёшево).": "300 avro – azdır, deməli billig (ucuz).",
  "Есть балкон и сад.": "Balkon və bağ var.",
  "Стол под окном.": "Stol pəncərənin altındadır.",
  "Диван перед окном.": "Divan pəncərənin qarşısındadır.",
  "Диван стоит перед окном.": "Divan pəncərənin qabağında durur.",
  "Диван находится перед окном.": "Divan pəncərənin önündə yerləşir.",
  "vor = перед": "vor = qarşısında",
  "Комната тёмная и дорогая.": "Otaq qaranlıq və bahadır.",
  "На каком этаже квартира?": "Mənzil hansı mərtəbədədir?",
  "Аренда 650 евро. Квартира на четвёртом этаже.": "Kirayə 650 avrodur. Mənzil dördüncü mərtəbədədir.",
  "Стул на кухне.": "Stul mətbəxdədir.",
  "Стул стоит на кухне.": "Stul mətbəxdə durur.",
  "Стул находится на кухне.": "Stul mətbəxdə yerləşir.",
  "in der Küche = на кухне (Dativ)": "in der Küche = mətbəxdə (Dativ)",
  "Я хочу снять квартиру.": "Mən mənzil kirayələmək istəyirəm.",
  "Осмотр квартиры": "Mənzilə baxış",
  "Добрый день! Вы Эмиль? Вот это квартира.": "Günortanız xeyir! Siz Emilsiniz? Budur mənzil.",
  "Добрый день, госпожа Шульц. Да, я Эмиль. О, квартира очень светлая!": "Günortanız xeyir, xanım Şuls. Bəli, mən Emiləm. Oo, mənzil çox işıqlıdır!",
  "Да. Есть две комнаты, кухня и ванная.": "Bəli. İki otaq, mətbəx və hamam var.",
  "А где спальня?": "Bəs yataq otağı haradadır?",
  "Здесь, рядом с гостиной. Кровать у окна.": "Burada, qonaq otağının yanında. Çarpayı pəncərənin yanındadır.",
  "Есть балкон?": "Balkon var?",
  "Да, балкон за кухней. И коридор большой.": "Bəli, balkon mətbəxin arxasındadır. Dəhliz də böyükdür.",
  "Очень хорошо. Сколько стоит аренда?": "Çox yaxşı. Kirayə neçəyədir?",
  "Аренда 700 евро. Квартира на третьем этаже.": "Kirayə 700 avrodur. Mənzil üçüncü mərtəbədədir.",
  "Это не дёшево, но квартира отличная. Я хочу снять эту квартиру.": "Bu ucuz deyil, amma mənzil əladır. Mən bu mənzili kirayələmək istəyirəm.",
  "Расскажи Мие о своей квартире": "Miaya mənzilindən danış",
  "Мия в гостях у тебя в Берлине и спрашивает про твою квартиру. Расскажи, где ты живёшь, сколько у тебя комнат, есть ли балкон, где стоит мебель, светлая ли квартира и сколько стоит аренда.": "Mia Berlində sənə qonaq gəlib və mənzilin barədə soruşur. Harada yaşadığını, neçə otağın olduğunu, balkonun olub-olmadığını, mebelin harada durduğunu, mənzilin işıqlı olub-olmadığını və kirayənin neçə olduğunu danış.",
  "В моей квартире две комнаты.": "Mənim mənzilimdə iki otaq var.",
  "Я живу на втором этаже.": "Mən ikinci mərtəbədə yaşayıram.",
  "Привет, Эмиль! Красивая квартира! Где ты сейчас живёшь?": "Salam, Emil! Gözəl mənzildir! Hazırda harada yaşayırsan?",
  "Сколько комнат в твоей квартире?": "Mənzilində neçə otaq var?",
  "Есть балкон или сад?": "Balkon və ya bağ var?",
  "А где твой диван?": "Bəs divanın haradadır?",
  "Квартира светлая или тёмная?": "Mənzil işıqlıdır, yoxsa qaranlıq?",
  "А сколько стоит аренда? Она дорогая?": "Bəs kirayə neçəyədir? Bahadır?",
  "Спасибо, Эмиль! Твоя квартира правда красивая. До скорого!": "Sağ ol, Emil! Mənzilin həqiqətən gözəldir. Tezliklə görüşərik!",
  "Стул перед дверью.": "Stul qapının qarşısındadır.",
  "Кухня маленькая, но светлая.": "Mətbəx kiçikdir, amma işıqlıdır.",
  "В квартире нет балкона.": "Mənzilin balkonu yoxdur.",
  "арендная плата": "kirayə haqqı",
  "три комнаты": "üç otaq",
  "Что есть в квартире?": "Mənzildə nə var?",
  "В квартире две комнаты и балкон. Аренда 800 евро.": "Mənzildə iki otaq və balkon var. Kirayə 800 avrodur.",
  "Эмиль живёт на третьем этаже.": "Emil üçüncü mərtəbədə yaşayır.",
  "Квартира дорогая и тёмная.": "Mənzil baha və qaranlıqdır.",
  "Эта квартира дорогая и тёмная.": "Bu mənzil baha və qaranlıqdır.",
  "Покупки и одежда": "Alış-veriş və geyim",
  "В этом уровне ты научишься делать покупки в супермаркете и в магазине одежды: спрашивать цену, называть количество, цвет и размер. Ты узнаешь, как образуется множественное число, как сказать «этот / эту / это» и как сказать, что тебе что-то нравится.": "Bu dərsdə supermarketdə və geyim mağazasında alış-veriş etməyi öyrənəcəksən: qiyməti soruşmaq, miqdarı, rəngi və ölçünü demək. Cəmin necə düzəldiyini, «bu» sözünü və nəyinsə xoşuna gəldiyini necə deməyi öyrənəcəksən.",
  "Спросить и назвать цену (Wie viel kostet…? Das kostet…)": "Qiyməti soruşmaq və demək (Wie viel kostet…? Das kostet…)",
  "Назвать одежду, цвета и размер": "Geyimi, rəngləri və ölçünü adlandırmaq",
  "Сказать «Мне нравится» и «Это подходит»": "«Xoşuma gəlir» və «Bu yaraşır» demək",
  "Образовать множественное число существительных": "İsimlərin cəmini düzəltmək",
  "супермаркет": "supermarket",
  "Эмиль делает покупки в супермаркете.": "Emil supermarketdə alış-veriş edir.",
  "Магазин очень большой.": "Mağaza çox böyükdür.",
  "покупать": "almaq",
  "Я покупаю брюки.": "Mən şalvar alıram.",
  "стоить": "dəyəri olmaq",
  "Сколько стоит рубашка?": "Köynək neçəyədir?",
  "цена": "qiymət",
