  "пальто": "palto",
  "Пальто дорогое.": "Palto bahadır.",
  "свитер": "sviter",
  "Я беру свитер.": "Mən sviter götürürəm.",
  "размер": "ölçü",
  "Какой у вас размер?": "Sizin ölçünüz nədir?",
  "цвет": "rəng",
  "Какого цвета куртка?": "Gödəkçə nə rəngdədir?",
  "красный": "qırmızı",
  "Куртка красная.": "Gödəkçə qırmızıdır.",
  "синий": "mavi",
  "Моя рубашка синяя.": "Mənim köynəyim mavidir.",
  "зелёный": "yaşıl",
  "Яблоко зелёное.": "Alma yaşıldır.",
