  "жёлтый": "sarı",
  "Пакет жёлтый.": "Torba sarıdır.",
  "примерять": "əyninə sınamaq",
  "Я примеряю брюки.": "Mən şalvarı əynimə sınayıram.",
  "подходить (по размеру)": "ölçüyə uyğun gəlmək",
  "Брюки хорошо сидят.": "Şalvar yaxşı oturur.",
  "нравиться": "xoşuna gəlmək",
  "Платье мне нравится.": "Paltar xoşuma gəlir.",
  "Множественное число существительных": "İsimlərin cəmi",
  "Во множественном числе артикль всегда die. Окончание нужно запоминать вместе со словом: -e, -(e)n, -er, -s, иногда добавляется умлаут (a → ä, o → ö, u → ü), а некоторые слова не меняются совсем. Слова на -e (die Hose, die Jacke) почти всегда получают -n. Иностранные слова (das T-Shirt) получают -s. Учи слово сразу с множественным числом: der Schuh – die Schuhe.": "Cəmdə artikl həmişə die olur. Şəkilçini sözlə birlikdə əzbərləmək lazımdır: -e, -(e)n, -er, -s, bəzən umlaut əlavə olunur (a → ä, o → ö, u → ü), bəzi sözlər isə heç dəyişmir. -e ilə bitən sözlər (die Hose, die Jacke) demək olar həmişə -n alır. Əcnəbi sözlər (das T-Shirt) -s alır. Sözü dərhal cəmi ilə birlikdə öyrən: der Schuh – die Schuhe.",
  "Ед. число": "Tək",
  "Мн. число": "Cəm",
  "умлаут": "umlaut",
  "умлаут + -e": "umlaut + -e",
  "без изменений": "dəyişiklik yoxdur",
  "Эмиль покупает две рубашки.": "Emil iki köynək alır.",
  "Пальто (мн. ч.) дорогие.": "Paltolar bahadır.",
  "После глаголов kaufen, nehmen, suchen, anprobieren, möchten стоит Akkusativ (вопрос «кого? что?»). Меняется только мужской род: der → den, dieser → diesen. Женский, средний род и множественное число остаются как в Nominativ. Слово dieser / diese / dieses («этот / эта / это») имеет те же окончания, что и der / die / das.": "kaufen, nehmen, suchen, anprobieren, möchten feillərindən sonra Akkusativ gəlir («kimi? nəyi?» sualı). Yalnız kişi cinsi dəyişir: der → den, dieser → diesen. Qadın, orta cins və cəm Nominativdəki kimi qalır. dieser / diese / dieses («bu») sözünün şəkilçiləri der / die / das ilə eynidir.",
  "мужской (Pullover)": "kişi cinsi (Pullover)",
  "женский (Hose)": "qadın cinsi (Hose)",
  "средний (Hemd)": "orta cins (Hemd)",
  "мн. число (Schuhe)": "cəm (Schuhe)",
  "Эмиль примеряет это пальто.": "Emil bu paltonu əyninə sınayır.",
  "Эта рубашка слишком маленькая.": "Bu köynək həddən artıq kiçikdir.",
  "Эти туфли стоят пятьдесят евро.": "Bu ayaqqabılar əlli avrodur.",
  "gefallen и passen + Dativ (mir, dir, Ihnen)": "gefallen və passen + Dativ (mir, dir, Ihnen)",
  "«Мне нравится» по-немецки — Das gefällt mir (дословно: это нравится мне). Вещь стоит в Nominativ, а человек — в Dativ: mir (мне), dir (тебе), Ihnen (Вам). Если вещей несколько, глагол во множественном числе: Die Schuhe gefallen mir. Так же работает passen: Die Hose passt mir (брюки мне подходят по размеру). Цвет говорим через sein: Die Jacke ist grün. Слово zu перед прилагательным значит «слишком»: Die Hose ist zu klein (слишком маленькие), der Mantel ist zu teuer (слишком дорогое).": "«Xoşuma gəlir» almanca Das gefällt mir olur (hərfən: bu mənə xoş gəlir). Əşya Nominativdə, adam isə Dativdə durur: mir (mənə), dir (sənə), Ihnen (Sizə). Əşya bir neçədirsə, feil cəmdə olur: Die Schuhe gefallen mir. passen də eyni cür işləyir: Die Hose passt mir (şalvar mənə ölçü olur). Rəngi sein ilə deyirik: Die Jacke ist grün. Sifətin qarşısındakı zu «həddən artıq» deməkdir: Die Hose ist zu klein (həddən artıq kiçik), der Mantel ist zu teuer (həddən artıq baha).",
  "Кому?": "Kimə?",
  "Пальто мне нравится.": "Palto xoşuma gəlir.",
  "Тебе нравится футболка, Эмиль?": "Futbolka xoşuna gəlir, Emil?",
  "Туфли мне не подходят.": "Ayaqqabılar mənə ölçü olmur.",
  "Как сказать «брюки»?": "«Şalvar» necə deyilir?",
  "die Hose — брюки, das Hemd — рубашка, die Jacke — куртка.": "die Hose — şalvar, das Hemd — köynək, die Jacke — gödəkçə.",
  "Что значит «das Kleid»?": "«das Kleid» nə deməkdir?",
  "das Kleid — платье, der Mantel — пальто.": "das Kleid — paltar, der Mantel — palto.",
  "Сколько это стоит?": "Bu neçəyədir?",
  "Сколько стоит куртка?": "Gödəkçə neçəyədir?",
  "die Jacke — она (3-е лицо, ед. число) → kostet.": "die Jacke — o (III şəxs, tək) → kostet.",
  "Das kostet 12,50 €. Как это сказать?": "Das kostet 12,50 €. Bunu necə demək olar?",
