  "Брюки не подходят по размеру.": "Şalvar ölçüyə görə uyğun gəlmir.",
  "Эти брюки не подходят.": "Bu şalvar ölçü olmur.",
  "Брюки не сидят.": "Şalvar oturmur.",
  "passen = подходить по размеру": "passen = ölçüyə uyğun gəlmək",
  "В магазине одежды": "Geyim mağazasında",
  "Добрый день! Что вы ищете?": "Günortanız xeyir! Nə axtarırsınız?",
  "Добрый день. Я ищу куртку.": "Günortanız xeyir. Mən gödəkçə axtarıram.",
  "Размер M. И я хочу её синего цвета.": "M ölçüsü. Onu mavi rəngdə istəyirəm.",
  "Вот синяя куртка. Она вам нравится?": "Budur mavi gödəkçə. Xoşunuza gəlir?",
  "Да, она мне нравится. Я её примерю.": "Bəli, xoşuma gəlir. Onu əynimə sınayacağam.",
  "Ну как? Куртка подходит?": "Necədir? Gödəkçə ölçü olur?",
  "Да, она хорошо сидит. Сколько она стоит?": "Bəli, yaxşı oturur. Neçəyədir?",
  "Она стоит 49 евро 90 центов.": "O, 49 avro 90 sentdir.",
  "Хорошо, я беру куртку. Где касса?": "Yaxşı, gödəkçəni götürürəm. Kassa haradadır?",
  "Касса там впереди. Хотите пакет?": "Kassa orada, qabaqdadır. Torba istəyirsiniz?",
  "Да, пожалуйста. Большое спасибо!": "Bəli, zəhmət olmasa. Çox sağ olun!",
  "Покупка свитера": "Sviter almaq",
  "Ты с Мией в магазине одежды в Берлине. Ты ищешь свитер. Скажи, что ты ищешь, какой цвет тебе нравится и какой у тебя размер. Примерь свитер, скажи, подходит ли он и нравится ли тебе, и реши, берёшь ли ты его.": "Mia ilə Berlində geyim mağazasındasan. Sviter axtarırsan. Nə axtardığını, hansı rəngin xoşuna gəldiyini və ölçünü de. Sviteri əyninə sına, ölçü olub-olmadığını və xoşuna gəlib-gəlmədiyini de, sonra onu götürüb-götürməyəcəyinə qərar ver.",
  "Я ищу свитер.": "Mən sviter axtarıram.",
  "У меня размер M.": "Mənim ölçüm M-dir.",
  "Мне нравится синий.": "Mavi xoşuma gəlir.",
  "Сколько стоит свитер?": "Sviter neçəyədir?",
  "Он хорошо сидит.": "Yaxşı oturur.",
  "Он слишком маленький.": "Həddən artıq kiçikdir.",
  "Это слишком дорого.": "Bu, həddən artıq bahadır.",
  "Привет, Эмиль! Мы в магазине. Что ты сегодня ищешь?": "Salam, Emil! Mağazadayıq. Bu gün nə axtarırsan?",
  "Вот свитер синего цвета и свитер зелёного цвета. Какой цвет тебе нравится?": "Budur mavi sviter və yaşıl sviter. Hansı rəng xoşuna gəlir?",
  "Хорошо. А какой у тебя размер?": "Yaxşı. Bəs ölçün nədir?",
  "Вот, пожалуйста. Примеришь свитер? Он подходит?": "Buyur. Sviteri əyninə sınayırsan? Ölçü olur?",
  "А свитер тебе нравится?": "Bəs sviter xoşuna gəlir?",
  "Он стоит тридцать евро. Ты берёшь свитер?": "O, otuz avrodur. Sviteri götürürsən?",
  "Отлично, Эмиль! Касса там впереди. Это было очень хорошо. Пока!": "Əla, Emil! Kassa orada, qabaqdadır. Çox yaxşı alındı. Salamat qal!",
