  "Куртка стоит 45 евро, а брюки стоят 30 евро.": "Gödəkçə 45 avro, şalvar isə 30 avrodur.",
  "das Kleid → dieses Kleid (средний род).": "das Kleid → dieses Kleid (orta cins).",
  "Размер 40 мне хорошо подходит.": "40 ölçüsü mənə yaxşı olur.",
