  "Пальто слишком дорогое.": "Palto həddən artıq bahadır.",
  "Это пальто слишком дорогое.": "Bu palto həddən artıq bahadır.",
  "Пальто слишком дорого.": "Palto olduqca bahadır.",
  "zu teuer = слишком дорого": "zu teuer = həddən artıq baha",
  "Город и дорога": "Şəhər və yol",
  "В этом уровне ты научишься ориентироваться в городе: спрашивать дорогу, понимать объяснения (налево, направо, прямо) и ездить на автобусе, метро и трамвае.": "Bu dərsdə şəhərdə istiqamət tapmağı öyrənəcəksən: yolu soruşmaq, izahatı başa düşmək (sola, sağa, düz) və avtobus, metro, tramvayla getmək.",
  "Спросить, где находится место и как туда добраться": "Bir yerin harada olduğunu və ora necə getməyi soruşmaq",
  "Понять и объяснить дорогу: links, rechts, geradeaus, bis zur Ampel": "Yolu başa düşmək və izah etmək: links, rechts, geradeaus, bis zur Ampel",
