  "пешком": "piyada",
  "Эмиль ходит на работу пешком.": "Emil işə piyada gedir.",
  "пересаживаться (делать пересадку)": "nəqliyyat dəyişmək",
  "На вокзале я пересаживаюсь.": "Vağzalda nəqliyyat dəyişirəm.",
  "выходить (из транспорта)": "düşmək (nəqliyyatdan)",
  "Мы выходим здесь.": "Biz burada düşürük.",
  "Повелительное наклонение нужно, чтобы объяснить дорогу. Вежливая форма (Sie): инфинитив + Sie: Gehen Sie links! Форма для друга (du): основа глагола без окончания -st и без местоимения: du gehst → Geh! У глаголов с изменением e → i это изменение остаётся: du nimmst → Nimm! А у глаголов с a → ä умлаут исчезает: du fährst → Fahr! У глаголов с отделяемой приставкой приставка идёт в конец: Steigen Sie um! / Steig um!": "Yolu izah etmək üçün əmr forması lazımdır. Nəzakətli forma (Sie): məsdər + Sie: Gehen Sie links! Dost forması (du): feilin kökü, -st şəkilçisi və əvəzlik olmadan: du gehst → Geh! e → i dəyişən feillərdə bu dəyişiklik qalır: du nimmst → Nimm! a → ä dəyişən feillərdə isə umlaut yox olur: du fährst → Fahr! Ayrılan prefiksli feillərdə prefiks sona gedir: Steigen Sie um! / Steig um!",
  "Sie-форма": "Sie forması",
  "du-форма": "du forması",
  "Идите прямо, а потом налево.": "Düz gedin, sonra isə sola.",
  "Садись на автобус, Эмиль!": "Avtobusa min, Emil!",
  "Пересядьте на вокзале.": "Vağzalda nəqliyyatı dəyişin.",
  "Как объяснить дорогу: links, rechts, geradeaus, bis zur…": "Yolu necə izah etməli: links, rechts, geradeaus, bis zur…",
  "Дорогу объясняют короткими фразами. bis zu + Dativ значит «до»: zum = zu dem (der/das), zur = zu der (die). an … vorbei значит «мимо»: an + Dativ (an der Post vorbei, am Museum vorbei). über значит «через» и требует Akkusativ: über die Straße, über den Platz. Порядок частей маршрута: zuerst (сначала) → dann (потом).": "Yolu qısa ifadələrlə izah edirlər. bis zu + Dativ «-ə qədər» deməkdir: zum = zu dem (der/das), zur = zu der (die). an … vorbei «yanından» deməkdir: an + Dativ (an der Post vorbei, am Museum vorbei). über «keçərək» deməkdir və Akkusativ tələb edir: über die Straße, über den Platz. Marşrutun hissələrinin sırası: zuerst (əvvəlcə) → dann (sonra).",
  "Немецкий": "Almanca",
  "Русский": "Azərbaycanca",
  "налево / направо": "sola / sağa",
  "до (чего-то)": "-ə qədər",
  "мимо …": "… yanından",
  "через": "keçərək",
  "Идите прямо до перекрёстка.": "Kəsişməyə qədər düz gedin.",
  "Потом идите мимо почты.": "Sonra poçtun yanından keçin.",
  "Поезжайте через мост, а потом направо.": "Körpüdən keçin, sonra isə sağa.",
  "Спросить, где что-то находится: Wo ist der Bahnhof? Спросить дорогу: Wie komme ich zu + Dativ? zum = zu dem (для der и das), zur = zu der (для die). На чём ты едешь — mit + Dativ: mit dem Bus (der), mit dem Taxi (das), mit der U-Bahn (die). Повторение: Gibt es hier + Akkusativ? — Gibt es hier eine Apotheke? Ja, es gibt eine Apotheke an der Ecke.": "Bir şeyin harada olduğunu soruşmaq: Wo ist der Bahnhof? Yolu soruşmaq: Wie komme ich zu + Dativ? zum = zu dem (der və das üçün), zur = zu der (die üçün). Nə ilə getdiyin — mit + Dativ: mit dem Bus (der), mit dem Taxi (das), mit der U-Bahn (die). Təkrar: Gibt es hier + Akkusativ? — Gibt es hier eine Apotheke? Ja, es gibt eine Apotheke an der Ecke.",
  "Артикль": "Artikl",
  "Извините, как мне добраться до вокзала?": "Bağışlayın, vağzala necə gedə bilərəm?",
  "Эмиль едет на работу на трамвае.": "Emil işə tramvayla gedir.",
  "Здесь есть банк?": "Burada bank var?",
