  "Потом налево, мимо почты. Вокзал справа.": "Sonra sola, poçtun yanından. Vağzal sağdadır.",
  "Это далеко пешком?": "Piyada uzaqdır?",
  "Пешком — десять минут. Или садитесь на автобус, линия 5.": "Piyada on dəqiqədir. Ya da avtobusa minin, 5 nömrəli xətt.",
  "А где остановка?": "Bəs dayanacaq haradadır?",
  "Вон там впереди, на перекрёстке. Билет купите в автобусе.": "Orada, qabaqda, kəsişmədə. Bileti avtobusda alarsınız.",
  "Отлично, я пойду пешком. Большое спасибо!": "Əla, piyada gedəcəyəm. Çox sağ olun!",
  "Не за что. До свидания!": "Dəyməz. Sağ olun!",
  "Как пройти к музею?": "Muzeyə necə getmək olar?",
  "Ты в Берлине и ищешь музей. Мия — местная, она объяснит тебе дорогу. Спроси, где музей, переспроси дорогу (bis zur Ampel? links?), скажи, идёшь ли ты пешком или едешь на транспорте, и попрощайся.": "Berlindəsən və muzeyi axtarırsan. Mia yerlidir, o, sənə yolu izah edəcək. Muzeyin harada olduğunu soruş, yolu bir də dəqiqləşdir (bis zur Ampel? links?), piyada, yoxsa nəqliyyatla gedəcəyini de və sağollaş.",
  "Извините, как мне пройти к музею?": "Bağışlayın, muzeyə necə gedə bilərəm?",
  "До светофора, а потом налево?": "Svetofora qədər, sonra isə sola?",
  "Я пойду пешком.": "Mən piyada gedəcəyəm.",
  "Привет, Эмиль! Что ты ищешь?": "Salam, Emil! Nə axtarırsan?",
  "Музей? Это недалеко. Ты пойдёшь пешком или поедешь на автобусе?": "Muzey? Uzaq deyil. Piyada gedəcəksən, yoxsa avtobusla?",
  "Хорошо. Иди прямо до светофора, а потом налево. Всё понятно?": "Yaxşı. Svetofora qədər düz get, sonra sola. Hər şey aydındır?",
  "Потом идёшь мимо церкви. Музей справа. Это далеко для тебя?": "Sonra kilsənin yanından keçirsən. Muzey sağdadır. Sənin üçün uzaqdır?",
  "Или ты едешь на метро. Станция вон там впереди. На чём ты поедешь?": "Ya da metro ilə gedirsən. Stansiya orada, qabaqdadır. Nə ilə gedəcəksən?",
  "На вокзале ты выходишь. А где ты купишь билет?": "Vağzalda düşürsən. Bəs bileti harada alacaqsan?",
  "Эмиль едет на трамвае к вокзалу.": "Emil vağzala tramvayla gedir.",
