  "umsteigen = пересаживаться": "umsteigen = nəqliyyat dəyişmək",
  "Выбери правильное предложение.": "Düzgün cümləni seç.",
  "Свободное время и хобби": "Boş vaxt və hobbi",
  "В этом уровне ты научишься рассказывать о хобби и спорте, приглашать друзей и отвечать на приглашения. Главная грамматика — модальные глаголы können, müssen, wollen.": "Bu dərsdə hobbi və idmandan danışmağı, dostları dəvət etməyi və dəvətə cavab verməyi öyrənəcəksən. Əsas qrammatika — modal feillər: können, müssen, wollen.",
  "Рассказать о своих хобби и о том, как часто ты занимаешься спортом": "Hobbilərindən və nə qədər tez-tez idmanla məşğul olduğundan danışmaq",
  "Использовать können, müssen, wollen в правильной форме и на правильном месте": "können, müssen, wollen feillərini düzgün formada və düzgün yerdə işlətmək",
  "Спросить «У тебя есть время / желание?» и пригласить друга": "«Vaxtın / həvəsin var?» soruşmaq və dostu dəvət etmək",
  "Принять приглашение или вежливо отказаться": "Dəvəti qəbul etmək və ya nəzakətlə imtina etmək",
  "хобби": "hobbi",
  "Моё хобби — футбол.": "Mənim hobbim futboldur.",
