  "Хочешь поиграть в футбол?": "Futbol oynamağa həvəsin var?",
  "фитнес-клуб": "idman klubu",
  "Я часто хожу в фитнес-клуб.": "Mən tez-tez idman klubuna gedirəm.",
  "команда": "komanda",
  "Наша команда очень хорошая.": "Bizim komandamız çox yaxşıdır.",
  "выигрывать": "qalib gəlmək",
  "Наша команда часто выигрывает.": "Komandamız tez-tez qalib gəlir.",
  "приглашать": "dəvət etmək",
  "Мия приглашает Эмиль.": "Mia Emili dəvət edir.",
