  "Может быть, в воскресенье?": "Bəlkə bazar günü?",
  "мочь, уметь": "bacarmaq, edə bilmək",
  "Я хорошо умею плавать.": "Mən yaxşı üzə bilirəm.",
  "должен, надо": "məcburdur, lazımdır",
  "Я должен работать в понедельник.": "Bazar ertəsi işləməliyəm.",
