  "часто": "tez-tez",
  "Мы часто ходим в кино.": "Biz tez-tez kinoya gedirik.",
  "иногда": "bəzən",
  "Иногда я хожу танцевать.": "Bəzən rəqsə gedirəm.",
  "никогда": "heç vaxt",
  "Я никогда не танцую.": "Mən heç vaxt rəqs etmirəm.",
  "Я люблю читать.": "Mən oxumağı sevirəm.",
  "Модальные глаголы können, müssen, wollen": "Modal feillər: können, müssen, wollen",
  "können = мочь, уметь; müssen = быть должным (надо); wollen = хотеть.\nВ формах ich и er/sie/es у них нет окончания, и меняется гласная: ich kann, ich muss, ich will.\nВажно: модальный глагол стоит на втором месте, а второй глагол — в инфинитиве в самом конце предложения. Это называется «рамка»: Ich kann heute nicht kommen. В вопросе модальный глагол стоит первым: Kannst du schwimmen?": "können = bacarmaq; müssen = məcbur olmaq (lazımdır); wollen = istəmək.\nich və er/sie/es formalarında şəkilçi olmur və sait dəyişir: ich kann, ich muss, ich will.\nVacib: modal feil ikinci yerdə durur, ikinci feil isə məsdər şəklində cümlənin lap sonunda. Buna «çərçivə» deyilir: Ich kann heute nicht kommen. Sualda modal feil birinci gəlir: Kannst du schwimmen?",
  "Я не могу сегодня прийти.": "Mən bu gün gələ bilmirəm.",
  "Эмиль должен работать в понедельник.": "Emil bazar ertəsi işləməlidir.",
  "Мы хотим пойти в кино.": "Biz kinoya getmək istəyirik.",
  "Ты хорошо умеешь плавать?": "Sən yaxşı üzə bilirsən?",
  "Приглашение: Hast du Zeit? Hast du Lust? gern + глагол": "Dəvət: Hast du Zeit? Hast du Lust? gern + feil",
  "Чтобы пригласить друга, спроси: Hast du Zeit? (У тебя есть время?) или Hast du Lust? (Хочешь? Есть желание?). После Lust идёт auf + Akkusativ: Hast du Lust auf ein Konzert?\nЧтобы сказать, что ты любишь что-то делать, поставь gern после глагола: Ich spiele gern Fußball.\nПринять приглашение: Ja, gern! Отказаться вежливо: Leider kann ich nicht. Ich muss arbeiten. Предложить другой день: Vielleicht am Samstag?": "Dostu dəvət etmək üçün soruş: Hast du Zeit? (Vaxtın var?) və ya Hast du Lust? (Həvəsin var?). Lust-dan sonra auf + Akkusativ gəlir: Hast du Lust auf ein Konzert?\nNəyisə etməyi sevdiyini demək üçün feildən sonra gern qoy: Ich spiele gern Fußball.\nDəvəti qəbul etmək: Ja, gern! Nəzakətlə imtina: Leider kann ich nicht. Ich muss arbeiten. Başqa gün təklif etmək: Vielleicht am Samstag?",
  "Фраза": "İfadə",
  "У тебя есть сегодня время?": "Bu gün vaxtın var?",
  "Хочешь в кино?": "Kinoya həvəsin var?",
  "Да, с удовольствием!": "Bəli, məmnuniyyətlə!",
  "К сожалению, я не могу.": "Təəssüf ki, bacarmıram.",
  "У тебя есть время в пятницу?": "Cümə günü vaxtın var?",
  "Мне хочется на вечеринку.": "Şənliyə getməyə həvəsim var.",
  "Эмиль любит плавать.": "Emil üzməyi sevir.",
  "Как часто? immer, oft, manchmal, nie, jeden Tag": "Nə qədər tez-tez? immer, oft, manchmal, nie, jeden Tag",
  "Эти слова отвечают на вопрос Wie oft? (Как часто?). Обычно они стоят сразу после глагола: Ich spiele oft Fußball. Их можно поставить и в начало — тогда глагол идёт вторым, а «я» после него: Manchmal spiele ich Fußball.\nnie уже содержит отрицание, поэтому nicht не нужно: Ich tanze nie.": "Bu sözlər Wie oft? (Nə qədər tez-tez?) sualına cavab verir. Adətən feildən dərhal sonra durur: Ich spiele oft Fußball. Onları əvvələ də qoymaq olar — onda feil ikinci, «mən» isə ondan sonra gəlir: Manchmal spiele ich Fußball.\nnie özü inkar daşıyır, ona görə nicht lazım deyil: Ich tanze nie.",
  "Как часто": "Nə qədər tez-tez",
  "всегда": "həmişə",
  "регулярно": "müntəzəm",
  "много раз": "çox dəfə",
  "время от времени": "vaxtaşırı",
  "Я часто играю в футбол.": "Mən tez-tez futbol oynayıram.",
  "Эмиль каждый день ходит в фитнес-клуб.": "Emil hər gün idman klubuna gedir.",
  "Мия никогда не танцует.": "Mia heç vaxt rəqs etmir.",
  "Как сказать «хобби» по-немецки?": "«Hobbi» almanca necə deyilir?",
  "das Hobby — хобби, die Freizeit — свободное время.": "das Hobby — hobbi, die Freizeit — boş vaxt.",
  "Что значит «Rad fahren»?": "«Rad fahren» nə deməkdir?",
  "das Rad — велосипед, fahren — ехать.": "das Rad — velosiped, fahren — sürmək.",
