  "Fußball spielen — играть в футбол; Sport — machen, а не spielen.": "Fußball spielen — futbol oynamaq; Sport ilə machen işlənir, spielen yox.",
  "ich → kann (без окончания).": "ich → kann (şəkilçisiz).",
  "Мия очень хорошо умеет танцевать.": "Mia çox yaxşı rəqs edə bilir.",
