  "Ты умеешь готовить?": "Yemək bişirə bilirsən?",
  "Модальный глагол на втором месте, инфинитив в конце.": "Modal feil ikinci yerdə, məsdər isə sonda.",
  "Эмиль не может сегодня прийти.": "Emil bu gün gələ bilmir.",
  "Я приглашаю Мию на вечеринку.": "Mən Mianı şənliyə dəvət edirəm.",
  "einladen — глагол с отделяемой приставкой: ich lade … ein.": "einladen — ayrılan prefiksli feildir: ich lade … ein.",
  "Как спросить «У тебя есть время?»": "«Vaxtın var?» necə soruşulur?",
  "die Zeit — время, die Lust — желание, das Geld — деньги.": "die Zeit — vaxt, die Lust — həvəs, das Geld — pul.",
  "Куда приглашают?": "Hara dəvət edirlər?",
  "в кино": "kinoya",
  "на концерт": "konsertə",
  "на вечеринку": "şənliyə",
  "Хочешь в пятницу на концерт?": "Cümə günü konsertə həvəsin var?",
  "Мне хочется на концерт.": "Konsertə getməyə həvəsim var.",
  "Мне хочется в кино.": "Kinoya getməyə həvəsim var.",
  "Как вежливо отказаться от приглашения?": "Dəvətdən necə nəzakətlə imtina etmək olar?",
  "leider — к сожалению; так вежливо говорят «нет».": "leider — təəssüf ki; belə nəzakətlə «yox» deyirlər.",
  "К сожалению, я не могу прийти.": "Təəssüf ki, gələ bilmirəm.",
  "Я, к сожалению, не могу прийти.": "Mən, təəssüf ki, gələ bilmirəm.",
  "Я не могу прийти, к сожалению.": "Gələ bilmirəm, təəssüf ki.",
  "К сожалению, я не могу приехать.": "Təəssüf ki, gələ bilməyəcəyəm.",
  "leider = к сожалению": "leider = təəssüf ki",
  "Мы хотим сегодня пойти в кино.": "Biz bu gün kinoya getmək istəyirik.",
  "Все семь дней недели — значит, jeden Tag (каждый день).": "Həftənin yeddi günü — deməli, jeden Tag (hər gün).",
  "Эмиль никогда не танцует. Он не умеет танцевать.": "Emil heç vaxt rəqs etmir. O, rəqs edə bilmir.",
  "nie — никогда; nicht после nie не нужно.": "nie — heç vaxt; nie-dən sonra nicht lazım deyil.",
  "Как часто он играет в футбол?": "O, nə qədər tez-tez futbol oynayır?",
  "Я часто играю в футбол. Моя команда очень хорошая.": "Mən tez-tez futbol oynayıram. Komandam çox yaxşıdır.",
  "Эмиль каждый день катается на велосипеде.": "Emil hər gün velosiped sürür.",
  "Мы хотим выиграть.": "Biz qalib gəlmək istəyirik.",
  "Я должен сегодня работать.": "Mən bu gün işləməliyəm.",
  "Я иногда хожу в фитнес-клуб.": "Mən bəzən idman klubuna gedirəm.",
  "Приглашение": "Dəvət",
  "Привет, Эмиль! Что ты делаешь в свободное время?": "Salam, Emil! Boş vaxtında nə edirsən?",
  "Я часто играю в футбол и хожу в фитнес-клуб.": "Mən tez-tez futbol oynayıram və idman klubuna gedirəm.",
  "Здорово! Я каждый день бегаю в парке.": "Gözəldir! Mən hər gün parkda qaçıram.",
  "Ты тоже умеешь плавать?": "Sən də üzə bilirsən?",
  "Да, но не очень хорошо. Скажи, у тебя есть время в субботу?": "Bəli, amma o qədər də yaxşı yox. De görüm, şənbə günü vaxtın var?",
  "В субботу? Да, возможно. А что в субботу?": "Şənbə? Bəli, ola bilər. Bəs şənbə günü nə var?",
  "Я устраиваю вечеринку. Я приглашаю тебя!": "Mən şənlik təşkil edirəm. Səni dəvət edirəm!",
  "Спасибо за приглашение! Когда начинается вечеринка?": "Dəvətə görə sağ ol! Şənlik nə vaxt başlayır?",
  "В восемь часов. Хочешь?": "Saat səkkizdə. Həvəsin var?",
  "Да, с удовольствием! Но в одиннадцать мне нужно идти домой.": "Bəli, məmnuniyyətlə! Amma saat on birdə evə getməliyəm.",
  "Не проблема. До субботы!": "Problem deyil. Şənbəyə qədər!",
  "До субботы, Мия!": "Şənbəyə qədər, Mia!",
  "Приглашение в кино": "Kinoya dəvət",
  "Ты встречаешь Мию после курсов. Она спрашивает о твоих хобби и приглашает тебя в кино. Расскажи, что ты любишь делать в свободное время, ответь, есть ли у тебя время, прими приглашение или предложи другой день, скажи, как часто ты занимаешься спортом.": "Kursdan sonra Mia ilə rastlaşırsan. O, hobbilərin barədə soruşur və səni kinoya dəvət edir. Boş vaxtında nə etməyi sevdiyini danış, vaxtın olub-olmadığını cavabla, dəvəti qəbul et və ya başqa gün təklif et, nə qədər tez-tez idmanla məşğul olduğunu de.",
  "Я должен работать.": "Mən işləməliyəm.",
  "Может быть, в субботу?": "Bəlkə şənbə günü?",
  "Я часто занимаюсь спортом.": "Mən tez-tez idmanla məşğul oluram.",
  "Привет, Эмиль! Что ты любишь делать в свободное время?": "Salam, Emil! Boş vaxtında nə etməyi sevirsən?",
  "Здорово! У тебя есть время в пятницу?": "Gözəldir! Cümə günü vaxtın var?",
  "Я хочу пойти в кино. Хочешь?": "Mən kinoya getmək istəyirəm. Həvəsin var?",
  "Отлично! Ты можешь прийти в семь часов?": "Əla! Saat yeddidə gələ bilərsən?",
  "Хорошо. А что ты делаешь на выходных?": "Yaxşı. Bəs həftəsonu nə edirsən?",
  "Как часто ты занимаешься спортом?": "Nə qədər tez-tez idmanla məşğul olursan?",
  "Здорово, Эмиль! Тогда до пятницы, в семь. Пока!": "Gözəldir, Emil! Onda cüməyə, saat yeddiyə qədər. Salamat qal!",
  "Emil und Mia = sie (они) → wollen.": "Emil und Mia = sie (onlar) → wollen.",
  "Ты хорошо умеешь танцевать? – Нет, я никогда не танцую.": "Sən yaxşı rəqs edə bilirsən? – Xeyr, mən heç vaxt rəqs etmirəm.",
  "После модального глагола — инфинитив: tanzen.": "Modal feildən sonra məsdər gəlir: tanzen.",
  "К сожалению, я должен сегодня работать.": "Təəssüf ki, bu gün işləməliyəm.",
  "Ты хочешь пойти в кино?": "Kinoya getmək istəyirsən?",
  "Ich komme gern — я с удовольствием приду.": "Ich komme gern — məmnuniyyətlə gələrəm.",
  "У меня никогда нет времени. Я работаю каждый день.": "Mənim heç vaxt vaxtım olmur. Hər gün işləyirəm.",
  "Работает каждый день — значит, времени нет никогда: nie.": "Hər gün işləyir — deməli, heç vaxt vaxtı yoxdur: nie.",
  "Когда играет команда?": "Komanda nə vaxt oynayır?",
