  "Инфинитив kochen стоит в самом конце предложения.": "kochen məsdəri cümlənin lap sonunda durur.",
  "Погода и времена года": "Hava və fəsillər",
  "В этом уровне ты научишься говорить о погоде, временах года, месяцах и датах. А ещё ты впервые расскажешь о прошлом: что ты делал вчера и на выходных (Perfekt с haben).": "Bu dərsdə hava, fəsillər, aylar və tarixlər barədə danışmağı öyrənəcəksən. Həmçinin ilk dəfə keçmişdən danışacaqsan: dünən və həftəsonu nə etdiyini (haben ilə Perfekt).",
  "Описать погоду: Es regnet, es ist kalt, es sind 20 Grad": "Havanı təsvir etmək: Es regnet, es ist kalt, es sind 20 Grad",
  "Назвать времена года, месяцы и дату (Heute ist der 3. Mai)": "Fəsilləri, ayları və tarixi demək (Heute ist der 3. Mai)",
