  "Сегодня прохладно.": "Bu gün sərindir.",
  "завтра (не путай с der Morgen — утро)": "sabah (der Morgen — səhər ilə qarışdırma)",
  "Завтра я играю в футбол.": "Sabah futbol oynayıram.",
  "Безличное es: Es regnet, es ist kalt": "Qeyri-müəyyən es: Es regnet, es ist kalt",
  "О погоде по-немецки говорят с безличным es (оно). В русском мы говорим «холодно», «идёт дождь» — без подлежащего, а в немецком подлежащее es обязательно: Es ist kalt. Es regnet.\nГлагол стоит на втором месте. Если предложение начинается с времени (Heute, Im Winter), es идёт после глагола: Heute regnet es. Im Winter ist es kalt.\nГрадусы: Es sind zwanzig Grad (глагол во множественном числе).": "Hava haqqında almanca qeyri-müəyyən es (o) ilə danışırlar. Azərbaycanca «soyuqdur», «yağış yağır» deyirik — mübtədasız, almancada isə es mübtədası mütləqdir: Es ist kalt. Es regnet.\nFeil ikinci yerdə durur. Cümlə vaxtla başlayırsa (Heute, Im Winter), es feildən sonra gəlir: Heute regnet es. Im Winter ist es kalt.\nDərəcə: Es sind zwanzig Grad (feil cəmdə).",
  "Идёт дождь.": "Yağış yağır.",
  "Идёт снег.": "Qar yağır.",
  "Холодно / тепло / жарко / прохладно.": "Soyuq / isti / qızmar / sərin.",
  "Солнечно / ветрено.": "Günəşli / küləkli.",
  "20 градусов.": "20 dərəcə.",
  "Светит солнце.": "Günəş parlayır.",
  "Какая сегодня погода? — Идёт дождь.": "Bu gün hava necədir? — Yağış yağır.",
  "Зимой холодно и идёт снег.": "Qışda soyuq olur və qar yağır.",
  "Сегодня только десять градусов.": "Bu gün cəmi on dərəcədir.",
  "Perfekt с haben: Ich habe gearbeitet": "haben ilə Perfekt: Ich habe gearbeitet",
  "Чтобы рассказать о прошлом, немцы используют Perfekt: haben (в нужной форме) + Partizip II в конце предложения. Это рамка: Ich habe gestern Fußball gespielt.\nПравильные глаголы образуют Partizip II так: ge- + основа + -t: machen → gemacht, spielen → gespielt. Если основа заканчивается на -t, добавляется -et: arbeiten → gearbeitet.\nНесколько важных глаголов неправильные — их надо запомнить: essen → gegessen, trinken → getrunken, sehen → gesehen.": "Keçmişdən danışmaq üçün almanlar Perfekt işlədir: haben (lazımi formada) + cümlənin sonunda Partizip II. Bu, çərçivədir: Ich habe gestern Fußball gespielt.\nQaydalı feillər Partizip II-ni belə düzəldir: ge- + kök + -t: machen → gemacht, spielen → gespielt. Kök -t ilə bitirsə, -et əlavə olunur: arbeiten → gearbeitet.\nBir neçə vacib feil qaydasızdır — onları əzbərləmək lazımdır: essen → gegessen, trinken → getrunken, sehen → gesehen.",
  "Что ты делал вчера?": "Dünən nə etmisən?",
  "Вчера я много работал.": "Dünən çox işləmişəm.",
  "На выходных Эмиль смотрел фильм.": "Həftəsonu Emil film baxıb.",
  "Мы пили кофе.": "Biz qəhvə içmişik.",
  "Когда? gestern, letzte Woche, am 3. Mai": "Nə vaxt? gestern, letzte Woche, am 3. Mai",
  "Слова времени для прошлого: gestern (вчера), letzte Woche (на прошлой неделе), am Wochenende (на выходных). Они часто стоят в начале: Gestern habe ich gekocht.\nМесяцы всегда с im: im Januar, im Mai. Вопрос о дате: Der Wievielte ist heute? Ответ: Heute ist der dritte Mai (3. Mai). С предлогом am окончание -en: am dritten Mai, am zwanzigsten Juli.\nПорядковые числа: 1.–19. → -te (der zweite, der vierte; особые: der erste, der dritte, der siebte), с 20. → -ste (der zwanzigste, der dreißigste).": "Keçmiş üçün vaxt sözləri: gestern (dünən), letzte Woche (keçən həftə), am Wochenende (həftəsonu). Onlar tez-tez əvvəldə durur: Gestern habe ich gekocht.\nAylar həmişə im ilə işlənir: im Januar, im Mai. Tarix sualı: Der Wievielte ist heute? Cavab: Heute ist der dritte Mai (3. Mai). am sözönü ilə şəkilçi -en olur: am dritten Mai, am zwanzigsten Juli.\nSıra sayları: 1.–19. → -te (der zweite, der vierte; xüsusi hallar: der erste, der dritte, der siebte), 20.-dən sonra → -ste (der zwanzigste, der dreißigste).",
