  "У тебя есть зонт?": "Çətirin var?",
  "Juni, Juli, August — какое это время года?": "Juni, Juli, August — bu hansı fəsildir?",
  "Июнь, июль, август — лето, der Sommer.": "İyun, iyul, avqust — yay, der Sommer.",
  "Осенью часто идёт дождь.": "Payızda tez-tez yağış yağır.",
  "Осенью часто идут дожди.": "Payızda tez-tez yağışlar olur.",
  "Осенью часто бывает дождь.": "Payızda tez-tez yağış olur.",
  "der Herbst = осень": "der Herbst = payız",
  "Какой месяц идёт после Juli?": "Juli-dən sonra hansı ay gəlir?",
  "Juli (июль) → August (август).": "Juli (iyul) → August (avqust).",
  "der Monat → die Monate (множественное число).": "der Monat → die Monate (cəm).",
  "Завтра тепло и солнечно.": "Sabah isti və günəşlidir.",
  "Завтра будет тепло и солнечно.": "Sabah isti və günəşli olacaq.",
