  "morgen = завтра": "morgen = sabah",
  "Как сказать «Сегодня третье мая»?": "«Bu gün mayın üçüdür» necə deyilir?",
  "Дата: der + порядковое число: der dritte Mai.": "Tarix: der + sıra sayı: der dritte Mai.",
  "У Эмиля день рождения 15 мая.": "Emilin ad günü mayın 15-idir.",
  "Дата с предлогом am: am fünfzehnten Mai.": "am sözönü ilə tarix: am fünfzehnten Mai.",
  "Как читается «am 20. Juli»?": "«am 20. Juli» necə oxunur?",
  "С 20 и дальше: -ste, после am → -sten: am zwanzigsten.": "20-dən sonra: -ste, am-dan sonra → -sten: am zwanzigsten.",
  "Выбери Partizip II от глагола machen.": "machen feilinin Partizip II formasını seç.",
  "Правильный глагол: ge- + mach + -t = gemacht.": "Qaydalı feil: ge- + mach + -t = gemacht.",
  "Вчера я играл в футбол.": "Dünən futbol oynamışam.",
