  "Вчера я готовил суп.": "Dünən şorba bişirmişəm.",
  "На выходных Эмиль много занимался.": "Həftəsonu Emil çox məşğul olub.",
  "Was hast du gestern gegessen? Какой ответ правильный?": "Was hast du gestern gegessen? Hansı cavab düzgündür?",
  "На выходных мы смотрели фильм.": "Həftəsonu film baxmışıq.",
