  "Что Эмиль вчера купил?": "Emil dünən nə alıb?",
  "Эмиль вчера вечером пил чай.": "Emil dünən axşam çay içib.",
  "Что говорящий делал на выходных?": "Danışan həftəsonu nə edib?",
  "Много работал": "Çox işləyib",
  "Смотрел фильм и ел пиццу": "Film baxıb və pizza yeyib",
  "Учил немецкий": "Alman dili öyrənib",
  "На прошлой неделе я много работал. На выходных я смотрел фильм и ел пиццу.": "Keçən həftə çox işləmişəm. Həftəsonu film baxmışam və pizza yemişəm.",
  "Что ты делал на выходных?": "Həftəsonu nə etmisən?",
  "Что ты делал в выходные?": "Həftəsonlarında nə etmisən?",
  "Чем ты занимался на выходных?": "Həftəsonu nə ilə məşğul olmusan?",
  "Что ты делала на выходных?": "Həftəsonu nələr etmisən?",
  "Вчера я учил немецкий.": "Dünən alman dili öyrənmişəm.",
  "Утро понедельника в офисе": "Bazar ertəsi səhəri ofisdə",
  "Привет, Эмиль! Что ты делал на выходных?": "Salam, Emil! Həftəsonu nə etmisən?",
  "Привет, Мия! Я играл в футбол и много готовил.": "Salam, Mia! Futbol oynamışam və çoxlu yemək bişirmişəm.",
  "Здорово! А какая сегодня погода?": "Gözəldir! Bəs bu gün hava necədir?",
  "Идёт дождь, и прохладно. Только двенадцать градусов.": "Yağış yağır və sərindir. Cəmi on iki dərəcə.",
  "О нет. У тебя есть зонт?": "Ay aman. Çətirin var?",
  "Да, вот. Вчера дождя не было.": "Bəli, budur. Dünən yağış yox idi.",
  "Осень пришла. Какое сегодня число?": "Payız gəlib. Bu gün ayın neçəsidir?",
  "Сегодня двадцатое сентября.": "Bu gün sentyabrın iyirmisidir.",
  "Ах да! В октябре часто холодно и ветрено.": "Ah, bəli! Oktyabrda tez-tez soyuq və küləkli olur.",
  "Зима мне не нравится. Мне нравится лето.": "Qış xoşuma gəlmir. Mənə yay xoşdur.",
  "Мне тоже! В июле тепло и солнечно. До завтра, Эмиль!": "Mənə də! İyulda isti və günəşli olur. Sabaha qədər, Emil!",
  "До завтра, Мия!": "Sabaha qədər, Mia!",
  "Погода и выходные": "Hava və həftəsonu",
  "Ты встречаешь Мию в понедельник. Расскажи ей, какая сегодня погода и сколько градусов, какое время года тебе нравится и что ты делал вчера и на выходных. В конце назови сегодняшнюю дату.": "Bazar ertəsi Mia ilə rastlaşırsan. Ona bu gün havanın necə olduğunu və neçə dərəcə olduğunu, hansı fəsli sevdiyini, dünən və həftəsonu nə etdiyini danış. Sonda bugünkü tarixi de.",
  "Холодно и ветрено.": "Soyuq və küləklidir.",
  "Пятнадцать градусов.": "On beş dərəcə.",
  "Мне нравится лето.": "Mənə yay xoşdur.",
  "На выходных я ел пиццу.": "Həftəsonu pizza yemişəm.",
  "Сегодня третье мая.": "Bu gün mayın üçüdür.",
  "Привет, Эмиль! Какая сегодня погода?": "Salam, Emil! Bu gün hava necədir?",
  "А сколько градусов?": "Bəs neçə dərəcədir?",
  "Какое время года тебе нравится?": "Hansı fəsil xoşuna gəlir?",
  "А что ты делал вчера?": "Bəs dünən nə etmisən?",
  "Интересно! Что ты ел на выходных?": "Maraqlıdır! Həftəsonu nə yemisən?",
  "А какое сегодня число?": "Bəs bu gün ayın neçəsidir?",
  "Отлично, Эмиль! Ты очень хорошо справился. До завтра!": "Əla, Emil! Çox yaxşı bacardın. Sabaha qədər!",
  "Wie ist das Wetter im Winter? Выбери верный ответ.": "Wie ist das Wetter im Winter? Düzgün cavabı seç.",
  "Зимой идёт снег и холодно.": "Qışda qar yağır və soyuq olur.",
  "Сегодня идёт дождь. Я беру зонт.": "Bu gün yağış yağır. Mən çətir götürürəm.",
