  "На выходных мы ели пиццу.": "Həftəsonu pizza yemişik.",
  "Что ты вчера купил?": "Dünən nə almısan?",
  "Какая погода сегодня?": "Bu gün hava necədir?",
  "Идёт дождь": "Yağış yağır",
  "Солнечно и тепло": "Günəşli və isti",
  "Идёт снег": "Qar yağır",
  "На прошлой неделе каждый день шёл дождь. Но сегодня солнечно и тепло. Двадцать градусов.": "Keçən həftə hər gün yağış yağırdı. Amma bu gün günəşli və istidir. İyirmi dərəcə.",
  "Здоровье и тело": "Sağlamlıq və bədən",
  "В этом уровне ты научишься говорить о самочувствии: называть части тела, объяснять врачу, что болит, записываться на приём по телефону и сообщать на работу, что ты заболел. Заодно выучишь модальные глаголы sollen и dürfen.": "Bu dərsdə özünü necə hiss etdiyindən danışmağı öyrənəcəksən: bədən üzvlərini adlandırmaq, həkimə nəyin ağrıdığını izah etmək, telefonla qəbula yazılmaq və işə xəstələndiyini bildirmək. Yanaşı sollen və dürfen modal feillərini öyrənəcəksən.",
  "Назвать части тела и сказать, что болит": "Bədən üzvlərini adlandırmaq və nəyin ağrıdığını demək",
  "Объяснить врачу симптомы и понять его совет": "Həkimə əlamətləri izah etmək və onun məsləhətini başa düşmək",
  "Записаться на приём к врачу по телефону": "Telefonla həkim qəbuluna yazılmaq",
  "Сообщить на работу, что ты болен": "İşə xəstə olduğunu bildirmək",
