  "Мне нужна запись на приём.": "Mənə qəbula yazılmaq lazımdır.",
  "больной, болен": "xəstə",
  "Эмиль сегодня болен.": "Emil bu gün xəstədir.",
  "здоровый": "sağlam",
  "Скоро ты снова будешь здоров.": "Tezliklə yenə sağlam olacaqsan.",
  "боли (мн. ч.)": "ağrılar",
  "У меня боли в спине.": "Belimdə ağrılar var.",
  "температура, жар": "hərarət, qızdırma",
  "У меня температура.": "Hərarətim var.",
