  "У меня насморк.": "Burnum axır.",
  "простуда": "soyuqdəymə",
  "Это всего лишь простуда.": "Bu, sadəcə soyuqdəymədir.",
  "Я сегодня иду к врачу.": "Mən bu gün həkimə gedirəm.",
  "врач (женщина)": "həkim (qadın)",
  "Доктор очень милая.": "Həkim çox mehribandır.",
  "запись на приём, встреча": "qəbul vaxtı, görüş",
  "У меня приём в 10 часов.": "Qəbulum saat 10-dadır.",
  "врачебный кабинет, практика": "həkim kabineti, praktika",
  "Кабинет врача на втором этаже.": "Həkim kabineti ikinci mərtəbədədir.",
  "лекарство": "dərman",
  "Мне нужно лекарство.": "Mənə dərman lazımdır.",
  "таблетка": "tablet",
  "Прими таблетку, Эмиль!": "Bir tablet iç, Emil!",
  "Аптека рядом с кабинетом врача.": "Aptek həkim kabinetinin yanındadır.",
  "рецепт": "resept",
  "Вот ваш рецепт.": "Budur sizin reseptiniz.",
  "Выздоравливай! / Поправляйтесь!": "Tez sağal! / Şəfa tapın!",
  "Выздоравливай, Эмиль!": "Tez sağal, Emil!",
  "отдыхать": "dincəlmək",
  "Мне надо сегодня отдохнуть.": "Bu gün dincəlməliyəm.",
  "усталый": "yorğun",
  "Я очень устал.": "Mən çox yorğunam.",
  "болеть (о части тела)": "ağrımaq (bədən üzvü)",
  "У меня болит нога.": "Ayağım ağrıyır.",
  "Что с вами? / На что жалуетесь?": "Nəyiniz var? / Şikayətiniz nədir?",
  "Добрый день! Что с вами?": "Günortanız xeyir! Nəyiniz var?",
  "Модальные глаголы sollen и dürfen": "sollen və dürfen modal feilləri",
  "sollen — это совет или рекомендация («следует, надо»): врач говорит: Sie sollen viel trinken. dürfen — разрешение («можно»), а nicht dürfen / kein… dürfen — запрет («нельзя»): Sie dürfen nicht arbeiten.\nКак и können или müssen, модальный глагол стоит на втором месте, а инфинитив уходит в конец предложения. Обрати внимание: у ich и er/sie/es форма одинаковая и без окончания: ich soll, er soll; ich darf, er darf.": "sollen — məsləhət və ya tövsiyədir («lazımdır, gərəkdir»): həkim deyir: Sie sollen viel trinken. dürfen — icazədir («olar»), nicht dürfen / kein… dürfen isə qadağadır («olmaz»): Sie dürfen nicht arbeiten.\nkönnen və müssen kimi, modal feil ikinci yerdə durur, məsdər isə cümlənin sonuna gedir. Diqqət et: ich və er/sie/es formaları eynidir və şəkilçisizdir: ich soll, er soll; ich darf, er darf.",
  "Тебе следует оставаться в постели.": "Yataqda qalmalısan.",
  "Эмилю надо пить много чая.": "Emil çoxlu çay içməlidir.",
  "Можно мне завтра работать?": "Sabah işləyə bilərəm?",
  "Вам нельзя заниматься спортом.": "Siz idmanla məşğul ola bilməzsiniz.",
  "Что болит: weh tun, Schmerzen и Dativ (mir, dir, Ihnen)": "Nə ağrıyır: weh tun, Schmerzen və Dativ (mir, dir, Ihnen)",
  "Чтобы сказать, что у тебя что-то болит, есть два способа. Первый: часть тела + tut weh (в единственном числе) или tun weh (во множественном): Mein Kopf tut weh. Meine Beine tun weh. Второй: haben + слово с -schmerzen: Ich habe Kopfschmerzen, Bauchschmerzen, Halsschmerzen, Zahnschmerzen, Rückenschmerzen.\nУ кого болит — это Dativ: mir (мне), dir (тебе), Ihnen (вам). Так же строится вопрос врача Was fehlt Ihnen? («Что с вами?») и Wie geht es dir/Ihnen?": "Nəyinsə ağrıdığını demək üçün iki yol var. Birincisi: bədən üzvü + tut weh (təkdə) və ya tun weh (cəmdə): Mein Kopf tut weh. Meine Beine tun weh. İkincisi: haben + -schmerzen ilə söz: Ich habe Kopfschmerzen, Bauchschmerzen, Halsschmerzen, Zahnschmerzen, Rückenschmerzen.\nKimin ağrıdığı — bu, Dativdir: mir (mənə), dir (sənə), Ihnen (sizə). Həkimin Was fehlt Ihnen? («Nəyiniz var?») sualı və Wie geht es dir/Ihnen? də eyni cür qurulur.",
  "У меня болят ноги.": "Ayaqlarım ağrıyır.",
  "У меня головная боль и температура.": "Başım ağrıyır və hərarətim var.",
  "Что у тебя болит, Эмиль?": "Nəyin ağrıyır, Emil?",
  "Imperativ для советов (повторение)": "Məsləhət üçün Imperativ (təkrar)",
  "Совет врача или друга удобно давать в повелительном наклонении. Форма на Sie: глагол + Sie: Trinken Sie viel Tee! Форма на du: основа глагола без -st и без du: Trink viel Tee! У nehmen форма на du — Nimm! А у schlafen умлаут пропадает: du schläfst → Schlaf!\nОтделяемая приставка уходит в конец: Ruhen Sie sich aus! / Ruh dich aus! — запомни целиком, sich / dich здесь значит «себя». Слово bitte делает совет мягче.": "Həkimin və ya dostun məsləhətini əmr formasında vermək rahatdır. Sie forması: feil + Sie: Trinken Sie viel Tee! du forması: feilin kökü, -st şəkilçisi və du olmadan: Trink viel Tee! nehmen-in du forması — Nimm! schlafen-də isə umlaut yox olur: du schläfst → Schlaf!\nAyrılan prefiks sona gedir: Ruhen Sie sich aus! / Ruh dich aus! — bunu bütöv əzbərlə, sich / dich burada «özünü» deməkdir. bitte sözü məsləhəti yumşaldır.",
  "Пейте много воды!": "Çoxlu su için!",
  "Прими таблетки, Эмиль!": "Tabletləri iç, Emil!",
  "Оставайтесь, пожалуйста, дома!": "Zəhmət olmasa, evdə qalın!",
  "рука (от плеча)": "qol (çiyindən)",
  "кисть руки": "əl",
  "Как сказать «живот»?": "«Qarın» necə deyilir?",
  "der Bauch — живот, der Rücken — спина, die Nase — нос.": "der Bauch — qarın, der Rücken — kürək, die Nase — burun.",
  "Что значит «krank»?": "«krank» nə deməkdir?",
  "больной": "xəstə",
  "krank — больной, gesund — здоровый, müde — усталый.": "krank — xəstə, gesund — sağlam, müde — yorğun.",
  "температура": "temperatur",
  "Врач спрашивает: «Was fehlt Ihnen?» Что это значит?": "Həkim soruşur: «Was fehlt Ihnen?» Bu nə deməkdir?",
  "Куда вы идёте?": "Hara gedirsiniz?",
  "Как вас зовут?": "Adınız nədir?",
  "Was fehlt Ihnen? — стандартный вопрос врача о самочувствии.": "Was fehlt Ihnen? — həkimin sağlamlıq barədə verdiyi standart sual.",
  "запись на приём": "qəbul vaxtı",
  "врачебный кабинет": "həkim kabineti",
  "Kopf + Schmerzen = Kopfschmerzen (головная боль).": "Kopf + Schmerzen = Kopfschmerzen (baş ağrısı).",
  "Одна часть тела (das Bein) → tut weh.": "Bir bədən üzvü (das Bein) → tut weh.",
  "У меня болят ноги (ступни).": "Ayaqlarım (pəncələrim) ağrıyır.",
  "Множественное число (die Füße) → tun weh.": "Cəm (die Füße) → tun weh.",
  "Неважно, у меня болит спина.": "Fərqi yoxdur, kürəyim ağrıyır.",
  "У кого болит — Dativ: mir.": "Ağrı kimdədir — Dativ: mir.",
  "fehlen требует Dativ: Ihnen (вам).": "fehlen Dativ tələb edir: Ihnen (sizə).",
  "Что у тебя болит?": "Nəyin ağrıyır?",
