  "Больному врач советует отдыхать: Ruhen Sie sich aus!": "Həkim xəstəyə dincəlməyi məsləhət görür: Ruhen Sie sich aus!",
  "Вам следует пить много чая.": "Siz çox çay içməlisiniz.",
  "Что значит «Sie dürfen keinen Kaffee trinken»?": "«Sie dürfen keinen Kaffee trinken» nə deməkdir?",
  "Вам нельзя пить кофе.": "Sizə qəhvə içmək olmaz.",
  "Вы должны пить кофе.": "Siz qəhvə içməlisiniz.",
  "Вы можете пить кофе.": "Siz qəhvə içə bilərsiniz.",
  "nicht dürfen / kein… dürfen = нельзя, запрет.": "nicht dürfen / kein… dürfen = olmaz, qadağa.",
  "Тебе нельзя сегодня работать, у тебя температура.": "Sənə bu gün işləmək olmaz, qızdırman var.",
  "Мне нельзя заниматься спортом.": "Mənə idmanla məşğul olmaq olmaz.",
  "Вам нельзя работать.": "Sizə işləmək olmaz.",
  "Совет пациенту на «Sie»: ___ viel Tee!": "Xəstəyə «Sie» ilə məsləhət: ___ viel Tee!",
  "Imperativ на Sie: глагол + Sie в начале предложения.": "Sie ilə Imperativ: feil + Sie cümlənin əvvəlində.",
  "Прими две таблетки, Эмиль!": "İki həb qəbul et, Emil!",
  "Imperativ на du от nehmen — Nimm!": "nehmen feilinin du ilə Imperativ forması — Nimm!",
  "Оставайся дома и много спи.": "Evdə qal və çox yat.",
  "Куда позвонил Эмиль?": "Emil hara zəng etdi?",
  "В аптеку": "Aptekə",
  "В кабинет врача": "Həkim kabinetinə",
  "В больницу": "Xəstəxanaya",
  "Добрый день, кабинет доктора Вебер. Вы хотите записаться на приём?": "Günortanız xeyir, doktor Weberin kabineti. Qəbula yazılmaq istəyirsiniz?",
  "Мне нужна запись к врачу.": "Mənə həkimə qəbul lazımdır.",
  "einen Termin — Akkusativ, мужской род.": "einen Termin — Akkusativ, kişi cinsi.",
  "Мне нужна запись на приём, пожалуйста.": "Zəhmət olmasa, mənə bir qəbul vaxtı lazımdır.",
  "Как часто нужно принимать таблетки?": "Həbləri nə qədər tez-tez qəbul etmək lazımdır?",
  "Один раз в день": "Gündə bir dəfə",
  "Два раза в день": "Gündə iki dəfə",
  "Три раза в день": "Gündə üç dəfə",
  "Принимайте таблетки два раза в день, утром и вечером. Тогда вы скоро снова будете здоровы.": "Həbləri gündə iki dəfə, səhər və axşam qəbul edin. Onda tezliklə yenə sağlam olacaqsınız.",
  "Zahnschmerzen — зубная боль, значит, к зубному врачу (Zahnarzt).": "Zahnschmerzen — diş ağrısı, deməli, diş həkiminə (Zahnarzt).",
  "Я болен и не приду.": "Mən xəstəyəm və gəlməyəcəyəm.",
  "Я сегодня очень устал.": "Mən bu gün çox yorğunam.",
  "Я сегодня очень устала.": "Mən bu gün çox yorulmuşam.",
  "Сегодня я очень устал.": "Bu gün mən çox yorğunam.",
  "Я очень устал сегодня.": "Bu gün çox yorğunam.",
  "müde = усталый": "müde = yorğun",
  "Поправляйся, Эмиль!": "Sağal, Emil!",
  "Скорейшего выздоровления, Эмиль!": "Tez sağalmağını arzu edirəm, Emil!",
  "Besserung — улучшение": "Besserung — yaxşılaşma",
  "В кабинете врача": "Həkim kabinetində",
  "Добрый день. Что с вами?": "Günortanız xeyir. Nəyiniz var?",
  "Добрый день, доктор. Я болен. У меня головная боль и температура.": "Günortanız xeyir, doktor. Mən xəstəyəm. Baş ağrım və qızdırmam var.",
  "А кашель или насморк у вас тоже есть?": "Bəs öskürəyiniz və ya zökəminiz də var?",
  "Да, у меня насморк и кашель. Горло тоже болит.": "Bəli, zökəmim və öskürəyim var. Boğazım da ağrıyır.",
  "У вас простуда. Вам следует оставаться в постели и пить много чая.": "Siz soyuqlamısınız. Yataqda qalmalı və çox çay içməlisiniz.",
  "Нет, на этой неделе вам нельзя работать. Отдыхайте!": "Xeyr, bu həftə sizə işləmək olmaz. Dincəlin!",
  "Мне нужны лекарства?": "Mənə dərman lazımdır?",
  "Да, вот рецепт. Принимайте таблетки два раза в день. Аптека рядом с кабинетом.": "Bəli, budur resept. Həbləri gündə iki dəfə qəbul edin. Aptek kabinetin yanındadır.",
  "Большое спасибо, доктор. До свидания!": "Çox təşəkkür edirəm, doktor. Sağ olun!",
  "До свидания и выздоравливайте!": "Görüşənədək və tez sağalın!",
  "Звонок в кабинет врача": "Həkim kabinetinə zəng",
  "Ты заболел: у тебя болит голова и горло, есть температура. Позвони в кабинет врача (Praxis Dr. Weber). Мия — администратор. Поздоровайся, скажи, что тебе нужна запись на приём, объясни, что с тобой, договорись о времени и назови свой номер телефона.": "Sən xəstələnmisən: başın və boğazın ağrıyır, qızdırman var. Həkim kabinetinə (Praxis Dr. Weber) zəng et. Mia — administratordur. Salamlaş, qəbula yazılmaq istədiyini de, nəyin olduğunu izah et, vaxtı razılaşdır və telefon nömrəni de.",
  "У меня ещё и кашель.": "Bir də öskürəyim var.",
  "Я могу прийти сегодня?": "Mən bu gün gələ bilərəm?",
  "Мой номер телефона …": "Mənim telefon nömrəm …",
  "Спасибо, до свидания (по телефону)!": "Təşəkkür edirəm, sağ olun (telefonla)!",
  "Кабинет доктора Вебер, добрый день. Чем могу помочь?": "Doktor Weberin kabineti, günortanız xeyir. Sizə necə kömək edə bilərəm?",
  "Хорошо. Как вас зовут?": "Yaxşı. Adınız nədir?",
  "Спасибо. И что с вами?": "Təşəkkür edirəm. Bəs nəyiniz var?",
  "О, мне жаль. У вас есть температура?": "Oh, təəssüf edirəm. Qızdırmanız var?",
  "Вы можете прийти сегодня в 15 часов?": "Bu gün saat 15-də gələ bilərsiniz?",
  "Очень хорошо. Какой у вас номер телефона?": "Çox gözəl. Telefon nömrəniz nədir?",
  "Спасибо, Эмиль. До 15 часов и выздоравливайте! До свидания!": "Təşəkkür edirəm, Emil. Saat 15-dək və tez sağalın! Görüşənədək!",
  "Врач говорит: «Вам следует много спать».": "Həkim deyir: «Siz çox yatmalısınız».",
  "Sie (вежливое) → sollen.": "Sie (nəzakətli) → sollen.",
  "У меня болит живот.": "Qarnım ağrıyır.",
  "Единственное число → tut weh.": "Tək → tut weh.",
  "На вопрос врача отвечают, что болит.": "Həkimin sualına nəyin ağrıdığını deyərək cavab verirlər.",
  "Могу я записаться на приём сегодня?": "Mən bu gün qəbula yazıla bilərəm?",
  "Мне нельзя пить кофе.": "Mənə qəhvə içmək olmaz.",
  "Imperativ на du: Geh! (geht — это ihr, gehst — не Imperativ).": "du ilə Imperativ: Geh! (geht — bu, ihr formasıdır, gehst — Imperativ deyil).",
  "Почему Эмиль сегодня не идёт на работу?": "Emil bu gün niyə işə getmir?",
