  "Он очень устал": "O, çox yorğundur",
  "Здравствуйте, это Эмиль. Я болен, и у меня температура. К сожалению, я не могу сегодня прийти на работу.": "Salam, bu, Emildir. Mən xəstəyəm və qızdırmam var. Təəssüf ki, bu gün işə gələ bilmirəm.",
  "У меня болят глаза.": "Gözlərim ağrıyır.",
  "Мои глаза болят.": "Mənim gözlərim ağrıyır.",
  "Глаза болят.": "Gözlər ağrıyır.",
  "Путешествия и отпуск": "Səyahət və məzuniyyət",
  "В последнем уровне ты научишься покупать билеты на вокзале, заселяться в отель и рассказывать о своей поездке. Ты также выучишь Perfekt с sein и формы war / hatte.": "Son səviyyədə vağzalda bilet almağı, otelə yerləşməyi və öz səfərin haqqında danışmağı öyrənəcəksən. Həmçinin sein ilə Perfekt və war / hatte formalarını öyrənəcəksən.",
  "Купить билет на поезд и спросить про путь и время": "Qatar bileti almaq, yol və vaxt barədə soruşmaq",
  "Заселиться в отель и вежливо попросить что-то": "Otelə yerləşmək və nəzakətlə nəsə xahiş etmək",
  "Рассказать о прошлой поездке (Perfekt с sein, war / hatte)": "Keçmiş səfər haqqında danışmaq (sein ilə Perfekt, war / hatte)",
  "Сказать, куда ты едешь и где ты был: nach, in die, am Meer": "Hara getdiyini və harada olduğunu demək: nach, in die, am Meer",
  "поездка, путешествие": "səfər, səyahət",
  "Поездка в Берлин была хорошей.": "Berlinə səfər yaxşı idi.",
  "В отпуске Эмиль был на море.": "Məzuniyyətdə Emil dəniz kənarında idi.",
  "Вокзал находится в центре.": "Vağzal mərkəzdədir.",
