  "«Ich möchte eine Fahrkarte nach Berlin, ___.» Туда и обратно — это:": "«Ich möchte eine Fahrkarte nach Berlin, ___.» Gediş-gəliş — bu:",
  "hin und zurück — туда и обратно; einfach — в одну сторону.": "hin und zurück — gediş-gəliş; einfach — bir tərəfə.",
