  "Perfekt отделяемых глаголов": "Ayrılan prefiksli feillərin Perfekt forması",
  "В Partizip II приставка ge- прячется внутрь слова — между отделяемой приставкой и глаголом: einziehen → eingezogen, aufräumen → aufgeräumt, mitbringen → mitgebracht.\nВспомогательный глагол выбираешь как обычно: einziehen, ausziehen и umziehen — это смена места, поэтому с sein. Всё остальное — с haben.": "Partizip II-də ge- prefiksi sözün içinə gizlənir — ayrılan prefikslə feilin arasına: einziehen → eingezogen, aufräumen → aufgeräumt, mitbringen → mitgebracht.\nKöməkçi feili həmişəki kimi seçirsən: einziehen, ausziehen və umziehen yer dəyişməsidir, ona görə sein ilə. Qalan hər şey — haben ilə.",
