  "После модального глагола отделяемый глагол стоит в конце целиком: anmelden.": "Modal feildən sonra ayrılan prefiksli feil sonda bütöv durur: anmelden.",
  "Почему Эмиль звонит?": "Emil niyə zəng edir?",
