  "Из-за врача": "Həkimə görə",
  "Добрый день, это Эмиль. У меня вопрос по квартире на Гартенштрассе. Она ещё свободна?": "Günortanız xeyir, mən Emiləm. Qartenştrassedəki mənzillə bağlı sualım var. O hələ boşdur?",
  "umziehen — смена места, поэтому Perfekt с sein: ist umgezogen.": "umziehen — yer dəyişməsidir, ona görə Perfekt sein ilə: ist umgezogen.",
