  "Я вчера убрал ванную.": "Mən dünən hamamı yığışdırdım.",
  "aufräumen → aufgeräumt, Perfekt с haben.": "aufräumen → aufgeräumt, Perfekt haben ilə.",
  "Соседи съехали в июле.": "Qonşular iyulda köçüb getdilər.",
