  "Аренда слишком высокая.": "Kirayə çox yüksəkdir.",
  "Квартплата слишком высокая.": "Mənzil haqqı çox yüksəkdir.",
  "Аренда слишком дорогая.": "Kirayə həddən artıq bahadır.",
  "zu hoch = слишком высокая": "zu hoch = çox yüksək",
  "Переезд в субботу.": "Köçmə şənbə günüdür.",
  "Мы переезжаем в субботу.": "Biz şənbə günü köçürük.",
  "Просмотр квартиры": "Mənzilə baxış",
  "Добрый день! Хорошо, что вы пришли. Проходите, это прихожая.": "Günortanız xeyir! Yaxşı ki, gəldiniz. Buyurun, bura dəhlizdir.",
  "Добрый день, госпожа Бергер. Квартира светлая, мне это нравится.": "Günortanız xeyir, Berger xanım. Mənzil işıqlıdır, bu mənim xoşuma gəlir.",
  "Здесь слева кухня, а справа ванная и спальня.": "Burada solda mətbəx, sağda isə hamam və yataq otağı var.",
  "А гостиная? В ней есть балкон?": "Bəs qonaq otağı? Orada balkon var?",
  "Да, балкон за гостиной. В подвале у вас ещё есть место для велосипедов.": "Bəli, balkon qonaq otağının arxasındadır. Zirzəmidə velosipedlər üçün də yeriniz var.",
  "750 евро плюс 150 евро коммунальных. И залог — две месячные арендные платы.": "750 avro üstəgəl 150 avro kommunal xərclər. Depozit isə iki aylıq kirayə haqqıdır.",
  "Когда я могу въехать?": "Mən nə vaxt köçüb gələ bilərəm?",
  "Старые жильцы съезжают в конце апреля. Вы можете въехать первого мая.": "Köhnə kirayənişinlər aprelin sonunda köçüb gedirlər. Siz mayın birində köçüb gələ bilərsiniz.",
  "Это мне подходит. Я беру квартиру. Когда мы подпишем договор аренды?": "Bu mənə uyğundur. Mənzili götürürəm. Kirayə müqaviləsini nə vaxt imzalayacağıq?",
  "Приходите в пятницу в 16 часов ко мне в офис. Принесите, пожалуйста, паспорт.": "Cümə günü saat 16-da mənim ofisimə gəlin. Zəhmət olmasa, pasportunuzu gətirin.",
  "Понятно. Большое спасибо, госпожа Бергер. До пятницы!": "Başa düşdüm. Çox sağ olun, Berger xanım. Cümə günü görüşənədək!",
  "Ты нашёл объявление о трёхкомнатной квартире и пришёл на просмотр. Мия — хозяйка квартиры, она говорит тебе «Sie». Поздоровайся, спроси, сколько в квартире комнат, сколько стоит аренда и коммунальные, есть ли балкон и подвал, и когда можно въехать. В конце скажи, что квартира тебе нравится.": "Sən üçotaqlı mənzil haqqında elan tapmısan və baxışa gəlmisən. Mia mənzilin sahibidir, o sənə «Sie» deyə müraciət edir. Salamlaş, soruş ki, mənzildə neçə otaq var, kirayə və kommunal xərclər nə qədərdir, balkon və zirzəmi varmı, və nə vaxt köçüb gəlmək olar. Sonda de ki, mənzil xoşuna gəlir.",
  "Добрый день, я хотел бы посмотреть квартиру.": "Günortanız xeyir, mən mənzilə baxmaq istərdim.",
  "Коммунальные включены?": "Kommunal xərclər daxildir?",
  "Квартира мне нравится.": "Mənzil xoşuma gəlir.",
  "Добрый день! Вы Эмиль, верно? Проходите.": "Günortanız xeyir! Siz Emilsiniz, elədir? Buyurun.",
  "Это прихожая, здесь слева кухня. Что вы хотите узнать?": "Bu dəhlizdir, burada solda mətbəx var. Nə bilmək istəyirsiniz?",
  "В квартире три комнаты и ванная. Есть вопросы по цене?": "Mənzildə üç otaq və hamam var. Qiymətlə bağlı sualınız var?",
  "Аренда 750 евро, коммунальные — 150 евро. Плюс залог.": "Kirayə 750 avro, kommunal xərclər — 150 avro. Üstəlik depozit.",
  "Да, балкон за гостиной. В подвале тоже есть место для ваших коробок.": "Bəli, balkon qonaq otağının arxasındadır. Zirzəmidə də qutularınız üçün yer var.",
  "Старые жильцы съезжают в конце апреля. Вы можете въехать первого мая. И как вам квартира?": "Köhnə kirayənişinlər aprelin sonunda köçüb gedirlər. Siz mayın birində köçüb gələ bilərsiniz. Bəs mənzil sizə necədir?",
  "Я рада, Эмиль! Тогда до пятницы в офисе. До свидания!": "Sevindim, Emil! Onda cümə günü ofisdə görüşərik. Sağ olun!",
