  "einziehen — смена места: Perfekt с sein, wir sind eingezogen.": "einziehen — yer dəyişməsi: Perfekt sein ilə, wir sind eingezogen.",
  "Соседи очень приветливые.": "Qonşular çox mehribandır.",
