  "Квартира стоит 700 евро аренды плюс 150 евро коммунальных.": "Mənzil 700 avro kirayə üstəgəl 150 avro kommunal xərclərə başa gəlir.",
  "Я убрал всю квартиру.": "Mən bütün mənzili yığışdırdım.",
  "После переезда в Германии нужно зарегистрироваться: sich anmelden.": "Almaniyada köçmədən sonra qeydiyyatdan keçmək lazımdır: sich anmelden.",
  "Мы переезжаем на следующей неделе.": "Biz gələn həftə köçürük.",
  "На следующей неделе мы переезжаем.": "Gələn həftə biz köçürük.",
  "umziehen = переезжать": "umziehen = köçmək",
  "Работа и поиск работы": "İş və iş axtarışı",
  "В этом уровне ты научишься говорить о работе по-взрослому: рассказывать, где и кем ты работал раньше, понимать объявление о вакансии, отвечать на вопросы на собеседовании и разбираться в словах из договора. Грамматика — Perfekt: с haben и с sein, правильные и неправильные Partizip II и рамка, в которой Partizip II всегда стоит в конце.": "Bu səviyyədə iş haqqında böyük adam kimi danışmağı öyrənəcəksən: əvvəl harada və kim işlədiyini danışmaq, vakansiya elanını başa düşmək, müsahibədə suallara cavab vermək və müqavilədəki sözləri anlamaq. Qrammatika — Perfekt: haben və sein ilə, qaydalı və qaydasız Partizip II və Partizip II-nin həmişə sonda durduğu çərçivə.",
  "Рассказать о своём опыте работы в Perfekt: где, кем и сколько ты работал": "Perfekt-də iş təcrübəndən danışmaq: harada, kim kimi və nə qədər işləmisən",
  "Понять объявление о вакансии и слова из договора: Probezeit, Schicht, Gehalt": "Vakansiya elanını və müqavilədəki sözləri başa düşmək: Probezeit, Schicht, Gehalt",
  "Пройти собеседование и позвонить работодателю по объявлению": "Müsahibədən keçmək və elana görə işəgötürənə zəng etmək",
  "Строить рамку правильно: haben/sein на втором месте, Partizip II в самом конце": "Çərçivəni düzgün qurmaq: haben/sein ikinci yerdə, Partizip II ən sonda",
