  "Сегодня я чувствую себя уже намного лучше.": "Bu gün özümü artıq xeyli yaxşı hiss edirəm.",
  "кружится голова (Mir ist schwindlig)": "başı gicəllənir (Mir ist schwindlig)",
  "У меня со вчерашнего дня кружится голова.": "Dünəndən başım gicəllənir.",
  "перенести приём": "qəbulu başqa vaxta keçirmək",
  "Мы можем перенести приём на пятницу?": "Qəbulu cümə gününə keçirə bilərik?",
  "срочно, срочный": "təcili",
  "Мне срочно нужен приём.": "Mənə təcili qəbul lazımdır.",
  "Модальные глаголы в прошедшем времени (Präteritum)": "Modal feillər keçmiş zamanda (Präteritum)",
  "О прошлом с модальными глаголами немцы говорят не в Perfekt, а в Präteritum — это короче и звучит естественно. Основа теряет умлаут, и к ней добавляется -te: können → konnte, müssen → musste, dürfen → durfte. У wollen и sollen умлаута и не было: wollte, sollte.\nОкончания как у обычного глагола в прошедшем: ich konnte, du konntest, er/sie konnte, wir konnten, ihr konntet, sie/Sie konnten. У ich и er/sie/es форма одинаковая.\nПорядок слов прежний: модальный глагол на втором месте, инфинитив — в самом конце.": "Keçmiş haqqında modal feillərlə almanlar Perfekt-də yox, Präteritum-da danışır — bu həm qısadır, həm də təbii səslənir. Kök umlautu itirir və ona -te əlavə olunur: können → konnte, müssen → musste, dürfen → durfte. wollen və sollen-də umlaut onsuz da yox idi: wollte, sollte.\nŞəkilçilər adi feilin keçmiş zamanındakı kimidir: ich konnte, du konntest, er/sie konnte, wir konnten, ihr konntet, sie/Sie konnten. ich və er/sie/es üçün forma eynidir.\nSöz sırası əvvəlki kimidir: modal feil ikinci yerdə, məsdər isə lap sonda.",
  "я мог": "mən bacarırdım",
  "мне пришлось, я должен был": "məcbur oldum, mən məcbur idim",
  "я хотел": "mən istəyirdim",
  "мне было можно": "mənə icazə var idi",
  "мне следовало": "mən etməli idim",
  "Эмиль вчера не мог работать.": "Emil dünən işləyə bilmirdi.",
  "Мне пришлось три дня лежать в постели.": "Üç gün yataqda qalmağa məcbur oldum.",
  "После гриппа мне нельзя было заниматься спортом.": "Qripdən sonra mənə idmanla məşğul olmağa icazə yox idi.",
  "Вы хотели приём в понедельник?": "Siz bazar ertəsinə qəbul istəyirdiniz?",
  "Вежливая просьба: Imperativ + bitte": "Nəzakətli xahiş: Imperativ + bitte",
  "В кабинете врача почти всё говорят в повелительном наклонении на Sie: глагол на первое место, сразу за ним Sie. Слово bitte делает просьбу вежливой, а слова doch и mal — мягкой, почти дружеской.\nФорма на du — это основа глагола без окончания: Trink!, Komm!, Ruh dich aus! Но если основа кончается на -t, -d или на -m/-n после согласной, добавляется -e: warten → Warte!, arbeiten → Arbeite!, atmen → Atme! У сильных глаголов с e → i меняется и гласная: nehmen → Nimm!\nОтделяемая приставка всегда уходит в конец: Atmen Sie tief ein! А возвратное слово стоит сразу после глагола: Ruhen Sie sich aus! / Ruh dich aus!": "Həkim kabinetində demək olar ki, hər şeyi Sie ilə əmr formasında deyirlər: feil birinci yerdə, dərhal ondan sonra Sie. bitte sözü xahişi nəzakətli, doch və mal sözləri isə yumşaq, az qala dostyana edir.\ndu forması — feilin şəkilçisiz köküdür: Trink!, Komm!, Ruh dich aus! Amma kök -t, -d ilə və ya samitdən sonra gələn -m/-n ilə bitirsə, -e əlavə olunur: warten → Warte!, arbeiten → Arbeite!, atmen → Atme! e → i dəyişən güclü feillərdə sait də dəyişir: nehmen → Nimm!\nAyrılan prefiks həmişə sona gedir: Atmen Sie tief ein! Qayıdış sözü isə dərhal feildən sonra durur: Ruhen Sie sich aus! / Ruh dich aus!",
  "Sie-Form (вежливо)": "Sie-Form (nəzakətli)",
  "Садитесь, пожалуйста, в приёмной.": "Zəhmət olmasa, gözləmə otağında oturun.",
  "Отдохни, Эмиль, и пей много чая.": "Dincəl, Emil, və çoxlu çay iç.",
  "Приходите, пожалуйста, ещё раз в пятницу.": "Zəhmət olmasa, cümə günü bir daha gəlin.",
  "Сходи всё-таки к семейному врачу!": "Get də ailə həkiminin yanına!",
  "Куда и где: zum Arzt, beim Arzt, ins Krankenhaus": "Hara və harada: zum Arzt, beim Arzt, ins Krankenhaus",
  "Если речь о человеке (врач), то «куда» — это zu + Dativ: zum Arzt, zur Ärztin. А «где» — bei + Dativ: beim Arzt, bei der Ärztin.\nЕсли речь о здании или помещении, работает знакомая пара: «куда» — in + Akkusativ (ins Krankenhaus, in die Apotheke), «где» — in + Dativ (im Krankenhaus, in der Apotheke).\nКороткие формы: zu dem = zum, zu der = zur, in das = ins, in dem = im.": "Söhbət insandan (həkimdən) gedirsə, «hara» — bu zu + Dativ-dir: zum Arzt, zur Ärztin. «Harada» isə bei + Dativ: beim Arzt, bei der Ärztin.\nSöhbət binadan və ya otaqdan gedirsə, tanış cütlük işləyir: «hara» — in + Akkusativ (ins Krankenhaus, in die Apotheke), «harada» — in + Dativ (im Krankenhaus, in der Apotheke).\nQısa formalar: zu dem = zum, zu der = zur, in das = ins, in dem = im.",
  "Wohin? (куда)": "Wohin? (hara)",
  "Wo? (где)": "Wo? (harada)",
