  "Форма на Sie плюс bitte — самый вежливый вариант.": "Sie forması üstəgəl bitte — ən nəzakətli variantdır.",
  "Сделайте, пожалуйста, глубокий вдох.": "Zəhmət olmasa, dərindən nəfəs alın.",
