  "Я возьму синюю куртку.": "Mən mavi gödəkçəni götürəcəyəm.",
  "Женский род после die — окончание -e, и в Nominativ, и в Akkusativ.": "die-dən sonra qadın cinsi — şəkilçi -e, həm Nominativ-də, həm də Akkusativ-də.",
  "После das — окончание -e: das graue T-Shirt (серая футболка).": "das-dan sonra — şəkilçi -e: das graue T-Shirt (boz futbolka).",
