  "Я покупаю тёплое пальто.": "Mən isti palto alıram.",
  "Артикль ein рода не показывает, поэтому его показывает прилагательное: -er, как в der.": "ein artikli cinsi göstərmir, ona görə də onu sifət göstərir: -er, der-dəki kimi.",
