  "der Rabatt — скидка в процентах.": "der Rabatt — faizlə endirim.",
  "Куртка для меня слишком дорогая.": "Gödəkçə mənim üçün həddindən artıq bahadır.",
  "zu teuer — слишком дорого; после ist прилагательное без окончания.": "zu teuer — həddindən artıq baha; ist-dən sonra sifət şəkilçisiz olur.",
