  "49 евро": "49 avro",
  "39 евро": "39 avro",
  "Эта куртка обычно стоит 59 евро. Сегодня она со скидкой и стоит всего 39 евро.": "Bu gödəkçə adətən 59 avrodur. Bu gün o, endirimlidir və cəmi 39 avroya satılır.",
  "Где находятся примерочные?": "Geyinmə kabinələri haradadır?",
