  "У входа в универмаг": "Univermağın girişində",
  "Примерочные там сзади слева, рядом с кассой.": "Geyinmə kabinələri orada arxada, solda, kassanın yanındadır.",
  "У меня 42-й размер.": "Mənim ölçüm 42-dir.",
