  "Могу я обменять рубашку?": "Köynəyi dəyişdirə bilərəm?",
  "Я возьму синий свитер.": "Mən mavi sviteri götürəcəyəm.",
  "Я беру синий свитер.": "Mən mavi sviteri götürürəm.",
  "Я куплю синий свитер.": "Mən mavi sviteri alacağam.",
  "Где примерочная?": "Geyinmə kabinəsi haradadır?",
  "Рубашка, к сожалению, мне мала.": "Köynək, təəssüf ki, mənə kiçikdir.",
  "Где касса, пожалуйста?": "Kassa haradadır, zəhmət olmasa?",
  "В универмаге": "Univermaqda",
  "Добрый день! Могу я вам помочь?": "Xeyirli gün! Sizə kömək edə bilərəm?",
  "Добрый день. Я ищу тёплую куртку на зиму.": "Günortanız xeyir. Mən qış üçün isti gödəkçə axtarıram.",
  "С удовольствием. Какой у вас размер?": "Məmnuniyyətlə. Ölçünüz neçədir?",
  "У меня 52-й размер. А какие цвета у вас есть?": "Mənim ölçüm 52-dir. Bəs hansı rəngləriniz var?",
  "У нас эта куртка есть в синем, чёрном и зелёном.": "Bu gödəkçə bizdə mavi, qara və yaşıl rənglərdə var.",
  "Тогда я возьму синюю куртку. Можно мне её примерить?": "Onda mən mavi gödəkçəni götürərəm. Onu sınaya bilərəm?",
  "Конечно. Примерочная там сзади слева.": "Əlbəttə. Geyinmə kabinəsi orada arxada, soldadır.",
  "Куртка мне хорошо сидит, и она очень удобная. Сколько она стоит?": "Gödəkçə mənə yaxşı oturur və çox rahatdır. Qiyməti neçədir?",
  "Обычно 89 евро, но сегодня она со скидкой: всего 69 евро.": "Adətən 89 avro, amma bu gün o, endirimlidir: cəmi 69 avro.",
  "Это действительно выгодно. Я её беру.": "Bu, həqiqətən sərfəlidir. Onu götürürəm.",
  "Пожалуйста. Касса впереди справа. Чек вы получите там.": "Buyurun. Kassa qabaqda, sağdadır. Çeki orada alacaqsınız.",
  "Обмен обуви в магазине": "Mağazada ayaqqabının dəyişdirilməsi",
  "Вчера ты купил в универмаге коричневые ботинки, а дома понял, что они малы. Ты возвращаешься в магазин, Мия работает продавщицей. Скажи, что хочешь обменять ботинки, объясни почему, покажи чек, назови свой размер и попроси примерить другую пару.": "Dünən univermaqdan qəhvəyi ayaqqabı almısan, evdə isə onların kiçik olduğunu başa düşmüsən. Mağazaya qayıdırsan, Mia satıcı işləyir. De ki, ayaqqabıları dəyişdirmək istəyirsən, səbəbini izah et, çeki göstər, öz ölçünü de və başqa bir cüt sınamağı xahiş et.",
  "Я хотел бы обменять эти ботинки.": "Mən bu ayaqqabıları dəyişdirmək istərdim.",
  "Я купил их вчера.": "Mən onları dünən almışam.",
  "Они мне малы.": "Onlar mənə kiçikdir.",
  "Вот кассовый чек.": "Budur kassa çeki.",
  "У меня 43-й размер.": "Mənim ölçüm 43-dür.",
  "Можно мне их примерить?": "Onları sınaya bilərəm?",
  "Коричневые ботинки мне хорошо сидят.": "Qəhvəyi ayaqqabılar mənə yaxşı oturur.",
  "Большое спасибо за помощь.": "Kömək üçün çox sağ olun.",
  "Добрый день! Чем могу помочь?": "Günortanız xeyir! Nə ilə kömək edə bilərəm?",
  "Без проблем. Почему вы хотите обменять ботинки?": "Problem yoxdur. Ayaqqabıları niyə dəyişdirmək istəyirsiniz?",
  "Понимаю. У вас есть с собой чек?": "Başa düşürəm. Çek yanınızdadır?",
  "Спасибо. А какой размер вам нужен?": "Sağ olun. Bəs sizə hansı ölçü lazımdır?",
  "У нас есть эти коричневые ботинки и в 43-м размере. Хотите их примерить?": "Bu qəhvəyi ayaqqabılar bizdə 43-cü ölçüdə də var. Onları sınamaq istəyirsiniz?",
  "Ну и как теперь ботинки?": "Bəs indi ayaqqabılar necədir?",
  "Отлично. Тогда пройдите, пожалуйста, к кассе. До свидания, Эмиль!": "Əla. Onda, zəhmət olmasa, kassaya keçin. Sağ olun, Emil!",
  "den (мужской род, Akkusativ) → -en.": "den (kişi cinsi, Akkusativ) → -en.",
