  "Красные ботинки стоят 49 евро. Коричневые ботинки со скидкой и стоят всего 35 евро.": "Qırmızı ayaqqabılar 49 avrodur. Qəhvəyi ayaqqabılar endirimlidir və cəmi 35 avroya satılır.",
