  "Еда и ресторан": "Yemək və restoran",
  "В этом уровне ты научишься уверенно вести себя в ресторане: бронировать столик, заказывать еду, спрашивать совета у официанта и просить счёт. А ещё выучишь сравнение: billiger als, so lecker wie, am besten и am liebsten.": "Bu səviyyədə restoranda özünü inamlı aparmağı öyrənəcəksən: masa rezerv etmək, yemək sifariş etmək, ofisiantdan məsləhət soruşmaq və hesab istəmək. Bundan başqa müqayisəni öyrənəcəksən: billiger als, so lecker wie, am besten və am liebsten.",
  "Заказать еду в ресторане и попросить счёт": "Restoranda yemək sifariş etmək və hesab istəmək",
  "Сравнивать блюда: billiger als, nicht so scharf wie": "Yeməkləri müqayisə etmək: billiger als, nicht so scharf wie",
  "Сказать, что ты любишь больше всего: lieber, am liebsten": "Ən çox nəyi sevdiyini demək: lieber, am liebsten",
  "Понять официанта и ответить на его вопросы": "Ofisiantı başa düşmək və onun suallarına cavab vermək",
