  "мясо": "ət",
  "Эмиль любит мясо с овощами.": "Emil əti tərəvəzlə sevir.",
  "курица (блюдо)": "toyuq (yemək)",
  "Курица с рисом очень вкусная.": "Düyü ilə toyuq çox dadlıdır.",
