  "В пятницу мы едим рыбу.": "Cümə günü balıq yeyirik.",
  "овощи": "tərəvəz",
  "Ешь больше овощей, это полезно!": "Daha çox tərəvəz ye, bu faydalıdır!",
  "картофелина, картошка": "kartof, yeralması",
  "Картошка ещё слишком твёрдая.": "Kartof hələ çox bərkdir.",
  "Ты хочешь рис или макароны?": "Düyü istəyirsən, yoxsa makaron?",
  "макароны, лапша (мн. ч.)": "makaron, əriştə (cəm)",
  "Макароны детям нравятся больше всего.": "Uşaqlar ən çox makaronu sevirlər.",
  "Принесите нам, пожалуйста, ещё хлеба.": "Zəhmət olmasa, bizə bir az da çörək gətirin.",
  "Салат с сыром.": "Pendirli salat.",
  "соль": "duz",
  "Передашь мне, пожалуйста, соль?": "Zəhmət olmasa, duzu mənə uzadarsan?",
  "острый (о еде)": "acı (yemək haqqında)",
  "Еда для меня слишком острая.": "Yemək mənim üçün çox acıdır.",
  "сладкий": "şirin",
  "Десерт очень сладкий.": "Desert çox şirindir.",
  "Это было действительно вкусно!": "Bu, həqiqətən dadlı idi!",
  "сытый, наелся": "tox, doymuş",
  "Спасибо, я сыт.": "Təşəkkür edirəm, mən toxam.",
  "быть вкусным, нравиться на вкус": "dadlı olmaq, dadı xoşa gəlmək",
  "Как тебе суп на вкус?": "Şorbanın dadı sənə necə gəlir?",
  "пробовать": "dadına baxmaq",
  "Хочешь попробовать салат?": "Salatın dadına baxmaq istəyirsən?",
  "Komparativ und Superlativ: сравнительная и превосходная степень": "Komparativ und Superlativ: müqayisə və üstünlük dərəcəsi",
  "Сравнительная степень (Komparativ) — это прилагательное + -er: billig → billiger, lecker → leckerer. Превосходная степень (Superlativ) после глагола строится с am и окончанием -sten: am billigsten.\nКороткие прилагательные с a, o, u почти всегда получают умлаут: scharf → schärfer, warm → wärmer, groß → größer, kalt → kälter. Если основа кончается на -t, -d, -ß, добавляется -esten: am kältesten, am süßesten, am heißesten. Исключение — groß: größer, am größten (без -e-).\nУ teuer в Komparativ выпадает e: teuer → teurer.": "Müqayisə dərəcəsi (Komparativ) — bu, sifət + -er deməkdir: billig → billiger, lecker → leckerer. Üstünlük dərəcəsi (Superlativ) feildən sonra am və -sten şəkilçisi ilə düzəlir: am billigsten.\na, o, u olan qısa sifətlər demək olar ki, həmişə umlaut alır: scharf → schärfer, warm → wärmer, groß → größer, kalt → kälter. Əgər kök -t, -d, -ß ilə bitirsə, -esten əlavə olunur: am kältesten, am süßesten, am heißesten. İstisna — groß: größer, am größten (-e- olmadan).\nteuer sözündə Komparativdə e düşür: teuer → teurer.",
  "billig — дешёвый": "billig — ucuz",
  "lecker — вкусный": "lecker — dadlı",
  "teuer — дорогой": "teuer — baha",
  "scharf — острый": "scharf — acı",
  "warm — тёплый": "warm — isti",
  "groß — большой": "groß — böyük",
  "kalt — холодный": "kalt — soyuq",
  "Суп дешевле салата.": "Şorba salatdan ucuzdur.",
  "Этот ресторан самый дешёвый.": "Bu restoran ən ucuzdur.",
  "Рыба сегодня острее, чем вчера.": "Balıq bu gün dünənkindən daha acıdır.",
  "Эмиль берёт самую большую порцию.": "Emil ən böyük porsiyanı götürür.",
  "Несколько важных слов образуют степени сравнения не по правилу — их надо выучить наизусть.\ngern, lieber, am liebsten говорят о том, что ты любишь делать: Ich esse gern Fisch (люблю), ich esse lieber Hähnchen (люблю больше), am liebsten esse ich Suppe (люблю больше всего). Эти слова стоят рядом с глаголом, а не с существительным.\nЕсли am liebsten или am besten стоит в начале предложения, глагол всё равно остаётся на втором месте: Am liebsten esse ich Fisch.": "Bir neçə vacib söz müqayisə dərəcələrini qaydaya uyğun düzəltmir — onları əzbər öyrənmək lazımdır.\ngern, lieber, am liebsten nə etməyi sevdiyini bildirir: Ich esse gern Fisch (sevirəm), ich esse lieber Hähnchen (daha çox sevirəm), am liebsten esse ich Suppe (ən çox sevirəm). Bu sözlər ismin yanında yox, feilin yanında durur.\nƏgər am liebsten və ya am besten cümlənin əvvəlində durursa, feil yenə də ikinci yerdə qalır: Am liebsten esse ich Fisch.",
  "Основа": "Kök",
  "gut — хорошо": "gut — yaxşı",
  "gern — охотно, с удовольствием": "gern — həvəslə, məmnuniyyətlə",
  "viel — много": "viel — çox",
  "hoch — высокий": "hoch — hündür",
  "nah — близкий": "nah — yaxın",
  "Я люблю рыбу, но курицу люблю больше.": "Mən balığı sevirəm, amma toyuğu daha çox sevirəm.",
  "Больше всего Эмиль любит суп с хлебом.": "Emil ən çox çörəklə şorbanı sevir.",
  "Твой суп вкуснее моего.": "Sənin şorban mənimkindən daha dadlıdır.",
  "Здесь готовят лучше всего.": "Burada ən yaxşı yemək bişirirlər.",
  "Два предмета можно сравнить двумя способами. Если они одинаковые, бери so … wie (такой же … как) или genauso … wie. Если один «больше» другого, бери Komparativ + als (чем).\nГлавная ошибка новичков — сказать «besser wie». После сравнительной степени всегда только als: besser als, teurer als, mehr als.\nОтрицание тоже работает: nicht so … wie — «не такой …, как».": "İki əşyanı iki cür müqayisə etmək olar. Əgər onlar eynidirsə, so … wie (… qədər, … kimi) və ya genauso … wie götür. Əgər biri o birindən «artıqdırsa», Komparativ + als (-dan, -dən) götür.\nYeni başlayanların əsas səhvi «besser wie» deməkdir. Müqayisə dərəcəsindən sonra həmişə yalnız als işlənir: besser als, teurer als, mehr als.\nİnkar da işləyir: nicht so … wie — «… qədər … deyil».",
  "Конструкция": "Konstruksiya",
  "Салат такой же дорогой, как суп.": "Salat şorba qədər bahadır.",
  "Хлеб такой же свежий, как вчера.": "Çörək dünənki qədər təzədir.",
  "Рыба не такая острая, как курица.": "Balıq toyuq qədər acı deyil.",
  "Основное блюдо дороже закуски.": "Əsas yemək qəlyanaltıdan bahadır.",
  "Мия ест больше овощей, чем Эмиль.": "Mia Emildən çox tərəvəz yeyir.",
  "Макароны такие же вкусные, как картошка.": "Makaron kartof qədər dadlıdır.",
  "Здесь не так дорого, как в центре.": "Burada mərkəzdəki qədər baha deyil.",
