  "Рыба дороже, чем курица.": "Balıq toyuqdan bahadır.",
  "Превосходная степень от gut — am besten («лучше всех»).": "gut sözünün üstünlük dərəcəsi — am besten («hamıdan yaxşı»).",
  "Из всех блюд мне больше всего нравится суп.": "Bütün yeməklərdən ən çox şorbanı bəyənirəm.",
