  "Рыбу я люблю больше.": "Balığı daha çox sevirəm.",
  "gern → lieber: люблю больше.": "gern → lieber: daha çox sevirəm.",
  "Ты больше любишь чай или кофе?": "Sən çayı daha çox sevirsən, yoxsa qəhvəni?",
  "lieber — когда выбираешь из двух вариантов.": "lieber — iki variantdan birini seçəndə.",
  "am liebsten — больше всего; стоит на первом месте, а глагол — на втором.": "am liebsten — ən çox; birinci yerdə durur, feil isə ikinci yerdə.",
  "Больше всего я люблю пить чай.": "Ən çox çay içməyi sevirəm.",
