  "Что человек берёт на основное блюдо?": "Adam əsas yeməyə nə götürür?",
  "Рыбу с картошкой": "Kartofla balıq",
  "Суп": "Şorba",
  "Курицу с рисом": "Düyü ilə toyuq",
  "На закуску я возьму суп, а на основное блюдо — рыбу с картошкой.": "Qəlyanaltıya şorba götürəcəyəm, əsas yeməyə isə kartofla balıq.",
  "После mehr и любой сравнительной степени — только als.": "mehr sözündən və istənilən müqayisə dərəcəsindən sonra yalnız als olur.",
