  "Курица вкуснее рыбы.": "Toyuq balıqdan dadlıdır.",
  "Мы хотим заплатить вместе.": "Biz birlikdə ödəmək istəyirik.",
  "Счёт, пожалуйста.": "Hesab, zəhmət olmasa.",
