  "Я наелся, спасибо.": "Mən doymuşam, sağ olun.",
  "Я сыта, спасибо.": "Mən toxam, sağ ol.",
  "satt = сытый": "satt = tox",
  "Еда была очень вкусной.": "Yemək çox dadlı idi.",
  "Я хотел бы расплатиться, пожалуйста.": "Zəhmət olmasa, hesablaşmaq istərdim.",
  "В ресторане": "Restoranda",
  "Добрый вечер! Вы бронировали столик?": "Axşamınız xeyir! Masa rezerv etmisiniz?",
  "Добрый вечер. Да, на имя Эмиль, столик на двоих.": "Axşamınız xeyir. Bəli, Emil adına, iki nəfərlik masa.",
  "Очень хорошо. Вот ваш столик, а вот меню.": "Çox gözəl. Budur sizin masanız, bu da menyu.",
  "Спасибо. Что вы можете нам посоветовать?": "Təşəkkür edirəm. Bizə nə məsləhət görə bilərsiniz?",
  "На закуску у нас сегодня салат с сыром. Из основных блюд лучше всего курица с рисом.": "Qəlyanaltı olaraq bu gün pendirli salatımız var. Əsas yeməklərdən ən yaxşısı düyü ilə toyuqdur.",
  "Курица острая? Я не очень люблю острое.": "Toyuq acıdır? Mən acı yeməyi o qədər də sevmirəm.",
  "Нет, рыба намного острее курицы.": "Xeyr, balıq toyuqdan xeyli acıdır.",
  "Тогда я возьму курицу. Принесите мне, пожалуйста, ещё хлеб и соль.": "Onda toyuq götürəcəyəm. Zəhmət olmasa, mənə bir az da çörək və duz gətirin.",
  "С удовольствием. Хотите потом ещё попробовать десерт?": "Məmnuniyyətlə. Sonra desertin də dadına baxmaq istəyirsiniz?",
  "Может быть. Ресторан мне нравится, здесь тише, чем в центре.": "Bəlkə. Restoran xoşuma gəlir, burada mərkəzdəkindən sakitdir.",
  "Я рад. А еда вам понравилась?": "Sevindim. Bəs yemək xoşunuza gəldi?",
  "Было очень вкусно. Можно расплатиться?": "Çox dadlı idi. Hesablaşmaq olar?",
  "Заказ в ресторане": "Restoranda sifariş",
  "Ты сидишь в ресторане, Мия — официантка. Сделай заказ: скажи, что хочешь заказать, выбери основное блюдо, скажи, что ты любишь больше — рис или картошку, закажи напиток. В конце скажи, что было вкусно, что ты наелся, и попроси счёт.": "Sən restoranda oturmusan, Mia isə ofisiantdır. Sifariş ver: nə sifariş etmək istədiyini de, əsas yeməyi seç, düyünü, yoxsa kartofu daha çox sevdiyini de, içki sifariş et. Sonda dadlı olduğunu, doyduğunu de və hesabı istə.",
  "Я хотел бы сделать заказ.": "Mən sifariş vermək istərdim.",
  "На основное блюдо я возьму курицу.": "Əsas yeməyə toyuq götürəcəyəm.",
  "Картошку я люблю больше, чем рис.": "Kartofu düyüdən daha çox sevirəm.",
  "Это очень острое?": "Bu çox acıdır?",
  "Было очень вкусно.": "Çox dadlı idi.",
  "Нет, спасибо, я наелся.": "Xeyr, sağ olun, mən doymuşam.",
  "Добрый вечер! Рада вас видеть. Вы уже готовы сделать заказ?": "Axşamınız xeyir! Sizi gördüyümə şadam. Sifariş verməyə hazırsınız?",
  "С удовольствием. Что вы возьмёте на основное блюдо?": "Məmnuniyyətlə. Əsas yeməyə nə götürəcəksiniz?",
  "Хороший выбор. Что вы больше любите на гарнир — рис или картошку?": "Yaxşı seçimdir. Qarnir olaraq nəyi daha çox sevirsiniz — düyünü, yoxsa kartofu?",
  "Хотите ещё закуску? Суп сегодня очень хороший.": "Qəlyanaltı da istəyirsiniz? Şorba bu gün çox yaxşıdır.",
  "А что вы будете пить?": "Bəs nə içəcəksiniz?",
  "Ну как, еда вам понравилась?": "Necədir, yemək xoşunuza gəldi?",
  "Очень приятно! Хотите ещё десерт?": "Çox məmnunam! Desert də istəyirsiniz?",
  "С вас 19 евро. Большое спасибо и хорошего вечера, Эмиль! До скорого!": "Sizdən 19 avro. Çox sağ olun və xoş axşamlar, Emil! Tezliklə görüşərik!",
  "После сравнительной степени всегда als, а не wie.": "Müqayisə dərəcəsindən sonra həmişə als olur, wie yox.",
  "Эмиль любит макароны, но картошку он любит больше.": "Emil makaronu sevir, amma kartofu daha çox sevir.",
  "gut – besser – am besten, форму надо выучить наизусть.": "gut – besser – am besten, formanı əzbər öyrənmək lazımdır.",
  "Что вы можете посоветовать?": "Nə məsləhət görə bilərsiniz?",
  "empfehlen = советовать": "empfehlen = məsləhət görmək",
  "Сколько сегодня стоит курица?": "Toyuq bu gün neçəyədir?",
  "девять евро": "doqquz avro",
  "десять евро": "on avro",
  "девятнадцать евро": "on doqquz avro",
  "Сегодня курица дешевле, чем вчера. Она стоит всего девять евро.": "Bu gün toyuq dünənkindən ucuzdur. Cəmi doqquz avrodur.",
  "Хлеб здесь такой же свежий, как в супермаркете.": "Burada çörək supermarketdəki qədər təzədir.",
  "genauso … wie — при равном сравнении.": "genauso … wie — bərabər müqayisədə.",
  "Emil sagt: «Ich bin satt.» Что это значит?": "Emil sagt: «Ich bin satt.» Bu nə deməkdir?",
  "Он голоден.": "O acdır.",
  "Он наелся.": "O doyub.",
  "Он хочет пить.": "O susayıb.",
  "satt — сытый, наевшийся.": "satt — tox, doymuş.",
  "Я ем больше овощей, чем мяса.": "Mən ətdən çox tərəvəz yeyirəm.",
  "Овощей я ем больше, чем мяса.": "Tərəvəzi ətdən daha çox yeyirəm.",
  "Я ем овощей больше, чем мяса.": "Mən tərəvəzi ətdən daha artıq yeyirəm.",
  "Путешествия и транспорт": "Səyahət və nəqliyyat",
  "В этом уровне ты разберёшься с немецким транспортом: как спросить про поезд, пересадку и платформу, что говорят в объявлениях на вокзале и что делать, если ты опоздал на автобус. Заодно выучишь Präteritum (war, hatte, musste, konnte) и предлоги, которые нужны в дороге.": "Bu səviyyədə alman nəqliyyatı ilə baş açacaqsan: qatar, dəyişmə və platforma haqqında necə soruşmaq lazımdır, vağzaldakı elanlarda nə deyirlər və avtobusa gecikmisənsə, nə etməli. Eyni zamanda Präteritum-u (war, hatte, musste, konnte) və yolda lazım olan sözönülərini öyrənəcəksən.",
  "Спросить про поезд, пересадку и платформу и купить билет": "Qatar, dəyişmə və platforma haqqında soruşmaq və bilet almaq",
  "Понять объявление о задержке и найти другой маршрут": "Gecikmə haqqında elanı başa düşmək və başqa marşrut tapmaq",
  "Рассказать о прошлой поездке в Präteritum: war, hatte, musste, konnte": "Keçmiş səfər haqqında Präteritum-da danışmaq: war, hatte, musste, konnte",
  "Сказать, на чём и куда ты едешь: mit dem Zug, zum Bahnhof, in den Bus": "Nə ilə və hara getdiyini demək: mit dem Zug, zum Bahnhof, in den Bus",
