  "вовремя, пунктуальный": "vaxtında, dəqiq",
  "Автобус сегодня был вовремя.": "Avtobus bu gün vaxtında idi.",
  "Покажите, пожалуйста, ваше удостоверение и билет.": "Zəhmət olmasa, şəxsiyyət vəsiqənizi və biletinizi göstərin.",
  "длиться, занимать (о времени)": "davam etmək, çəkmək (vaxt haqqında)",
  "Поездка в аэропорт занимает сорок минут.": "Hava limanına səfər qırx dəqiqə çəkir.",
  "опоздать на, пропустить": "gecikmək, buraxmaq",
  "Эмиль сегодня утром опоздал на автобус.": "Emil bu gün səhər avtobusa gecikdi.",
  "успеть на (транспорт), добраться": "(nəqliyyata) çatmaq, yetişmək",
  "Если мы пойдём сейчас, мы ещё успеем на поезд.": "İndi getsək, qatara hələ çatarıq.",
  "объявление (по громкой связи)": "elan (səsucaldandan)",
  "В объявлении говорят, что поезд опаздывает.": "Elanda deyirlər ki, qatar gecikir.",
  "Präteritum: war, hatte и модальные глаголы": "Präteritum: war, hatte və modal feillər",
  "О прошлом немцы обычно говорят в Perfekt (Ich habe gearbeitet). Но у трёх групп глаголов есть своя простая форма прошедшего времени — Präteritum, и в разговоре используют именно её: sein → war, haben → hatte и все модальные глаголы.\nУ модальных глаголов в Präteritum умлаут исчезает и появляется -t-: müssen → musste, können → konnte, dürfen → durfte, wollen → wollte, sollen → sollte, mögen → mochte.\nЗапомни главное: формы ich и er/sie/es всегда одинаковые и без окончания. Порядок слов не меняется, а инфинитив при модальном глаголе по-прежнему стоит в конце: Wir mussten umsteigen.": "Almanlar keçmiş haqqında adətən Perfekt-də danışırlar (Ich habe gearbeitet). Amma üç qrup feilin öz sadə keçmiş zaman forması var — Präteritum, və danışıqda məhz ondan istifadə edirlər: sein → war, haben → hatte və bütün modal feillər.\nModal feillərdə Präteritum-da umlaut yox olur və -t- peyda olur: müssen → musste, können → konnte, dürfen → durfte, wollen → wollte, sollen → sollte, mögen → mochte.\nƏsas şeyi yadda saxla: ich və er/sie/es formaları həmişə eynidir və şəkilçisizdir. Söz sırası dəyişmir, modal feilin yanındakı məsdər isə yenə də sonda durur: Wir mussten umsteigen.",
  "Вчера я час простоял в пробке.": "Dünən bir saat tıxacda dayandım.",
  "Нам пришлось сделать пересадку в Ганновере.": "Hannoverdə nəqliyyatı dəyişməli olduq.",
  "Эмиль уже не смог успеть на поезд.": "Emil artıq qatara çata bilmədi.",
  "У меня не было билета, и мне пришлось заплатить.": "Biletim yox idi və pul ödəməli oldum.",
  "На чём и куда: mit dem Zug, zum Bahnhof, nach Berlin": "Nə ilə və hara: mit dem Zug, zum Bahnhof, nach Berlin",
  "На чём ты едешь — это mit + Dativ: mit dem Bus, mit dem Zug, mit dem Auto, mit dem Fahrrad, mit der U-Bahn, mit der S-Bahn. Исключение одно: пешком — просто zu Fuß, без mit.\nКуда ты едешь? К месту в городе или к человеку — zu + Dativ: zu dem = zum (zum Bahnhof, zum Arzt), zu der = zur (zur Haltestelle, zur Arbeit). В город или страну — nach: nach Berlin, nach Italien. Домой — всегда nach Hause, а дома — zu Hause.\nГде ты стоишь и ждёшь — an + Dativ: an der Haltestelle, am Gleis.": "Nə ilə getdiyin — bu mit + Dativ-dir: mit dem Bus, mit dem Zug, mit dem Auto, mit dem Fahrrad, mit der U-Bahn, mit der S-Bahn. Bir istisna var: piyada — sadəcə zu Fuß, mit olmadan.\nHara gedirsən? Şəhərdəki bir yerə və ya bir adamın yanına — zu + Dativ: zu dem = zum (zum Bahnhof, zum Arzt), zu der = zur (zur Haltestelle, zur Arbeit). Şəhərə və ya ölkəyə — nach: nach Berlin, nach Italien. Evə — həmişə nach Hause, evdə isə — zu Hause.\nHarada dayanıb gözlədiyin — an + Dativ: an der Haltestelle, am Gleis.",
  "Womit? (на чём?)": "Womit? (nə ilə?)",
  "Wohin? (к месту)": "Wohin? (bir yerə)",
  "Wohin? (город)": "Wohin? (şəhər)",
  "Wohin? (домой)": "Wohin? (evə)",
  "Wo? (дома)": "Wo? (evdə)",
  "Пешком": "Piyada",
  "Эмиль ездит на электричке на работу.": "Emil işə elektrik qatarı ilə gedir.",
  "Как мне добраться до главного вокзала?": "Mərkəzi vağzala necə çata bilərəm?",
  "После работы я сразу еду домой.": "İşdən sonra dərhal evə gedirəm.",
  "До остановки я иду пешком.": "Dayanacağa qədər piyada gedirəm.",
  "Wohin? или Wo? — in den Bus einsteigen, im Bus sitzen": "Wohin? yoxsa Wo? — in den Bus einsteigen, im Bus sitzen",
  "Предлоги in, an, auf, vor, hinter, neben, über, unter, zwischen называют «двойными» (Wechselpräpositionen). После них стоит то Akkusativ, то Dativ — и выбор зависит от вопроса.\nWohin? (куда, есть движение к месту) → Akkusativ: Ich steige in den Bus ein. Wo? (где, ты уже там) → Dativ: Ich sitze im Bus (in dem = im).\nДва предлога сомнений не вызывают: aus и mit всегда с Dativ — aus dem Zug aussteigen, mit dem Zug fahren.": "in, an, auf, vor, hinter, neben, über, unter, zwischen sözönülərinə «ikili» (Wechselpräpositionen) deyirlər. Onlardan sonra gah Akkusativ, gah Dativ durur — seçim isə sualdan asılıdır.\nWohin? (hara, bir yerə doğru hərəkət var) → Akkusativ: Ich steige in den Bus ein. Wo? (harada, sən artıq oradasan) → Dativ: Ich sitze im Bus (in dem = im).\nİki sözönü şübhə doğurmur: aus və mit həmişə Dativ ilə işlənir — aus dem Zug aussteigen, mit dem Zug fahren.",
