  "Поезд в Гамбург сегодня опаздывает на двадцать минут. Пожалуйста, подождите на платформе.": "Hamburqa gedən qatar bu gün iyirmi dəqiqə gecikir. Zəhmət olmasa, platformada gözləyin.",
