  "Как будет «я не смог» — Präteritum от können для ich?": "«mən bacarmadım» necə olur — ich üçün können feilinin Präteritum forması?",
  "konnte — смог; könnte — «мог бы»; kannte — знал (от kennen).": "konnte — bacardı; könnte — «bacarardı»; kannte — tanıyırdı (kennen feilindən).",
  "У Эмиля вчера не было билета.": "Emilin dünən bileti yox idi.",
