  "Эмиль опоздал на автобус.": "Emil avtobusa gecikdi.",
  "Вчера мы были на вокзале.": "Dünən biz vağzalda idik.",
  "waren = были": "waren = idilər",
  "Сегодня мне пришлось ехать на автобусе.": "Bu gün avtobusla getməli oldum.",
