  "Не забудьте прокомпостировать билет!": "Bileti təsdiqləməyi unutmayın!",
  "entwerten — прокомпостировать билет в автомате.": "entwerten — avtomatda bileti təsdiqləmək.",
  "Есть хорошее сообщение до Бонна.": "Bonna yaxşı nəqliyyat əlaqəsi var.",
  "Я не успел на пересадку.": "Mən əlaqəli reysə çata bilmədim.",
  "Я пропустил пересадку.": "Mən əlaqəli reysi buraxdım.",
