  "Я не успел на следующий поезд.": "Mən növbəti qatara çatmadım.",
  "der Anschluss = пересадка": "der Anschluss = əlaqəli reys",
  "Что нужно сделать пассажирам?": "Sərnişinlər nə etməlidirlər?",
  "Выйти на главном вокзале": "Mərkəzi vağzalda düşmək",
  "Сесть в поезд": "Qatara minmək",
  "Купить билет": "Bilet almaq",
  "Следующая остановка: главный вокзал. Пожалуйста, выходите здесь.": "Növbəti dayanacaq: mərkəzi vağzal. Zəhmət olmasa, burada düşün.",
  "Где мне нужно пересесть?": "Harada nəqliyyatı dəyişməliyəm?",
  "У меня есть проездной на месяц.": "Mənim aylıq gediş biletim var.",
  "Эмиль едет на автобусе на вокзал.": "Emil vağzala avtobusla gedir.",
  "Объявление на платформе": "Platformada elan",
  "Мия, ты поняла объявление? Я услышал только «задержка».": "Mia, elanı başa düşdün? Mən yalnız «gecikmə» eşitdim.",
  "Да, поезд в Лейпциг опаздывает на тридцать минут.": "Bəli, Leyptsiqə gedən qatar otuz dəqiqə gecikir.",
  "О нет. Тогда я не успею на пересадку.": "Ay aman. Onda mən əlaqəli reysə çatmayacağam.",
  "Подожди, я посмотрю расписание. Есть ещё один маршрут.": "Dayan, hərəkət cədvəlinə baxım. Bir marşrut da var.",
  "И мне тогда нужно делать пересадку?": "Onda mən nəqliyyatı dəyişməli olacağam?",
  "Да, один раз. Ты пересядешь в Галле и будешь на месте в 18 часов.": "Bəli, bir dəfə. Sən Halledə nəqliyyatı dəyişəcəksən və saat 18-də yerində olacaqsan.",
  "Это хорошо. Вчера мне пришлось ждать два часа, это было действительно ужасно.": "Bu, yaxşıdır. Dünən iki saat gözləməli oldum, bu, həqiqətən dəhşətli idi.",
  "Сегодня тебе повезло. Другой поезд идёт вовремя и уже стоит у платформы, путь 4.": "Bu gün bəxtin gətirib. Digər qatar vaxtında gedir və artıq platformada dayanıb, yol 4.",
  "Тогда я быстро пойду. Где моё удостоверение? А, вот тут, в сумке.": "Onda tez gedim. Şəxsiyyət vəsiqəm haradadır? Ah, budur, çantadadır.",
  "Пассажиры уже садятся. Хорошей поездки, Эмиль!": "Sərnişinlər artıq minirlər. Yaxşı yol, Emil!",
  "Спасибо, Мия! До завтра.": "Sağ ol, Mia! Sabaha qədər.",
  "У справочной на вокзале": "Vağzaldakı məlumat bürosunda",
  "Ты опоздал на свой поезд и пришёл к справочной на вокзале. Мия работает за стойкой. Спроси, когда идёт следующий поезд в Лейпциг, купи билет туда и обратно, узнай, нужно ли делать пересадку, сколько длится поездка и с какой платформы отправляется поезд.": "Sən qatarına gecikdin və vağzaldakı məlumat bürosuna gəldin. Mia piştaxtanın arxasında işləyir. Soruş ki, Leyptsiqə növbəti qatar nə vaxt gedir, gediş-gəliş bileti al, nəqliyyatı dəyişmək lazım olub-olmadığını, səfərin nə qədər davam etdiyini və qatarın hansı platformadan yola düşdüyünü öyrən.",
  "Я опоздал на свой поезд.": "Mən qatarıma gecikdim.",
  "Когда идёт следующий поезд в Лейпциг?": "Leyptsiqə növbəti qatar nə vaxt gedir?",
  "Один билет туда и обратно, пожалуйста.": "Bir gediş-gəliş bileti, zəhmət olmasa.",
  "Мне нужно делать пересадку?": "Mən nəqliyyatı dəyişməliyəmmi?",
  "С какой платформы отправляется поезд?": "Qatar hansı platformadan yola düşür?",
  "Добрый день! Чем могу вам помочь?": "Günortanız xeyir! Sizə necə kömək edə bilərəm?",
  "Следующий поезд отправляется в 14:20. У вас уже есть билет?": "Növbəti qatar 14:20-də yola düşür. Sizin artıq biletiniz varmı?",
  "Ничего страшного. В одну сторону или туда и обратно?": "Eybi yoxdur. Bir tərəfə, yoxsa gediş-gəliş?",
  "Хорошо. Вы хотите ехать без пересадок или пересадка вас устроит?": "Yaxşı. Birbaşa getmək istəyirsiniz, yoxsa nəqliyyatı dəyişmək sizə uyğundur?",
  "Вы один раз пересядете в Галле. Поездка длится около трёх часов.": "Siz bir dəfə Halledə nəqliyyatı dəyişəcəksiniz. Səfər təxminən üç saat davam edir.",
  "С четвёртой платформы. Билет стоит 39 евро. Наличными или картой?": "Dördüncü platformadan. Bilet 39 avrodur. Nağd, yoxsa kartla?",
  "Спасибо. Вот ваш билет. Хорошей поездки, Эмиль! До свидания!": "Təşəkkür edirəm. Budur biletiniz. Yaxşı yol, Emil! Sağ olun!",
  "Präteritum от haben: er hatte — у него был / не было.": "haben feilinin Präteritum forması: er hatte — onun var idi / yox idi.",
  "Пассажиры садятся в поезд.": "Sərnişinlər qatara minirlər.",
