  "Я час простоял в пробке.": "Mən bir saat tıxacda dayandım.",
  "der Stau = пробка": "der Stau = tıxac",
  "В этом уровне ты научишься рассказывать о своих хобби, договариваться о встрече с друзьями и записываться в спортивный клуб. Главная грамматика — возвратные глаголы (sich freuen, sich treffen, sich interessieren) и местоимения mich, dich, sich, uns, euch.": "Bu səviyyədə sən hobbilərindən danışmağı, dostlarınla görüş barədə razılaşmağı və idman klubuna yazılmağı öyrənəcəksən. Əsas qrammatika — qayıdış feilləri (sich freuen, sich treffen, sich interessieren) və mich, dich, sich, uns, euch əvəzlikləri.",
