  "Правильно употреблять возвратные глаголы в настоящем времени и в Perfekt": "Qayıdış feillərini indiki zamanda və Perfekt-də düzgün işlətmək",
  "В свободное время я охотно играю в футбол.": "Boş vaxtımda həvəslə futbol oynayıram.",
