  "Для детей вход бесплатный.": "Uşaqlar üçün giriş pulsuzdur.",
  "хотеть чего-то, быть не прочь": "bir şey istəmək, həvəsi olmaq",
  "Хочешь сходить на концерт?": "Konsertə getmək istəyirsən?",
  "Возвратные глаголы: Reflexivpronomen в Akkusativ": "Qayıdış feilləri: Akkusativ-də Reflexivpronomen",
  "Многие немецкие глаголы идут вместе с маленьким словом sich: sich freuen (радоваться), sich treffen (встречаться), sich entspannen (расслабляться), sich langweilen (скучать). В словаре стоит форма sich, но в предложении это слово меняется вместе с лицом: ich → mich, du → dich, wir → uns, ihr → euch. У er/sie/es и у sie/Sie остаётся sich.\nПо-русски такие глаголы часто заканчиваются на -ся, но не всегда: sich langweilen — «скучать», sich interessieren — «интересоваться». Поэтому местоимение нужно учить вместе с глаголом.\nМестоимение стоит сразу после спрягаемого глагола: Ich freue mich. В вопросе — после подлежащего: Freust du dich?": "Bir çox alman feili kiçik bir sich sözü ilə birlikdə gəlir: sich freuen (sevinmək), sich treffen (görüşmək), sich entspannen (rahatlamaq), sich langweilen (darıxmaq). Lüğətdə sich forması yazılır, amma cümlədə bu söz şəxsə görə dəyişir: ich → mich, du → dich, wir → uns, ihr → euch. er/sie/es və sie/Sie ilə sich olduğu kimi qalır.\nAzərbaycan dilində belə feillər çox vaxt qayıdış şəkilçisi ilə düzəlir, amma həmişə yox: sich langweilen — «darıxmaq», sich interessieren — «maraqlanmaq». Ona görə də əvəzliyi feillə birlikdə öyrənmək lazımdır.\nƏvəzlik təsriflənən feildən dərhal sonra gəlir: Ich freue mich. Sualda isə mübtədadan sonra: Freust du dich?",
  "Я расслабляюсь вечером.": "Mən axşam rahatlayıram.",
  "Мы встречаемся в парке.": "Biz parkda görüşürük.",
  "Тебе скучно?": "Sən darıxırsan?",
  "Эмиль и Мия радуются.": "Emil və Mia sevinirlər.",
  "Какой предлог: für, auf, mit": "Hansı sözönü: für, auf, mit",
  "Возвратные глаголы обычно приходят с «своим» предлогом, и его нужно запомнить вместе с глаголом — он часто не совпадает с русским.\nsich interessieren für + Akkusativ — интересоваться чем-то. sich freuen auf + Akkusativ — ждать с нетерпением того, что будет. sich freuen über + Akkusativ — радоваться тому, что уже случилось. sich treffen mit + Dativ и sich verabreden mit + Dativ — встречаться и договариваться о встрече с кем-то.\nТа же логика у выражения Lust haben auf + Akkusativ — «быть не прочь, хотеть чего-то».": "Qayıdış feilləri adətən «öz» sözönü ilə gəlir və onu feillə birlikdə yadda saxlamaq lazımdır — o, çox vaxt Azərbaycan dilindəki ilə üst-üstə düşmür.\nsich interessieren für + Akkusativ — bir şeylə maraqlanmaq. sich freuen auf + Akkusativ — olacaq bir şeyi səbirsizliklə gözləmək. sich freuen über + Akkusativ — artıq baş vermiş bir şeyə sevinmək. sich treffen mit + Dativ və sich verabreden mit + Dativ — kiminləsə görüşmək və görüş barədə razılaşmaq.\nEyni məntiq Lust haben auf + Akkusativ ifadəsində də var — «həvəsi olmaq, bir şey istəmək».",
  "auf + Akkusativ (о будущем)": "auf + Akkusativ (gələcək haqqında)",
  "über + Akkusativ (о прошедшем)": "über + Akkusativ (keçmiş haqqında)",
  "Моя жена интересуется музыкой.": "Mənim həyat yoldaşım musiqi ilə maraqlanır.",
  "Мы с нетерпением ждём поездки.": "Biz səbirsizliklə gəzintini gözləyirik.",
  "Эмиль встречается со своими коллегами.": "Emil öz həmkarları ilə görüşür.",
  "Я не прочь сыграть в настольную игру.": "Stolüstü oyun oynamağa həvəsim var.",
  "Возвратные глаголы в Perfekt": "Perfekt-də qayıdış feilləri",
  "В Perfekt возвратные глаголы всегда идут с haben — даже sich treffen, хотя это как бы «движение». Местоимение (mich, dich, sich, uns, euch) стоит сразу после haben, а Partizip II уходит в конец: Ich habe mich gefreut.\nЕсли предложение начинается с обстоятельства времени, порядок такой: Gestern habe ich mich mit Mia getroffen. В вопросе местоимение идёт после подлежащего: Hast du dich angemeldet?\nОбрати внимание на Partizip II: у глаголов на -ieren и у приставок ver-, ent-, unter- нет приставки ge-: interessiert, verabredet, entspannt, unterhalten.": "Perfekt-də qayıdış feilləri həmişə haben ilə gəlir — hətta sich treffen də, baxmayaraq ki, bu, sanki «hərəkət»dir. Əvəzlik (mich, dich, sich, uns, euch) haben-dən dərhal sonra durur, Partizip II isə sona gedir: Ich habe mich gefreut.\nƏgər cümlə zaman zərfliyi ilə başlayırsa, sıra belə olur: Gestern habe ich mich mit Mia getroffen. Sualda əvəzlik mübtədadan sonra gəlir: Hast du dich angemeldet?\nPartizip II-yə diqqət et: -ieren ilə bitən feillərdə və ver-, ent-, unter- prefiksləri olan feillərdə ge- prefiksi olmur: interessiert, verabredet, entspannt, unterhalten.",
