  "schwimmen — плавать; grillen готовят в саду, а Fahrrad fahren — на улице.": "schwimmen — üzmək; grillen bağda edilir, Fahrrad fahren isə bayırda olur.",
  "На выходных мы катаемся на велосипеде.": "Həftəsonu biz velosiped sürürük.",
  "Не хочешь сходить на концерт?": "Konsertə getmək istəmirsən?",
