  "В спортивном клубе": "İdman klubunda",
  "Добрый день. Я интересуюсь футболом и хотел бы записаться.": "Xeyirli gün. Mən futbolla maraqlanıram və yazılmaq istərdim.",
  "С удовольствием. Вы раньше уже играли?": "Məmnuniyyətlə. Siz əvvəllər oynamısınız?",
  "Да, в Азербайджане я играл десять лет.": "Bəli, Azərbaycanda mən on il oynamışam.",
  "Это отлично. Наша команда тренируется по вторникам и четвергам в 19 часов.": "Bu əladır. Bizim komanda çərşənbə axşamı və cümə axşamı saat 19-da məşq edir.",
  "Мне это подходит. Сколько стоит год в клубе?": "Bu mənə uyğundur. Klubda bir il nə qədərdir?",
  "Двенадцать евро в месяц. Для детей дешевле.": "Ayda on iki avro. Uşaqlar üçün daha ucuzdur.",
  "Хорошо. А когда следующий матч?": "Yaxşı. Bəs növbəti matç nə vaxtdır?",
  "В субботу в 15 часов. Заходите!": "Şənbə günü saat 15-də. Gəlin!",
  "С удовольствием. Я с нетерпением жду тренировки.": "Məmnuniyyətlə. Mən səbirsizliklə məşqi gözləyirəm.",
  "Тогда увидимся во вторник. До встречи!": "Onda çərşənbə axşamı görüşərik. Görüşənədək!",
  "Большое спасибо. До вторника!": "Çox sağ olun. Çərşənbə axşamına qədər!",
  "Планы на выходные": "Həftəsonu planları",
  "Мия спрашивает тебя, чем ты занимаешься в свободное время, и предлагает сходить вместе в бассейн в субботу. Расскажи о своём хобби, скажи, как часто ты тренируешься, согласись или вежливо откажись, а потом договорись, во сколько и где вы встретитесь.": "Mia səndən boş vaxtında nə etdiyini soruşur və şənbə günü birlikdə hovuza getməyi təklif edir. Hobbin haqqında danış, nə qədər tez-tez məşq etdiyini de, razılaş və ya nəzakətlə imtina et, sonra isə saat neçədə və harada görüşəcəyinizi razılaşdır.",
  "В свободное время я играю в футбол.": "Boş vaxtımda mən futbol oynayıram.",
  "Я тренируюсь два раза в неделю.": "Mən həftədə iki dəfə məşq edirəm.",
  "Да, с удовольствием! Я пойду с тобой.": "Bəli, məmnuniyyətlə! Mən səninlə gedəcəyəm.",
  "Давай встретимся в десять часов?": "Gəl saat onda görüşək?",
  "Мы встретимся перед бассейном.": "Biz hovuzun qarşısında görüşəcəyik.",
  "Я с нетерпением жду субботы.": "Mən səbirsizliklə şənbəni gözləyirəm.",
  "Привет, Эмиль! Слушай, чем ты любишь заниматься в свободное время?": "Salam, Emil! De görüm, boş vaxtında nə etməyi xoşlayırsan?",
  "О, здорово! А как часто ты тренируешься?": "Oh, əladır! Bəs nə qədər tez-tez məşq edirsən?",
  "В субботу я иду в бассейн. Пойдёшь со мной?": "Şənbə günü mən hovuza gedirəm. Mənimlə gedərsən?",
  "Супер! А во сколько мы встретимся?": "Super! Bəs saat neçədə görüşəcəyik?",
  "Хорошо. А где мы встретимся?": "Yaxşı. Bəs harada görüşəcəyik?",
  "Всё понятно. Ты ждёшь выходных?": "Hər şey aydındır. Həftəsonunu səbirsizliklə gözləyirsən?",
  "Я тоже! До субботы, Эмиль. Пока!": "Mən də! Şənbəyə qədər, Emil. Hələlik!",
