  "В музее": "Muzeydə",
  "В субботу мы едем за город. Мы встречаемся в девять часов на вокзале.": "Şənbə günü biz şəhərdən kənara gedirik. Biz saat doqquzda vağzalda görüşürük.",
  "Мы договорились встретиться в субботу.": "Biz şənbə günü görüşməyə razılaşdıq.",
  "sich verabreden — возвратный глагол: wir → uns.": "sich verabreden — qayıdış feili: wir → uns.",
  "Тебе было скучно?": "Sən darıxdın?",
  "sich langweilen в Perfekt: hast du dich … gelangweilt": "Perfekt-də sich langweilen: hast du dich … gelangweilt",
  "Семья и отношения": "Ailə və münasibətlər",
  "В этом уровне ты научишься подробно рассказывать о своей семье: кто у тебя есть, кто где живёт, с кем ты хорошо ладишь и кому ты помогаешь. Главная грамматика — дательный падеж: формы meinem / meiner / meinen и четыре важных глагола helfen, danken, gehören, gefallen, после которых немцы всегда ставят Dativ.": "Bu səviyyədə ailən haqqında ətraflı danışmağı öyrənəcəksən: kimlərin var, kim harada yaşayır, kiminlə yaxşı yola gedirsən və kimə kömək edirsən. Əsas qrammatika — yönlük hal: meinem / meiner / meinen formaları və dörd vacib feil — helfen, danken, gehören, gefallen; almanlar bu feillərdən sonra həmişə Dativ işlədirlər.",
  "Рассказать о своей семье и расспросить о чужой": "Öz ailən haqqında danışmaq və başqasının ailəsi barədə soruşmaq",
  "Правильно говорить meinem, meiner, meinen в дательном падеже": "Yönlük halda meinem, meiner, meinen formalarını düzgün demək",
  "Сказать, кому ты помогаешь, кого благодаришь, кому что принадлежит и что кому нравится": "Kimə kömək etdiyini, kimə təşəkkür etdiyini, nəyin kimə aid olduğunu və nəyin kimin xoşuna gəldiyini demək",
  "Поздравить с днём рождения и вести себя в гостях у немецкой семьи": "Ad günü münasibətilə təbrik etmək və alman ailəsində qonaq olanda özünü necə aparmağı bilmək",
  "Моя семья для меня очень важна.": "Ailəm mənim üçün çox vacibdir.",
  "родители (мн. ч.)": "valideynlər (cəm)",
  "Родители Эмиль живут в Азербайджане.": "Emilin valideynləri Azərbaycanda yaşayırlar.",
  "братья и сёстры (мн. ч.)": "bacı-qardaşlar (cəm)",
  "Мои братья и сёстры живут не в Германии.": "Bacı-qardaşlarım Almaniyada yaşamırlar.",
  "Мой брат работает в Лейпциге.": "Qardaşım Leyptsiqdə işləyir.",
  "Сестра звонит мне каждое воскресенье.": "Bacım hər bazar günü mənə zəng edir.",
  "Наш сын уже ходит в школу.": "Oğlumuz artıq məktəbə gedir.",
  "Эмиль отводит дочь в детский сад.": "Emil qızını uşaq bağçasına aparır.",
  "жена, супруга": "arvad, həyat yoldaşı",
  "Его жену зовут Севиль.": "Onun arvadının adı Sevildir.",
  "муж, супруг": "ər, həyat yoldaşı",
  "Муж моей сестры — учитель.": "Bacımın əri müəllimdir.",
  "бабушка и дедушка (мн. ч.)": "nənə və baba (cəm)",
  "Мои бабушка и дедушка ещё живут в Баку.": "Nənəm və babam hələ də Bakıda yaşayırlar.",
  "Моя бабушка готовит лучше всех.": "Nənəm hamıdan yaxşı yemək bişirir.",
  "Моему дедушке 78 лет.": "Babamın 78 yaşı var.",
  "дядя": "əmi, dayı",
  "У моего дяди маленький ресторан.": "Əmimin kiçik restoranı var.",
  "тётя": "bibi, xala",
  "Я пишу тёте сообщение.": "Bibimə mesaj yazıram.",
  "двоюродная сестра": "əmiqızı, xalaqızı",
  "Моя двоюродная сестра учится в Гамбурге.": "Əmiqızım Hamburqda oxuyur.",
  "Наш сосед нам часто помогает.": "Qonşumuz bizə tez-tez kömək edir.",
  "Моего лучшего друга зовут Тимур.": "Ən yaxşı dostumun adı Timurdur.",
  "подруга; девушка (в паре)": "rəfiqə; sevgili (qız)",
  "Мой брат придёт со своей девушкой.": "Qardaşım sevgilisi ilə gələcək.",
