  "В анкете указано и семейное положение.": "Anketdə ailə vəziyyəti də göstərilir.",
  "Завтра у моей дочери день рождения.": "Sabah qızımın ad günüdür.",
  "подарок": "hədiyyə",
  "Подарок очень нравится моей жене.": "Hədiyyə arvadımın çox xoşuna gəlir.",
  "помогать (кому-то — Dativ)": "kömək etmək (kiməsə — Dativ)",
  "Я помогаю брату с переездом.": "Qardaşıma köçməkdə kömək edirəm.",
  "благодарить (кого-то — Dativ)": "təşəkkür etmək (kiməsə — Dativ)",
  "Спасибо тебе за твою помощь.": "Köməyin üçün sənə təşəkkür edirəm.",
  "принадлежать (кому-то — Dativ)": "aid olmaq (kiməsə — Dativ)",
  "Машина принадлежит моему отцу.": "Maşın atama aiddir.",
  "нравиться (кому-то — Dativ)": "xoşuna gəlmək (kiminsə — Dativ)",
  "Квартира нравится моей семье.": "Mənzil ailəmin xoşuna gəlir.",
  "навещать, ходить в гости": "baş çəkmək, qonaq getmək",
  "Мы навещаем мою тётю на выходных.": "Həftə sonu bibimə baş çəkirik.",
  "Мы приглашаем всю семью.": "Bütün ailəni dəvət edirik.",
  "жениться, выходить замуж": "evlənmək, ərə getmək",
  "Моя сестра выходит замуж летом.": "Bacım yayda ərə gedir.",
  "ладить с кем-то": "kiminləsə yola getmək",
  "Я хорошо лажу со своими соседями.": "Qonşularımla yaxşı yola gedirəm.",
  "Притяжательные слова в Dativ: meinem, meiner, meinen": "Yiyəlik əvəzlikləri Dativ-də: meinem, meiner, meinen",
  "Ты уже знаешь mein, meine, meinen в именительном и винительном падеже. В дательном (Dativ) окончания другие и их всего три.\nМужской и средний род → -em: meinem Bruder, meinem Kind. Женский род → -er: meiner Schwester. Множественное число → -en: meinen Eltern.\nТочно так же ведут себя dein, sein, ihr, unser, euer, Ihr: deinem Sohn, seiner Tochter, unseren Kindern.\nВажно: во множественном числе само существительное тоже получает -n, если его там ещё нет: die Kinder → meinen Kindern, die Brüder → meinen Brüdern. У Eltern и Geschwister -n уже есть.": "Sən artıq adlıq və təsirlik halda mein, meine, meinen formalarını bilirsən. Yönlük halda (Dativ) şəkilçilər başqadır və onlar cəmi üç dənədir.\nKişi və orta cins → -em: meinem Bruder, meinem Kind. Qadın cinsi → -er: meiner Schwester. Cəm → -en: meinen Eltern.\ndein, sein, ihr, unser, euer, Ihr də tam eyni cür davranır: deinem Sohn, seiner Tochter, unseren Kindern.\nVacib: cəmdə ismin özü də -n şəkilçisi alır, əgər orada hələ yoxdursa: die Kinder → meinen Kindern, die Brüder → meinen Brüdern. Eltern və Geschwister sözlərində -n onsuz da var.",
  "Род / число": "Cins / kəmiyyət",
  "мужской (der Bruder)": "kişi cinsi (der Bruder)",
  "средний (das Kind)": "orta cins (das Kind)",
  "женский (die Schwester)": "qadın cinsi (die Schwester)",
  "мн. ч. (die Eltern)": "cəm (die Eltern)",
  "мн. ч. (die Kinder)": "cəm (die Kinder)",
  "Я помогаю своему брату.": "Qardaşıma kömək edirəm.",
  "Телефон принадлежит моей сестре.": "Telefon bacıma aiddir.",
  "Эмиль едет со своими родителями в Гамбург.": "Emil valideynləri ilə Hamburqa gedir.",
  "Мы живём у нашей тёти.": "Bibimizin yanında yaşayırıq.",
  "Глаголы с Dativ: helfen, danken, gehören, gefallen": "Dativ tələb edən feillər: helfen, danken, gehören, gefallen",
  "По-русски мы говорим «помогать кому?», «благодарить кого?». По-немецки после этих глаголов всегда стоит Dativ — даже там, где русский требует винительного падежа. Ich danke dir (не «dich»).\nЛичные местоимения в Dativ: ich → mir, du → dir, er/es → ihm, sie → ihr, wir → uns, ihr → euch, sie/Sie → ihnen/Ihnen.\nОсобенно обрати внимание на gefallen: то, что нравится, — это подлежащее, а человек стоит в Dativ. Das Geschenk gefällt mir. Во множественном числе — gefallen: Die Fotos gefallen mir.\nВопрос к дательному падежу — wem? (кому?): Wem gehört das Auto?": "Burada Azərbaycan dili sənə kömək edir: bizdə də «kimə kömək edirəm?», «kimə təşəkkür edirəm?» deyilir — yönlük hal. Almanca da bu feillərdən sonra həmişə Dativ durur. Ich danke dir («dich» yox).\nDativ-də şəxs əvəzlikləri: ich → mir, du → dir, er/es → ihm, sie → ihr, wir → uns, ihr → euch, sie/Sie → ihnen/Ihnen.\nXüsusilə gefallen feilinə diqqət et: xoşa gələn şey mübtədadır, insan isə Dativ-də durur. Das Geschenk gefällt mir. Cəmdə — gefallen: Die Fotos gefallen mir.\nYönlük hala verilən sual — wem? (kimə?): Wem gehört das Auto?",
  "Я помогаю маме.": "Anama kömək edirəm.",
  "Спасибо тебе за подарок.": "Hədiyyə üçün sənə təşəkkür edirəm.",
  "Город нравится моим родителям.": "Şəhər valideynlərimin xoşuna gəlir.",
  "Я поздравляю свою тётю.": "Bibimi təbrik edirəm.",
  "Ты можешь мне помочь?": "Mənə kömək edə bilərsən?",
  "Кому принадлежит эта сумка?": "Bu çanta kimə aiddir?",
  "Берлин нравится моей жене.": "Berlin arvadımın xoşuna gəlir.",
  "Благодарю вас за приглашение.": "Dəvətiniz üçün sizə təşəkkür edirəm.",
  "Dativ после предлогов mit, bei, von, zu": "mit, bei, von, zu sözönülərindən sonra Dativ",
  "Предлоги mit (с), bei (у), von (от), zu (к), seit (с какого-то времени) и nach (после) всегда требуют Dativ. Именно с ними ты чаще всего и будешь говорить о семье.\nДва предлога сливаются с артиклем: zu dem → zum, zu der → zur, bei dem → beim. Но если стоит притяжательное слово, сливать нечего: zu meiner Tante, bei meinem Onkel.\nЗапомни разницу: zu — к человеку (zu meinen Großeltern), nach — в город или страну (nach Hamburg).": "mit (ilə), bei (yanında), von (-dan), zu (-ın yanına), seit (hansısa vaxtdan bəri) və nach (sonra) sözönüləri həmişə Dativ tələb edir. Ailə haqqında danışanda ən çox məhz onlardan istifadə edəcəksən.\nİki sözönü artikllə birləşir: zu dem → zum, zu der → zur, bei dem → beim. Amma yanında yiyəlik əvəzliyi durursa, birləşdirməyə bir şey qalmır: zu meiner Tante, bei meinem Onkel.\nFərqi yadda saxla: zu — insanın yanına (zu meinen Großeltern), nach — şəhərə və ya ölkəyə (nach Hamburg).",
  "с моим братом": "qardaşımla",
  "у моей бабушки": "nənəmin yanında",
