  "die Ehefrau — жена, супруга.": "die Ehefrau — arvad, həyat yoldaşı.",
  "разведён": "boşanmış",
  "В анкете есть строка «Familienstand». Что напишет там Эмиль, если у него есть жена?": "Anketdə «Familienstand» sətri var. Arvadı varsa, Emil orada nə yazacaq?",
  "der Familienstand — семейное положение; есть жена значит verheiratet.": "der Familienstand — ailə vəziyyəti; arvadı varsa, deməli verheiratet.",
  "helfen требует Dativ, der Bruder — мужской род: seinem Bruder.": "helfen Dativ tələb edir, der Bruder isə kişi cinsidir: seinem Bruder.",
  "Я часто помогаю маме по дому.": "Ev işlərində anama tez-tez kömək edirəm.",
  "Женский род в Dativ → meiner.": "Qadın cinsi Dativ-də → meiner.",
