  "Как часто они навещают брата?": "Qardaşına nə vaxtdan bir baş çəkirlər?",
  "каждое лето": "hər yay",
  "каждую неделю": "hər həftə",
  "каждый месяц": "hər ay",
  "Мой брат живёт в Мюнхене. Мы навещаем его каждое лето с детьми.": "Qardaşım Münhendə yaşayır. Hər yay uşaqlarla ona baş çəkirik.",
  "Эмиль помогает своему соседу в саду.": "Emil bağda qonşusuna kömək edir.",
