  "Мне это принадлежит.": "Bu mənə aiddir.",
  "Я этому помогаю.": "Mən buna kömək edirəm.",
  "gefallen — нравиться; mir — мне.": "gefallen — xoşa gəlmək; mir — mənə.",
  "Мои родители часто мне помогают.": "Valideynlərim mənə tez-tez kömək edirlər.",
  "Мои родители мне часто помогают.": "Valideynlərim tez-tez mənə kömək edir.",
  "Родители часто мне помогают.": "Valideynlər mənə tez-tez kömək edirlər.",
  "Учёба и курсы": "Təhsil və kurslar",
  "В этом уровне ты научишься записываться на языковой курс, говорить о своём уровне, об экзамене и о том, как ты учишься. Грамматика: придаточные с wenn и als, а также связки deshalb и trotzdem.": "Bu səviyyədə dil kursuna yazılmağı, öz səviyyən, imtahan və necə oxuduğun barədə danışmağı öyrənəcəksən. Qrammatika: wenn və als ilə budaq cümlələr, həmçinin deshalb və trotzdem bağlayıcı sözləri.",
  "Записаться на курс и спросить про расписание и оплату": "Kursa yazılmaq, dərs cədvəli və ödəniş barədə soruşmaq",
  "Рассказать, когда и как ты учишь немецкий": "Alman dilini nə vaxt və necə öyrəndiyini danışmaq",
  "Строить предложения с wenn и als («когда»)": "wenn və als («nə vaxt») ilə cümlələr qurmaq",
  "Связывать мысли словами deshalb (поэтому) и trotzdem (всё равно)": "Fikirləri deshalb (buna görə) və trotzdem (hər halda) sözləri ilə bağlamaq",
  "курс": "kurs",
  "Курс начинается в понедельник.": "Kurs bazar ertəsi başlayır.",
  "языковой курс": "dil kursu",
  "Эмиль ходит на языковой курс по вечерам.": "Emil axşamlar dil kursuna gedir.",
