  "Народный университет находится рядом с ратушей.": "Xalq universiteti bələdiyyə binasının yanındadır.",
  "повышение квалификации": "ixtisasartırma",
  "Моя фирма оплачивает повышение квалификации.": "Firmam ixtisasartırmanın haqqını ödəyir.",
  "занятия, уроки": "məşğələlər, dərslər",
  "Занятие длится два часа.": "Dərs iki saat davam edir.",
  "запись, регистрация": "qeydiyyat",
  "Запись возможна до пятницы.": "Qeydiyyat cümə gününə qədər mümkündür.",
  "плата, взнос": "haqq, ödəniş",
  "Плата за курс — 240 евро.": "Kurs haqqı — 240 avro.",
  "Вот расписание вечернего курса.": "Budur axşam kursunun dərs cədvəli.",
  "Экзамен 12 июня.": "İmtahan 12 iyundadır.",
  "сертификат": "sertifikat",
  "Без сертификата я не найду хорошее место.": "Sertifikat olmadan yaxşı iş yeri tapmayacağam.",
