  "Я ещё делаю много ошибок, когда говорю.": "Danışanda hələ çox səhv edirəm.",
  "домашнее задание": "ev tapşırığı",
  "Домашние задания я всегда делаю вечером.": "Ev tapşırıqlarını həmişə axşam edirəm.",
  "словарь": "lüğət",
  "Мой словарь лежит на столе.": "Lüğətim masanın üstündədir.",
  "грамматика": "qrammatika",
  "Немецкая грамматика вначале трудная.": "Alman qrammatikası əvvəlcə çətindir.",
  "Твоё произношение уже намного лучше.": "Tələffüzün artıq xeyli daha yaxşıdır.",
