  "Для этой должности нужны хорошие знания немецкого.": "Bu vəzifə üçün yaxşı alman dili bilikləri lazımdır.",
  "участник": "iştirakçı",
  "На курсе двенадцать участников.": "Kursda on iki iştirakçı var.",
