  "Преподаватель курса родом из Лейпцига.": "Kurs müəllimi Leyptsiqdəndir.",
  "Мой уровень сейчас A2.": "Səviyyəm indi A2-dir.",
  "Я записываюсь на вечерний курс.": "Axşam kursuna yazılıram.",
