  "Эмиль посещает вечерний курс.": "Emil axşam kursuna gedir.",
  "тренировать, заниматься": "məşq etmək, çalışmaq",
  "Эмиль тренирует произношение в приложении.": "Emil tələffüzünü tətbiqdə məşq edir.",
