  "В выходные я повторяю слова.": "Həftəsonu sözləri təkrar edirəm.",
  "готовиться (auf + Akkusativ)": "hazırlaşmaq (auf + Akkusativ)",
  "Я каждый вечер готовлюсь к экзамену.": "Hər axşam imtahana hazırlaşıram.",
  "сдать (экзамен)": "(imtahandan) keçmək",
  "Эмиль сдал экзамен в июне.": "Emil imtahandan iyunda keçdi.",
  "не сдать, провалить экзамен": "imtahandan keçməmək, imtahanda kəsilmək",
  "В первый раз он не сдал.": "Birinci dəfə keçə bilmədi.",
