  "Я поздравляю тебя с днём рождения.": "Səni ad günün münasibətilə təbrik edirəm.",
  "Поздравляю! / От души поздравляю!": "Təbrik edirəm! / Ürəkdən təbrik edirəm!",
  "Поздравляю, Эмиль!": "Təbrik edirəm, Emil!",
  "сюрприз": "sürpriz",
  "Подарок был приятным сюрпризом.": "Hədiyyə xoş bir sürpriz oldu.",
