  "На Рождество мы остаёмся дома.": "Milad bayramında biz evdə qalırıq.",
  "новогодняя ночь, 31 декабря": "yeni il gecəsi, 31 dekabr",
  "В новогоднюю ночь мы празднуем с друзьями.": "Yeni il gecəsi biz dostlarla qeyd edirik.",
  "свадьба": "toy",
  "Свадьба была в июне.": "Toy iyunda oldu.",
  "ждать с нетерпением (то, что ещё впереди)": "səbirsizliklə gözləmək (hələ qabaqda olanı)",
  "Дети с нетерпением ждут Рождества.": "Uşaqlar Milad bayramını səbirsizliklə gözləyirlər.",
