  "Мия рада цветам.": "Mia güllərə sevinir.",
  "ждать (кого-то, что-то)": "gözləmək (kimisə, nəyisə)",
  "Мы ждём гостей.": "Biz qonaqları gözləyirik.",
  "говорить о (чём-то)": "(nəsə) haqqında danışmaq",
  "За кофе мы говорим о работе.": "Qəhvə içə-içə biz iş haqqında danışırıq.",
  "Эмиль интересуется футболом.": "Emil futbolla maraqlanır.",
  "Мне что-нибудь принести?": "Özümlə nəsə gətirim?",
  "отменить, отказаться (от встречи)": "ləğv etmək, imtina etmək (görüşdən)",
  "К сожалению, мне придётся отменить встречу.": "Təəssüf ki, görüşü ləğv etməliyəm.",
  "На свадьбе мы много танцевали.": "Toyda biz çox rəqs etdik.",
  "настроение, атмосфера": "ovqat, atmosfer",
  "Атмосфера на празднике была отличная.": "Şənlikdə atmosfer əla idi.",
  "лёгкий разговор ни о чём": "yüngül, mövzusuz söhbət",
  "В лёгком разговоре говорят о погоде.": "Yüngül söhbətdə hava haqqında danışırlar.",
  "Глаголы с фиксированными предлогами": "Sabit sözönü ilə işlənən feillər",
  "У многих немецких глаголов предлог «приклеен» намертво, и переводить его отдельно нельзя. Warten auf — это «ждать», хотя auf значит «на». Такой глагол нужно учить сразу с предлогом и падежом.\nПочти все предлоги в этом списке требуют Akkusativ: auf den Bus, über die Arbeit, für Fußball. Только zu идёт с Dativ, и там часто получается zum (zu + dem) или zur (zu + der).\nРазница auf / über у sich freuen важная: auf — о том, что ещё впереди, über — о том, что уже случилось или уже в руках.": "Bir çox alman feilində sözönü ona möhkəm «yapışıb» və onu ayrıca tərcümə etmək olmaz. Warten auf — bu «gözləmək» deməkdir, baxmayaraq ki, auf «üstündə» mənasını verir. Belə feili dərhal sözönü və halı ilə birlikdə öyrənmək lazımdır.\nBu siyahıdakı sözönlərinin demək olar ki, hamısı Akkusativ tələb edir: auf den Bus, über die Arbeit, für Fußball. Yalnız zu Dativ ilə işlənir və orada tez-tez zum (zu + dem) və ya zur (zu + der) alınır.\nSich freuen feilində auf / über fərqi vacibdir: auf — hələ qabaqda olan şey haqqında, über — artıq baş vermiş və ya artıq əlində olan şey haqqında.",
  "Глагол + предлог": "Feil + sözönü",
  "ждать кого-то, что-то": "kimisə, nəyisə gözləmək",
  "ждать с нетерпением": "səbirsizliklə gözləmək",
  "радоваться чему-то": "nəyəsə sevinmək",
  "говорить о чём-то": "nəsə haqqında danışmaq",
  "интересоваться чем-то": "nəyləsə maraqlanmaq",
  "думать о ком-то, о чём-то": "kimsə, nəsə haqqında düşünmək",
  "приглашать на что-то": "nəyəsə dəvət etmək",
  "поздравлять с чем-то": "nəyəsə görə təbrik etmək",
  "Эмиль ждёт автобус домой.": "Emil evə gedən avtobusu gözləyir.",
  "Мы с нетерпением ждём отпуска летом.": "Biz yaydakı məzuniyyəti səbirsizliklə gözləyirik.",
  "Мия обрадовалась цветам.": "Mia güllərə sevindi.",
  "Ты интересуешься футболом?": "Sən futbolla maraqlanırsan?",
  "Perfekt: повторение": "Perfekt: təkrar",
  "О празднике почти всегда рассказывают в Perfekt: вспомогательный глагол haben или sein на втором месте, Partizip II — в самом конце.\nС sein идут глаголы движения и перемены состояния: kommen, gehen, fahren, bleiben. Всё остальное — с haben.\nФормы Partizip II: правильные глаголы ge- + основа + -t (feiern → gefeiert), сильные ge- + …-en (sprechen → gesprochen). У глаголов с отделяемой приставкой ge- прячется в середину: einladen → eingeladen, mitbringen → mitgebracht. А глаголы на -ieren приставку ge- вообще не берут: gratulieren → gratuliert.": "Bayram haqqında demək olar ki, həmişə Perfekt-də danışırlar: köməkçi feil haben və ya sein ikinci yerdə, Partizip II isə lap sonda olur.\nSein ilə hərəkət və vəziyyət dəyişməsi bildirən feillər işlənir: kommen, gehen, fahren, bleiben. Qalan hamısı — haben ilə.\nPartizip II formaları: qaydalı feillər ge- + kök + -t (feiern → gefeiert), güclü feillər ge- + …-en (sprechen → gesprochen). Ayrılan prefiksi olan feillərdə ge- ortaya gizlənir: einladen → eingeladen, mitbringen → mitgebracht. -ieren ilə bitən feillər isə ge- prefiksini ümumiyyətlə qəbul etmir: gratulieren → gratuliert.",
  "Мы праздновали до одиннадцати часов.": "Biz saat on birə qədər qeyd etdik.",
  "Эмиль принёс торт.": "Emil tort gətirdi.",
  "Все гости пришли вовремя.": "Bütün qonaqlar vaxtında gəldi.",
  "Придаточные с weil, dass, wenn": "weil, dass, wenn ilə budaq cümlələr",
  "После weil (потому что), dass (что) и wenn (если, когда) спрягаемый глагол уходит в самый конец придаточного, а перед союзом всегда стоит запятая.\nЕсли в придаточном Perfekt, то в конец уходит haben или sein: …, weil ich gearbeitet habe. Если есть модальный глагол, он встаёт последним, после инфинитива: …, weil ich arbeiten muss. Отделяемая приставка в придаточном не отделяется: …, dass sie eine Torte mitbringt.\nКогда придаточное с wenn стоит первым, главное предложение начинается сразу с глагола: Wenn ich Zeit habe, komme ich gern.": "weil (çünki), dass (ki) və wenn (əgər, nə vaxt) bağlayıcılarından sonra təsriflənən feil budaq cümlənin lap sonuna keçir, bağlayıcıdan əvvəl isə həmişə vergül qoyulur.\nƏgər budaq cümlədə Perfekt varsa, sona haben və ya sein gedir: …, weil ich gearbeitet habe. Modal feil varsa, o, məsdərdən sonra ən axırda durur: …, weil ich arbeiten muss. Budaq cümlədə ayrılan prefiks ayrılmır: …, dass sie eine Torte mitbringt.\nwenn ilə budaq cümlə birinci gələndə, baş cümlə dərhal feillə başlayır: Wenn ich Zeit habe, komme ich gern.",
  "если, когда": "əgər, nə vaxt",
  "Я не могу прийти, потому что я болен.": "Gələ bilmirəm, çünki xəstəyəm.",
  "Эмиль сказал, что с нетерпением ждёт праздника.": "Emil dedi ki, şənliyi səbirsizliklə gözləyir.",
  "Если будет хорошая погода, мы пожарим на гриле в саду.": "Hava yaxşı olsa, bağda qrildə bişirəcəyik.",
  "праздник": "şənlik",
  "Silvester — ночь с 31 декабря на 1 января; Weihnachten — Рождество, 24–26 декабря.": "Silvester — 31 dekabrdan 1 yanvara keçən gecə; Weihnachten — Milad bayramı, 24–26 dekabr.",
