  "Привет, Эмиль! В субботу я праздную свой день рождения. Придёшь?": "Salam, Emil! Şənbə günü ad günümü qeyd edirəm. Gələrsən?",
  "tanzen — не движение из точки А в точку Б, поэтому Perfekt с haben.": "tanzen — A nöqtəsindən B nöqtəsinə hərəkət deyil, ona görə də Perfekt haben ilə düzəlir.",
