  "Я этим займусь.": "Mən bununla məşğul olacağam.",
  "признание диплома": "diplomun tanınması",
  "sich kümmern um + Akkusativ — заниматься чем-то.": "sich kümmern um + Akkusativ — bir işlə məşğul olmaq.",
  "Клиенты жалуются на позднюю доставку.": "Müştərilər gecikmiş çatdırılmadan şikayət edirlər.",
  "Я подаю заявку на новую должность.": "Mən yeni vəzifəyə müraciət edirəm.",
  "Кто отвечает за склад?": "Anbara kim cavabdehdir?",
