  "Курсы повышения квалификации пройдут в мае, и их оплачивает фирма.": "İxtisasartırma kursları mayda keçiriləcək və onların pulunu firma ödəyir.",
  "Я занимаюсь новыми заказами.": "Mən yeni sifarişlərlə məşğul oluram.",
  "Поиск квартиры и договор": "Mənzil axtarışı və müqavilə",
  "В этом уровне ты научишься искать квартиру в Германии: читать объявление, звонить арендодателю, задавать вопросы на просмотре и понимать договор аренды. Главная грамматика — относительные придаточные (der, den, dem, der, denen) и относительные придаточные с предлогом.": "Bu səviyyədə Almaniyada mənzil axtarmağı öyrənəcəksən: elanı oxumaq, ev sahibinə zəng etmək, baxışda sual vermək və kirayə müqaviləsini başa düşmək. Əsas qrammatika — Relativsatz budaq cümlələri (der, den, dem, der, denen) və sözönü ilə işlənən Relativsatz budaq cümlələri.",
  "Позвонить по объявлению и договориться о просмотре квартиры": "Elana görə zəng etmək və mənzilə baxış barədə razılaşmaq",
  "Спросить про аренду, коммунальные расходы, залог и срок расторжения договора": "Kirayə, kommunal xərclər, depozit və müqavilənin ləğvi müddəti haqqında soruşmaq",
  "Строить относительные придаточные в Nominativ, Akkusativ и Dativ": "Nominativ, Akkusativ və Dativ-də Relativsatz budaq cümlələri qurmaq",
  "Объяснять, о какой квартире или о каком человеке идёт речь: die Wohnung, in der wir wohnen": "Hansı mənzildən və ya hansı adamdan söhbət getdiyini izah etmək: die Wohnung, in der wir wohnen",
  "Мы ищем квартиру с тремя комнатами.": "Biz üç otaqlı mənzil axtarırıq.",
  "поиск квартиры": "mənzil axtarışı",
  "Поиск квартиры длится у нас уже четыре месяца.": "Mənzil axtarışımız artıq dörd aydır davam edir.",
