  "Старые жильцы выезжают в конце июня.": "Köhnə kirayəçilər iyunun sonunda köçüb gedirlər.",
  "риелтор": "rieltor",
  "Для этой квартиры нам не нужен риелтор.": "Bu mənzil üçün bizə rieltor lazım deyil.",
  "Договор аренды мы подпишем на следующей неделе.": "Kirayə müqaviləsini gələn həftə imzalayacağıq.",
  "Аренду мы платим всегда в начале месяца.": "Kirayəni həmişə ayın əvvəlində ödəyirik.",
