  "Через четыре месяца": "Dörd aydan sonra",
  "Через четыре дня": "Dörd gündən sonra",
  "Ваши документы в полном порядке. Ответ вы получите через четыре недели.": "Sənədləriniz tam qaydasındadır. Cavabı dörd həftədən sonra alacaqsınız.",
  "К заявке на работу всегда прилагают резюме — der Lebenslauf.": "İşə müraciətə həmişə tərcümeyi-hal əlavə olunur — der Lebenslauf.",
  "Медиа и интернет": "Media və internet",
  "Здесь ты научишься решать проблемы с интернетом и телефоном, разговаривать со службой поддержки и спокойно высказывать своё мнение о том, что читаешь в сети. Главная грамматика — косвенные вопросы (Ich weiß nicht, ob …) и глаголы мнения (sagen, meinen, finden, behaupten), плюс пассив, без которого не понять ни одного письма от провайдера.": "Burada internet və telefonla bağlı problemləri həll etməyi, müştəri xidməti ilə danışmağı və şəbəkədə oxuduqların barədə fikrini rahatca bildirməyi öyrənəcəksən. Əsas qrammatika — dolayı suallar (Ich weiß nicht, ob …) və fikir feilləri (sagen, meinen, finden, behaupten), üstəlik passiv, onsuz provayderdən gələn heç bir məktubu başa düşmək olmur.",
  "Задавать вежливые косвенные вопросы: Können Sie mir sagen, wann …": "Nəzakətli dolayı suallar vermək: Können Sie mir sagen, wann …",
  "Объяснить проблему с интернетом и договориться о визите техника": "İnternet problemini izah etmək və texnikin gəlişi barədə razılaşmaq",
  "Высказать мнение: Ich finde / Ich glaube / Meiner Meinung nach …": "Fikrini bildirmək: Ich finde / Ich glaube / Meiner Meinung nach …",
  "Понимать пассив в счетах и письмах: Die Daten werden gespeichert.": "Hesablarda və məktublarda passivi başa düşmək: Die Daten werden gespeichert.",
