  "Отопление": "İsitmə",
  "Стиральную машину": "Paltaryuyan maşın",
  "Окно": "Pəncərə",
  "Отопление починили в понедельник. Теперь снова тепло.": "İsitməni bazar ertəsi təmir etdilər. İndi yenə istidir.",
  "Старые батарейки нельзя просто выбрасывать.": "Köhnə batareyaları sadəcə atmaq olmaz.",
  "После модального глагола стоит инфинитив: darf man nicht wegwerfen.": "Modal feildən sonra məsdər gəlir: darf man nicht wegwerfen.",
