  "Мы хотим экономить электричество.": "Biz elektrikə qənaət etmək istəyirik.",
  "Отопление, к сожалению, не работает.": "İsitmə, təəssüf ki, işləmir.",
  "Здесь ничего не выбрасывают.": "Burada heç nə atmırlar.",
  "Alte Geräte — множественное число в Präteritum: wurden ... abgeholt.": "Alte Geräte — Präteritum-da cəm: wurden ... abgeholt.",
  "Счёт за электричество": "Elektrik hesabı",
  "Эмиль, пришёл счёт за электричество. Нам придётся доплатить.": "Emil, elektrik hesabı gəlib. Əlavə ödəməli olacağıq.",
  "И сколько же?": "Bəs nə qədər?",
  "Двести сорок евро. Зимой расход сильно вырос.": "İki yüz qırx avro. Qışda sərf xeyli artıb.",
  "Неудивительно. Старый холодильник так и не заменили.": "Təəccüblü deyil. Köhnə soyuducunu elə dəyişmədilər də.",
  "И окна не меняли уже двадцать лет.": "Pəncərələri də artıq iyirmi ildir dəyişmirlər.",
  "Завтра поговорю с домоуправлением. Может быть, наконец что-то сделают.": "Sabah ev idarəsi ilə danışacağam. Bəlkə nəhayət nəsə edərlər.",
  "А пока будем экономить сами. По вечерам можно меньше топить.": "Hələlik isə özümüz qənaət edərik. Axşamlar az qızdırmaq olar.",
  "И правильно проветривать: три раза коротко, а не целый день.": "Və düzgün havalandırmaq: üç dəfə qısa, bütün gün yox.",
  "Точно. И подержанную технику мы больше покупать не будем.": "Doğrudur. İşlənmiş texnikanı da bir daha almayacağıq.",
  "Согласен. В следующем году счёт, надеюсь, будет меньше.": "Razıyam. Gələn il hesab, ümid edirəm, daha az olacaq.",
  "Первый разговор с домоуправлением": "Ev idarəsi ilə ilk söhbət",
  "Ты только что въехал с семьёй в новую квартиру. Мия из домоуправления показывает тебе двор. Спроси, куда идёт какой мусор, где сдавать бутылки с пфандом и когда вывозят макулатуру. Скажи, что отопление в ванной было холодным, и узнай, чинили ли его. В конце поблагодари и попрощайся.": "Sən ailənlə birlikdə təzəcə yeni mənzilə köçmüsən. Ev idarəsindən Mia sənə həyəti göstərir. Soruş ki, hansı zibil hara gedir, pfandlı butulkaları harada təhvil vermək olar və kağız tullantılarını nə vaxt aparırlar. De ki, hamamda isitmə soyuq idi, və öyrən ki, onu təmir ediblərmi. Sonda təşəkkür et və sağollaş.",
  "Когда вывозят остаточный мусор?": "Qalıq zibili nə vaxt aparırlar?",
  "Отопление в ванной было холодным.": "Hamamdakı isitmə soyuq idi.",
  "Отопление уже починили?": "İsitməni artıq təmir ediblər?",
  "Мы хотели бы экономить электричество.": "Biz elektrikə qənaət etmək istərdik.",
  "Большое спасибо за помощь! До свидания!": "Kömək üçün çox sağ olun! Xudahafiz!",
  "Добрый день! Вы ведь новенький в доме? Я Мия из домоуправления.": "Günortanız xeyir! Siz binada təzəsiniz, elə deyil? Mən ev idarəsindən Miayam.",
  "Прекрасно. Здесь во дворе стоят мусорные баки. Есть вопросы по сортировке мусора?": "Əla. Burada, həyətdə zibil qabları durur. Zibilin çeşidlənməsi ilə bağlı sualınız var?",
  "Фрукты, овощи и остатки еды идут в органические отходы, бумага — в макулатуру. А бутылки?": "Meyvə, tərəvəz və yemək qalıqları üzvi tullantılara gedir, kağız isə kağız tullantılarına. Bəs butulkalar?",
  "Именно, к автомату приёма бутылок в супермаркете. Кстати, остаточный мусор вывозят по вторникам.": "Məhz, supermarketdəki butulka qəbulu avtomatına. Yeri gəlmişkən, qalıq zibili çərşənbə axşamları aparırlar.",
  "Макулатуру — раз в две недели, всегда по пятницам. В остальном в квартире всё в порядке?": "Kağız tullantılarını — iki həftədən bir, həmişə cümə günləri. Qalan məsələlərdə mənzildə hər şey qaydasındadır?",
  "Отопление починили на прошлой неделе. Если оно снова будет холодным, позвоните мне, пожалуйста.": "İsitməni keçən həftə təmir ediblər. Əgər yenə soyuq olsa, xahiş edirəm, mənə zəng edin.",
  "Очень разумно. Тогда хорошего вам дня. До свидания!": "Çox ağıllı qərardır. Onda gününüz xeyirli olsun. Xudahafiz!",
  "Нашу квартиру отремонтировали летом.": "Bizim mənzili yayda təmir ediblər.",
  "renovieren → renoviert, без ge-.": "renovieren → renoviert, ge- olmadan.",
