  "Отопление в доме полностью заменили в августе.": "Binadakı isitmə sistemi avqustda tamamilə dəyişdirildi.",
  "Деньги, банк и договоры": "Pul, bank və müqavilələr",
  "В этом уровне ты разберёшься с деньгами, банком и договорами: откроешь счёт, поймёшь комиссии и сроки, научишься расторгать договор и спокойно говорить о планах. Главная грамматика — Futur I (werden + Infinitiv) для планов и предположений и реальные условные предложения с wenn.": "Bu səviyyədə pul, bank və müqavilələrdən baş çıxaracaqsan: hesab açacaqsan, komissiyaları və müddətləri başa düşəcəksən, müqaviləni ləğv etməyi və planlardan rahat danışmağı öyrənəcəksən. Əsas qrammatika — planlar və ehtimallar üçün Futur I (werden + Infinitiv) və wenn ilə real şərt cümlələri.",
  "Открыть счёт в банке и спросить про комиссии и карту": "Bankda hesab açmaq və komissiyalarla kart barədə soruşmaq",
  "Разобраться в договоре: срок действия, срок расторжения, платежи": "Müqavilədən baş çıxarmaq: qüvvədə olma müddəti, ləğv müddəti, ödənişlər",
  "Говорить о планах и предположениях через Futur I": "Futur I ilə planlardan və ehtimallardan danışmaq",
  "Строить условия с wenn: Wenn ich Zeit habe, gehe ich zur Bank": "wenn ilə şərtlər qurmaq: Wenn ich Zeit habe, gehe ich zur Bank",
  "счёт (в банке)": "hesab (bankda)",
  "Я хочу открыть счёт в немецком банке.": "Mən alman bankında hesab açmaq istəyirəm.",
  "расчётный (текущий) счёт": "cari hesab",
