  "четыре года": "dörd il",
  "восемь лет": "səkkiz il",
  "Ваш кредит стоит 180 евро в месяц. Срок действия — четыре года.": "Kreditiniz ayda 180 avroya başa gəlir. Qüvvədə olma müddəti — dörd il.",
  "du → wirst, а инфинитив gehen уходит в конец.": "du → wirst, gehen məsdəri isə sona gedir.",
  "Новую машину мы сейчас себе позволить не можем.": "İndi yeni maşına imkanımız çatmır.",
  "sich etwas leisten können — мочь себе что-то позволить.": "sich etwas leisten können — nəyəsə maddi imkanı çatmaq.",
  "Чувства и конфликты": "Hisslər və münaqişələr",
  "На этом уровне ты научишься называть свои чувства и спокойно улаживать конфликты — с соседом, с коллегой, в семье. Главная грамматика: Konjunktiv II (hätte, wäre, würde) для нереальных условий и мягкие советы через «An deiner Stelle würde ich …».": "Bu səviyyədə öz hisslərini adlandırmağı və münaqişələri sakitcə həll etməyi öyrənəcəksən — qonşu ilə, həmkarla, ailədə. Əsas qrammatika: qeyri-real şərtlər üçün Konjunktiv II (hätte, wäre, würde) və «An deiner Stelle würde ich …» vasitəsilə yumşaq məsləhətlər.",
  "Назвать своё состояние: wütend, enttäuscht, genervt, gestresst": "Öz vəziyyətini adlandır: wütend, enttäuscht, genervt, gestresst",
  "Построить нереальное условие: Wenn ich mehr Zeit hätte, würde ich …": "Qeyri-real şərt qur: Wenn ich mehr Zeit hätte, würde ich …",
  "Дать совет мягко: An deiner Stelle würde ich … / Du solltest …": "Məsləhəti yumşaq ver: An deiner Stelle würde ich … / Du solltest …",
  "Уладить конфликт: признать ошибку, извиниться и предложить компромисс": "Münaqişəni həll et: səhvi boynuna al, üzr istə və kompromis təklif et",
  "чувство": "hiss",
  "Говорить о чувствах не всегда легко.": "Hisslər haqqında danışmaq həmişə asan olmur.",
