  "Ссора с соседом длилась долго.": "Qonşu ilə dava uzun çəkdi.",
  "ссориться": "dalaşmaq, mübahisə etmək",
  "Мы ссоримся редко, но в этот раз было громко.": "Biz nadir hallarda dalaşırıq, amma bu dəfə səs-küylü oldu.",
