  "в 15:45": "15:45-də",
  "Экскурсия начинается в четверть четвёртого у входа. Пожалуйста, будьте пунктуальны.": "Ekskursiya üçü on beş dəqiqə keçmiş girişin yanında başlayır. Zəhmət olmasa, vaxtında gəlin.",
  "vor zwei Jahren — «два года назад». seit означает длящееся действие, in zwei Jahren — будущее.": "vor zwei Jahren — «iki il əvvəl». seit davam edən hərəkəti bildirir, in zwei Jahren — gələcəyi.",
  "Общество и интеграция": "Cəmiyyət və inteqrasiya",
  "Этот уровень — про жизнь в немецком обществе: ведомства и документы, соседи, школа дочери, клубы и волонтёрство, права и обязанности. Грамматика здесь взрослая и очень полезная: устойчивые связки «существительное + глагол» (eine Entscheidung treffen, einen Antrag stellen), превращение глагола в существительное (beim Einkaufen, zum Lernen) и Genitiv в устойчивых оборотах (wegen des Wetters, trotz der Probleme).": "Bu səviyyə alman cəmiyyətində yaşamaqdan bəhs edir: idarələr və sənədlər, qonşular, qızın məktəbi, klublar və könüllü iş, hüquqlar və vəzifələr. Qrammatika burada ciddi və çox faydalıdır: sabit «isim + feil» birləşmələri (eine Entscheidung treffen, einen Antrag stellen), feilin ismə çevrilməsi (beim Einkaufen, zum Lernen) və sabit ifadələrdə Genitiv (wegen des Wetters, trotz der Probleme).",
  "Объясниться в ведомстве: подать заявление, записаться на приём, принести документы": "İdarədə dil tapmaq: ərizə vermək, qəbula yazılmaq, sənədləri gətirmək",
  "Использовать связки eine Entscheidung treffen, eine Frage stellen, eine Rolle spielen": "eine Entscheidung treffen, eine Frage stellen, eine Rolle spielen birləşmələrini işlətmək",
