  "Строить Genitiv после wegen, trotz, während и в оборотах вроде die Anerkennung des Abschlusses": "wegen, trotz, während sözönülərindən sonra və die Anerkennung des Abschlusses kimi ifadələrdə Genitiv qurmaq",
